{
  "name": "Master Finance - Gestão de Fluxo de Caixa",
  "description": "Assistente especializado em gestão de fluxo de caixa pessoal com processamento de linguagem natural e análise de risco.",
  "requestFramePermissions": []
}

import { GoogleGenAI, Type } from "@google/genai";
import { FinanceAnalysis, FinanceItem } from "../types";

const SYSTEM_INSTRUCTION_ANALYSIS = `
Você é o "Master Finance", assistente de gestão de fluxo de caixa.
Sua função é analisar dados financeiros e gerar um Resumo Executivo e Status de Saúde.

LOGICA DE CÁLCULO RIGOROSA:
1. Gasto Total = Soma de 'house' (Casa) + 'fixed' (Mensais).
2. Entradas (Trabalho) = Categoria 'work'. Representa o salário líquido.
3. Entradas (Terceiros) = Categoria 'thirdParty'. Tratadas como compensação (ex: amigo pagando parte da fatura). NÃO somar como renda disponível.
4. Percentual de Comprometimento = Gasto Total / Entradas (Trabalho).
5. ALERTA DE RISCO: Se Gasto Total > 80% das Entradas (Trabalho), o campo 'alertMessage' DEVE ser exatamente: "**⚠️ ALERTA DE RISCO: Orçamento comprometido acima de 80%!**".

STATUS:
- Saudável: Comprometimento <= 0.5
- Atenção: Comprometimento > 0.5 e <= 0.8
- Crítico: Comprometimento > 0.8

TOM DE VOZ: Profissional, direto, objetivo e levemente analítico.
RETORNE APENAS JSON.
`;

const SYSTEM_INSTRUCTION_PARSER = `
Você é o processador de dados do "Master Finance".
Sua tarefa é extrair itens financeiros de um texto natural e categorizá-los.

CATEGORIAS:
- house: Contas da casa (aluguel, água, luz, internet).
- fixed: Contas mensais/fixas (impostos, contabilidade, carro, celular, assinaturas).
- work: Salários, rendas fixas, pagamentos recebidos por trabalho.
- thirdParty: Valores de terceiros (amigos pagando dívidas, compras emprestadas no cartão).

Regras:
1. Identifique descrição e valor.
2. Identifique parcelas se houver (ex: "3 de 10").
3. Retorne um array de objetos JSON.
`;

export async function parseNaturalLanguage(text: string): Promise<Partial<FinanceItem>[]> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Extraia os dados deste texto: "${text}"`,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION_PARSER,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            description: { type: Type.STRING },
            value: { type: Type.NUMBER },
            category: { type: Type.STRING, enum: ['house', 'fixed', 'work', 'thirdParty'] },
            paidInstallments: { type: Type.NUMBER, nullable: true },
            totalInstallments: { type: Type.NUMBER, nullable: true },
          },
          required: ["description", "value", "category"]
        }
      }
    }
  });
  return JSON.parse(response.text.trim());
}

export async function analyzeFinanceData(items: FinanceItem[]): Promise<FinanceAnalysis> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `Analise estes dados: ${JSON.stringify(items)}`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: prompt,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION_ANALYSIS,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          summary: {
            type: Type.OBJECT,
            properties: {
              totalWorkIncome: { type: Type.NUMBER },
              totalExpenses: { type: Type.NUMBER },
              remainingBalance: { type: Type.NUMBER },
              compromisePercentage: { type: Type.NUMBER },
              status: { type: Type.STRING },
              alertMessage: { type: Type.STRING, nullable: true }
            },
            required: ["totalWorkIncome", "totalExpenses", "remainingBalance", "compromisePercentage", "status"]
          }
        },
        required: ["summary"]
      }
    }
  });

  const data = JSON.parse(response.text.trim());
  return {
    ...data,
    analysisDate: new Date().toLocaleDateString('pt-BR')
  };
}

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  Plus,
  AlertTriangle, 
  Calculator,
  LayoutGrid,
  History,
  CheckCircle2,
  Clock,
  FileSpreadsheet,
  Copy,
  Edit2,
  Check,
  X,
  Sparkles,
  ArrowRightLeft
} from 'lucide-react';
import { FinanceAnalysis, FinanceItem, HealthStatus, Ledger } from './types';
import { analyzeFinanceData, parseNaturalLanguage } from './services/geminiService';
import ExpenseTable from './components/ExpenseTable';

const App: React.FC = () => {
  const createInitialLedger = (): Ledger => ({
    id: 'ledger-' + Date.now(),
    name: 'Mês Atual',
    items: []
  });

  const [ledgers, setLedgers] = useState<Ledger[]>([createInitialLedger()]);
  const [activeLedgerId, setActiveLedgerId] = useState<string>(ledgers[0].id);
  const [analysis, setAnalysis] = useState<FinanceAnalysis | null>(null);
  const [loading, setLoading] = useState(false);
  const [parsing, setParsing] = useState(false);
  const [nlpText, setNlpText] = useState('');

  const [editingLedgerId, setEditingLedgerId] = useState<string | null>(null);
  const [tempLedgerName, setTempLedgerName] = useState('');
  const editInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const exists = ledgers.some(l => l.id === activeLedgerId);
    if (!exists && ledgers.length > 0) {
      setActiveLedgerId(ledgers[0].id);
    }
  }, [ledgers, activeLedgerId]);

  const activeLedger = useMemo(() => {
    return ledgers.find(l => l.id === activeLedgerId) || ledgers[0];
  }, [ledgers, activeLedgerId]);

  const items = activeLedger?.items || [];

  const [desc, setDesc] = useState('');
  const [val, setVal] = useState('');
  const [paidCount, setPaidCount] = useState('');
  const [totalCount, setTotalCount] = useState('');
  const [cat, setCat] = useState<'house' | 'fixed' | 'work' | 'thirdParty'>('house');

  const handleValueChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const digits = e.target.value.replace(/\D/g, '');
    if (!digits) {
      setVal('');
      return;
    }
    const amount = parseInt(digits) / 100;
    setVal(new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(amount));
  };

  const addItem = () => {
    const numericValue = parseFloat(val.replace(/[^\d,]/g, '').replace(',', '.')) || 0;
    if (!desc || numericValue <= 0) return;

    const newItem: FinanceItem = {
      id: Math.random().toString(36).substr(2, 9),
      description: desc,
      value: numericValue,
      paidInstallments: paidCount ? parseInt(paidCount) : undefined,
      totalInstallments: totalCount ? parseInt(totalCount) : undefined,
      category: cat,
      status: 'pending'
    };

    setLedgers(prev => prev.map(l => l.id === activeLedgerId ? { ...l, items: [...l.items, newItem] } : l));
    setDesc(''); setVal(''); setPaidCount(''); setTotalCount('');
  };

  const processNlp = async () => {
    if (!nlpText.trim()) return;
    setParsing(true);
    try {
      const parsedItems = await parseNaturalLanguage(nlpText);
      const newFinanceItems: FinanceItem[] = parsedItems.map(item => ({
        id: Math.random().toString(36).substr(2, 9),
        description: item.description || 'Sem descrição',
        value: item.value || 0,
        category: item.category as any || 'house',
        paidInstallments: item.paidInstallments,
        totalInstallments: item.totalInstallments,
        status: 'pending'
      }));

      setLedgers(prev => prev.map(l => l.id === activeLedgerId ? { ...l, items: [...l.items, ...newFinanceItems] } : l));
      setNlpText('');
    } catch (err) {
      alert("Erro ao processar texto. Tente descrever os valores de forma mais clara.");
    } finally {
      setParsing(false);
    }
  };

  const removeItem = (id: string) => {
    setLedgers(prev => prev.map(l => l.id === activeLedgerId ? { ...l, items: l.items.filter(i => i.id !== id) } : l));
  };

  const updateItem = (id: string, updates: Partial<FinanceItem>) => {
    setLedgers(prev => prev.map(l => l.id === activeLedgerId ? { ...l, items: l.items.map(i => i.id === id ? { ...i, ...updates } : i) } : l));
  };

  const runAnalysis = async () => {
    if (items.length === 0) return;
    setLoading(true);
    try {
      const result = await analyzeFinanceData(items);
      setAnalysis(result);
    } catch (err) {
      alert('Erro na análise Master Finance.');
    } finally {
      setLoading(false);
    }
  };

  const fmt = (val: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  return (
    <div className="min-h-screen bg-slate-50 font-sans text-slate-900 selection:bg-blue-100">
      <nav className="bg-slate-900 text-white h-16 flex items-center px-8 sticky top-0 z-50 shadow-2xl">
        <div className="flex items-center gap-4">
          <div className="w-10 h-10 bg-blue-600 rounded-lg flex items-center justify-center font-black text-lg shadow-lg">MF</div>
          <div>
            <h1 className="text-sm font-black tracking-tighter uppercase leading-none">Master Finance</h1>
            <p className="text-blue-400 font-mono text-[9px] tracking-[0.3em] uppercase opacity-80">Gestão de Fluxo Rígida</p>
          </div>
        </div>
      </nav>

      {/* Tabs System */}
      <div className="bg-white border-b border-slate-200 sticky top-16 z-40 px-8 flex items-center gap-2 py-3 overflow-x-auto no-scrollbar">
        {ledgers.map(l => (
          <button 
            key={l.id}
            onClick={() => { setActiveLedgerId(l.id); setAnalysis(null); }}
            className={`px-5 py-2 text-[10px] font-black uppercase tracking-widest whitespace-nowrap transition-all rounded-md border ${activeLedgerId === l.id ? 'bg-slate-900 text-white border-slate-900 shadow-md' : 'bg-transparent text-slate-400 border-transparent hover:bg-slate-100'}`}
          >
            {l.name}
          </button>
        ))}
        <button 
          onClick={() => {
            const newL = createInitialLedger();
            setLedgers([...ledgers, newL]);
            setActiveLedgerId(newL.id);
          }}
          className="p-2 text-slate-400 hover:text-blue-600 transition-colors"
        >
          <Plus size={18} />
        </button>
      </div>

      <main className="max-w-6xl mx-auto p-8 space-y-8">

        {/* NLP Input Section */}
        <section className="bg-white border border-slate-200 shadow-sm rounded-xl overflow-hidden">
          <div className="bg-slate-50 px-6 py-3 border-b border-slate-100 flex items-center gap-2">
            <Sparkles size={14} className="text-blue-600" />
            <h2 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Comando Rápido (IA)</h2>
          </div>
          <div className="p-6 space-y-4">
            <textarea 
              value={nlpText}
              onChange={(e) => setNlpText(e.target.value)}
              placeholder="Ex: Paguei aluguel 1200, recebi 5000 do trabalho, recebi 200 do João p/ pagar cartão..."
              className="w-full h-24 bg-slate-50 border border-slate-200 rounded-lg p-4 text-sm focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 outline-none transition-all resize-none font-medium"
            />
            <div className="flex justify-end">
              <button 
                onClick={processNlp}
                disabled={parsing || !nlpText.trim()}
                className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 disabled:bg-slate-200 text-white text-[10px] font-black uppercase px-6 py-3 rounded-lg transition-all shadow-lg shadow-blue-500/20"
              >
                {parsing ? <div className="w-3 h-3 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : <Sparkles size={14} />}
                Processar e Lançar
              </button>
            </div>
          </div>
        </section>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
          <div className="lg:col-span-8 space-y-8">
            <ExpenseTable 
              title="🏠 Contas da Casa" icon="" type="expense" 
              items={items.filter(i => i.category === 'house')} 
              onRemove={removeItem} onUpdate={updateItem}
            />
            <ExpenseTable 
              title="📅 Contas Mensais / Fixas" icon="" type="expense" 
              items={items.filter(i => i.category === 'fixed')} 
              onRemove={removeItem} onUpdate={updateItem}
            />
            <ExpenseTable 
              title="📥 Entradas (Trabalho)" icon="" type="income" 
              items={items.filter(i => i.category === 'work')} 
              onRemove={removeItem} onUpdate={updateItem}
            />
            <ExpenseTable 
              title="💳 Entradas (Terceiros / Cartão)" icon="" type="neutral" 
              items={items.filter(i => i.category === 'thirdParty')} 
              onRemove={removeItem} onUpdate={updateItem}
            />
          </div>

          <div className="lg:col-span-4 space-y-6 sticky top-40">
            <button 
              onClick={runAnalysis}
              disabled={loading || items.length === 0}
              className="w-full bg-slate-900 text-white font-black py-5 rounded-xl uppercase text-[11px] tracking-[0.2em] shadow-2xl hover:bg-slate-800 hover:-translate-y-0.5 active:translate-y-0 disabled:bg-slate-300 transition-all flex items-center justify-center gap-3"
            >
              {loading ? <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : <Calculator size={20} />}
              Gerar Análise Master
            </button>

            {analysis && (
              <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
                <div className={`p-6 border-2 shadow-xl rounded-2xl ${
                  analysis.summary.status === 'Saudável' ? 'bg-emerald-50 border-emerald-200' : 
                  analysis.summary.status === 'Atenção' ? 'bg-amber-50 border-amber-200' : 'bg-rose-50 border-rose-200'
                }`}>
                  <span className="text-[10px] font-black uppercase text-slate-400 block mb-2 tracking-widest">Saúde Financeira</span>
                  <div className="flex justify-between items-end mb-4">
                    <h3 className={`text-2xl font-black uppercase tracking-tighter ${
                      analysis.summary.status === 'Saudável' ? 'text-emerald-700' : 
                      analysis.summary.status === 'Atenção' ? 'text-amber-700' : 'text-rose-700'
                    }`}>
                      {analysis.summary.status}
                    </h3>
                    <span className="text-lg font-mono font-black opacity-70">
                      {(analysis.summary.compromisePercentage * 100).toFixed(0)}%
                    </span>
                  </div>
                  <div className="w-full h-2 bg-slate-200/50 rounded-full overflow-hidden">
                    <div 
                      className={`h-full transition-all duration-1000 ease-out ${
                        analysis.summary.compromisePercentage > 0.8 ? 'bg-rose-500' : 
                        analysis.summary.compromisePercentage > 0.5 ? 'bg-amber-500' : 'bg-emerald-500'
                      }`}
                      style={{ width: `${Math.min(analysis.summary.compromisePercentage * 100, 100)}%` }}
                    />
                  </div>

                  {analysis.summary.alertMessage && (
                    <div className="mt-6 bg-white border border-rose-200 p-4 rounded-xl text-rose-700 text-[11px] font-bold leading-relaxed shadow-sm">
                      <div className="flex items-start gap-3">
                        <AlertTriangle size={18} className="shrink-0" />
                        <span dangerouslySetInnerHTML={{ __html: analysis.summary.alertMessage.replace(/\*\*/g, '') }} />
                      </div>
                    </div>
                  )}
                </div>

                <div className="bg-white border border-slate-200 p-6 space-y-6 shadow-sm rounded-2xl">
                  <div className="flex items-center gap-2 border-b border-slate-100 pb-3">
                    <History size={14} className="text-slate-400" />
                    <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Resumo Executivo</h4>
                  </div>
                  <div className="space-y-4">
                    <div className="flex justify-between items-center group">
                      <span className="text-[11px] font-bold text-slate-400 uppercase">Receita (Trabalho)</span>
                      <span className="font-mono font-black text-emerald-600 text-sm">{fmt(analysis.summary.totalWorkIncome)}</span>
                    </div>
                    <div className="flex justify-between items-center group">
                      <span className="text-[11px] font-bold text-slate-400 uppercase">Gastos Essenciais</span>
                      <span className="font-mono font-black text-rose-500 text-sm">{fmt(analysis.summary.totalExpenses)}</span>
                    </div>
                    <div className="pt-4 border-t border-slate-100 flex justify-between items-center">
                      <span className="text-[11px] font-black text-slate-900 uppercase tracking-tight">Sobrou no Caixa</span>
                      <span className={`font-mono text-lg font-black ${analysis.summary.remainingBalance >= 0 ? 'text-blue-600' : 'text-rose-600'}`}>
                        {fmt(analysis.summary.remainingBalance)}
                      </span>
                    </div>
                  </div>
                </div>

                <div className="bg-slate-900 text-white p-6 space-y-6 shadow-2xl rounded-2xl">
                  <div className="flex items-center gap-2 border-b border-slate-800 pb-3">
                    <ArrowRightLeft size={14} className="text-blue-400" />
                    <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Compensação de Terceiros</h4>
                  </div>
                  <div className="flex items-center justify-between">
                    <div>
                      <p className="text-[9px] font-bold text-slate-500 uppercase tracking-tighter mb-1">Total Identificado</p>
