};

export default App;

{
  "name": "Gestão Financeira - Controle de caixa",
  "description": "Sistema de gestão de fluxo de caixa pessoal com categorias e análise de saúde financeira.",
  "requestFramePermissions": []
}

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Plus,
  Calculator,
  LayoutGrid,
  TrendingUp,
  TrendingDown,
  Wallet,
  AlertCircle
} from 'lucide-react';
import { FinanceAnalysis, FinanceItem, HealthStatus, Ledger } from './types';
import { analyzeFinanceData } from './services/geminiService';
import ExpenseTable from './components/ExpenseTable';
import SummaryCard from './components/SummaryCard';

const App: React.FC = () => {
  const createInitialLedger = (): Ledger => ({
    id: 'ledger-' + Date.now(),
    name: 'Mês Atual',
    items: []
  });

  const [ledgers, setLedgers] = useState<Ledger[]>([createInitialLedger()]);
  const [activeLedgerId, setActiveLedgerId] = useState<string>(ledgers[0].id);
  const [analysis, setAnalysis] = useState<FinanceAnalysis | null>(null);
  const [loading, setLoading] = useState(false);

  const activeLedger = useMemo(() => {
    return ledgers.find(l => l.id === activeLedgerId) || ledgers[0];
  }, [ledgers, activeLedgerId]);

  const items = activeLedger?.items || [];

  const [desc, setDesc] = useState('');
  const [val, setVal] = useState('');
  const [cat, setCat] = useState<'house' | 'fixed' | 'work' | 'thirdParty'>('house');

  const totals = useMemo(() => {
    const income = items.filter(i => i.category === 'work').reduce((a, b) => a + b.value, 0);
    const expenses = items.filter(i => i.category === 'house' || i.category === 'fixed').reduce((a, b) => a + b.value, 0);
    return { income, expenses, balance: income - expenses };
  }, [items]);

  const handleValueChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const digits = e.target.value.replace(/\D/g, '');
    if (!digits) { setVal(''); return; }
    const amount = parseInt(digits) / 100;
    setVal(new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(amount));
  };

  const addItem = () => {
    const numericValue = parseFloat(val.replace(/[^\d,]/g, '').replace(',', '.')) || 0;
    if (!desc || numericValue <= 0) return;

    const newItem: FinanceItem = {
      id: Math.random().toString(36).substr(2, 9),
      description: desc,
      value: numericValue,
      category: cat,
      status: 'pending'
    };

    setLedgers(prev => prev.map(l => l.id === activeLedgerId ? { ...l, items: [...l.items, newItem] } : l));
    setDesc(''); setVal('');
  };

  const removeItem = (id: string) => {
    setLedgers(prev => prev.map(l => l.id === activeLedgerId ? { ...l, items: l.items.filter(i => i.id !== id) } : l));
  };

  const updateItem = (id: string, updates: Partial<FinanceItem>) => {
    setLedgers(prev => prev.map(l => l.id === activeLedgerId ? { ...l, items: l.items.map(i => i.id === id ? { ...i, ...updates } : i) } : l));
  };

  const runAnalysis = async () => {
    if (items.length === 0) return;
    setLoading(true);
    try {
      const result = await analyzeFinanceData(items);
      setAnalysis(result);
    } catch (err) {
      alert('Erro ao processar análise.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 pb-20">
      <nav className="bg-white border-b border-slate-200 h-16 flex items-center px-8 sticky top-0 z-50">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 bg-indigo-600 rounded flex items-center justify-center text-white">
            <Wallet size={18} />
          </div>
          <h1 className="font-bold text-lg tracking-tight">Gestão Financeira</h1>
        </div>
      </nav>

      <main className="max-w-6xl mx-auto p-8 space-y-8">
        {/* Dashboard Resumo */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <SummaryCard label="Entradas (Renda)" value={totals.income} type="income" icon={<TrendingUp size={20} />} />
          <SummaryCard label="Saídas (Despesas)" value={totals.expenses} type="expense" icon={<TrendingDown size={20} />} />
          <SummaryCard label="Saldo Disponível" value={totals.balance} type="balance" icon={<LayoutGrid size={20} />} />
        </div>

        {/* Formulário de Adição Rápida */}
        <section className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm flex flex-wrap gap-4 items-end">
          <div className="flex-1 min-w-[200px]">
            <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">Descrição</label>
