            <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">Categoria</label>
            <select value={cat} onChange={e => setCat(e.target.value as any)} className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-indigo-500/20 outline-none">
              <option value="house">🏠 Casa</option>
              <option value="fixed">📅 Mensal Fixa</option>
