            <ExpenseTable title="Contas Fixas" icon="📅" type="expense" items={items.filter(i => i.category === 'fixed')} onRemove={removeItem} onUpdate={updateItem} />
            <ExpenseTable title="Entradas de Trabalho" icon="📥" type="income" items={items.filter(i => i.category === 'work')} onRemove={removeItem} onUpdate={updateItem} />
