            >
              {loading ? <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : <Calculator size={18} />}
              Analisar Saúde Financeira
            </button>

            {analysis && (
              <div className="bg-white border border-slate-200 p-6 rounded-2xl shadow-sm animate-in fade-in slide-in-from-top-2">
                <div className="flex items-center gap-2 mb-4">
