import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  Plus,
  AlertTriangle, 
  Calculator,
  LayoutGrid,
  History,
  Trash2,
  X,
  Sparkles,
  ArrowRightLeft,
  Wallet
} from 'lucide-react';
import { FinanceAnalysis, FinanceItem, HealthStatus, Ledger } from './types';
import { analyzeFinanceData, parseNaturalLanguage } from './services/geminiService';
import ExpenseTable from './components/ExpenseTable';

const App: React.FC = () => {
  const createInitialLedger = (): Ledger => ({
    id: 'ledger-' + Date.now(),
    name: `Mês ${new Date().getMonth() + 1}/${new Date().getFullYear()}`,
    items: []
  });

  const [ledgers, setLedgers] = useState<Ledger[]>(() => {
    const saved = localStorage.getItem('mf_ledgers');
    return saved ? JSON.parse(saved) : [createInitialLedger()];
  });

  const [activeLedgerId, setActiveLedgerId] = useState<string>(ledgers[0]?.id || '');
  const [analysis, setAnalysis] = useState<FinanceAnalysis | null>(null);
  const [loading, setLoading] = useState(false);
  const [parsing, setParsing] = useState(false);
  const [nlpText, setNlpText] = useState('');

  useEffect(() => {
    localStorage.setItem('mf_ledgers', JSON.stringify(ledgers));
  }, [ledgers]);

  const activeLedger = useMemo(() => {
    return ledgers.find(l => l.id === activeLedgerId) || ledgers[0];
  }, [ledgers, activeLedgerId]);

  const items = activeLedger?.items || [];

  const addLedger = () => {
    const newL = createInitialLedger();
    setLedgers([...ledgers, newL]);
    setActiveLedgerId(newL.id);
    setAnalysis(null);
  };

  const removeLedger = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (ledgers.length === 1) return;
    const newLedgers = ledgers.filter(l => l.id !== id);
    setLedgers(newLedgers);
    if (activeLedgerId === id) {
      setActiveLedgerId(newLedgers[0].id);
    }
    setAnalysis(null);
  };

  const processNlp = async () => {
    if (!nlpText.trim()) return;
    setParsing(true);
    try {
      const parsedItems = await parseNaturalLanguage(nlpText);
      const newFinanceItems: FinanceItem[] = parsedItems.map(item => ({
        id: Math.random().toString(36).substr(2, 9),
        description: item.description || 'Sem descrição',
        value: item.value || 0,
        category: (item.category as any) || 'house',
        paidInstallments: item.paidInstallments,
        totalInstallments: item.totalInstallments,
        status: 'pending'
      }));

      setLedgers(prev => prev.map(l => l.id === activeLedgerId ? { ...l, items: [...l.items, ...newFinanceItems] } : l));
      setNlpText('');
    } catch (err) {
      alert("Erro ao processar texto pela IA.");
    } finally {
      setParsing(false);
    }
  };

  const removeItem = (id: string) => {
    setLedgers(prev => prev.map(l => l.id === activeLedgerId ? { ...l, items: l.items.filter(i => i.id !== id) } : l));
  };

  const updateItem = (id: string, updates: Partial<FinanceItem>) => {
    setLedgers(prev => prev.map(l => l.id === activeLedgerId ? { ...l, items: l.items.map(i => i.id === id ? { ...i, ...updates } : i) } : l));
  };

  const runAnalysis = async () => {
    if (items.length === 0) return;
    setLoading(true);
    try {
      const result = await analyzeFinanceData(items);
      setAnalysis(result);
    } catch (err) {
      alert('Erro na análise Master Finance.');
    } finally {
      setLoading(false);
    }
  };

  const fmt = (val: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  return (
    <div className="min-h-screen bg-slate-50 font-sans text-slate-900 selection:bg-blue-100">
      {/* Header Master Finance */}
      <nav className="bg-slate-900 text-white h-16 flex items-center px-8 sticky top-0 z-50 shadow-2xl">
        <div className="flex items-center gap-4">
          <div className="w-10 h-10 bg-blue-600 rounded-lg flex items-center justify-center font-black text-lg shadow-lg">MF</div>
          <div>
            <h1 className="text-sm font-black tracking-tighter uppercase leading-none">Master Finance</h1>
            <p className="text-blue-400 font-mono text-[9px] tracking-[0.3em] uppercase opacity-80">Arquitetura de Fluxo de Caixa</p>
          </div>
        </div>
      </nav>

      {/* Tabs with X button */}
      <div className="bg-white border-b border-slate-200 sticky top-16 z-40 px-8 flex items-center gap-2 py-3 overflow-x-auto no-scrollbar">
        {ledgers.map(l => (
          <div 
            key={l.id}
            onClick={() => { setActiveLedgerId(l.id); setAnalysis(null); }}
            className={`group relative flex items-center gap-2 px-4 py-2 text-[10px] font-black uppercase tracking-widest whitespace-nowrap transition-all rounded-md border cursor-pointer ${activeLedgerId === l.id ? 'bg-slate-900 text-white border-slate-900 shadow-md' : 'bg-transparent text-slate-400 border-transparent hover:bg-slate-100'}`}
          >
            <span>{l.name}</span>
            {ledgers.length > 1 && (
              <button 
                onClick={(e) => removeLedger(e, l.id)}
                className={`p-0.5 rounded-full hover:bg-rose-500 hover:text-white transition-colors ${activeLedgerId === l.id ? 'text-slate-500' : 'text-slate-300'}`}
              >
                <X size={12} />
              </button>
            )}
          </div>
        ))}
        <button 
          onClick={addLedger}
          className="p-2 text-slate-400 hover:text-blue-600 transition-colors"
          title="Nova Aba"
        >
          <Plus size={18} />
        </button>
      </div>

      <main className="max-w-6xl mx-auto p-8 space-y-8">

        {/* IA Input Section */}
        <section className="bg-white border border-slate-200 shadow-sm rounded-xl overflow-hidden">
          <div className="bg-slate-50 px-6 py-3 border-b border-slate-100 flex items-center gap-2">
            <Sparkles size={14} className="text-blue-600" />
            <h2 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Comando Rápido (IA)</h2>
          </div>
          <div className="p-6 space-y-4">
            <textarea 
              value={nlpText}
              onChange={(e) => setNlpText(e.target.value)}
              placeholder="Descreva suas movimentações: 'Paguei 1500 de aluguel, recebi 4000 de salário, João me deu 100 pra pagar a net...'"
              className="w-full h-24 bg-slate-50 border border-slate-200 rounded-lg p-4 text-sm focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 outline-none transition-all resize-none font-medium"
            />
            <div className="flex justify-end">
              <button 
                onClick={processNlp}
                disabled={parsing || !nlpText.trim()}
                className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 disabled:bg-slate-200 text-white text-[10px] font-black uppercase px-6 py-3 rounded-lg transition-all shadow-lg shadow-blue-500/20"
              >
                {parsing ? <div className="w-3 h-3 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : <Sparkles size={14} />}
                Lançar na Planilha
              </button>
            </div>
          </div>
        </section>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
          <div className="lg:col-span-8 space-y-8">
            <ExpenseTable 
              title="🏠 Contas da Casa" icon="" type="expense" 
              items={items.filter(i => i.category === 'house')} 
              onRemove={removeItem} onUpdate={updateItem}
            />
            <ExpenseTable 
              title="📅 Contas Mensais / Fixas" icon="" type="expense" 
              items={items.filter(i => i.category === 'fixed')} 
              onRemove={removeItem} onUpdate={updateItem}
            />
            <ExpenseTable 
              title="📥 Entradas (Trabalho)" icon="" type="income" 
              items={items.filter(i => i.category === 'work')} 
              onRemove={removeItem} onUpdate={updateItem}
            />
            <ExpenseTable 
              title="💳 Entradas (Terceiros / Cartão)" icon="" type="neutral" 
              items={items.filter(i => i.category === 'thirdParty')} 
              onRemove={removeItem} onUpdate={updateItem}
            />
          </div>

          <div className="lg:col-span-4 space-y-6 sticky top-40">
            <button 
              onClick={runAnalysis}
              disabled={loading || items.length === 0}
              className="w-full bg-slate-900 text-white font-black py-5 rounded-xl uppercase text-[11px] tracking-[0.2em] shadow-2xl hover:bg-slate-800 hover:-translate-y-0.5 active:translate-y-0 disabled:bg-slate-300 transition-all flex items-center justify-center gap-3"
            >
              {loading ? <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : <Calculator size={20} />}
              Executar Análise Master
            </button>

            {analysis && (
              <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
                {/* Saúde Card */}
                <div className={`p-6 border-2 shadow-xl rounded-2xl ${
                  analysis.summary.status === 'Saudável' ? 'bg-emerald-50 border-emerald-200' : 
                  analysis.summary.status === 'Atenção' ? 'bg-amber-50 border-amber-200' : 'bg-rose-50 border-rose-200'
                }`}>
                  <span className="text-[10px] font-black uppercase text-slate-400 block mb-2 tracking-widest">Saúde Financeira</span>
                  <div className="flex justify-between items-end mb-4">
                    <h3 className={`text-2xl font-black uppercase tracking-tighter ${
                      analysis.summary.status === 'Saudável' ? 'text-emerald-700' : 
                      analysis.summary.status === 'Atenção' ? 'text-amber-700' : 'text-rose-700'
                    }`}>
                      {analysis.summary.status}
                    </h3>
                    <span className="text-lg font-mono font-black opacity-70">
                      {(analysis.summary.compromisePercentage * 100).toFixed(0)}%
                    </span>
                  </div>
                  <div className="w-full h-2 bg-slate-200/50 rounded-full overflow-hidden">
                    <div 
                      className={`h-full transition-all duration-1000 ease-out ${
                        analysis.summary.compromisePercentage > 0.8 ? 'bg-rose-500' : 
                        analysis.summary.compromisePercentage > 0.5 ? 'bg-amber-500' : 'bg-emerald-500'
                      }`}
                      style={{ width: `${Math.min(analysis.summary.compromisePercentage * 100, 100)}%` }}
                    />
                  </div>

                  {analysis.summary.alertMessage && (
                    <div className="mt-6 bg-white border border-rose-200 p-4 rounded-xl text-rose-700 text-[11px] font-bold leading-relaxed shadow-sm">
                      <div className="flex items-start gap-3">
                        <AlertTriangle size={18} className="shrink-0" />
                        <span dangerouslySetInnerHTML={{ __html: analysis.summary.alertMessage.replace(/\*\*/g, '') }} />
                      </div>
                    </div>
                  )}
                </div>

                {/* Resumo Card */}
                <div className="bg-white border border-slate-200 p-6 space-y-6 shadow-sm rounded-2xl">
                  <div className="flex items-center gap-2 border-b border-slate-100 pb-3">
                    <History size={14} className="text-slate-400" />
                    <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Resumo do Caixa</h4>
                  </div>
                  <div className="space-y-4">
                    <div className="flex justify-between items-center">
                      <span className="text-[11px] font-bold text-slate-400 uppercase">Receita (Trabalho)</span>
                      <span className="font-mono font-black text-emerald-600 text-sm">{fmt(analysis.summary.totalWorkIncome)}</span>
                    </div>
                    <div className="flex justify-between items-center">
                      <span className="text-[11px] font-bold text-slate-400 uppercase">Gastos Genuínos</span>
                      <span className="font-mono font-black text-rose-500 text-sm">{fmt(analysis.summary.totalExpenses)}</span>
                    </div>
                    <div className="pt-4 border-t border-slate-100 flex justify-between items-center">
                      <span className="text-[11px] font-black text-slate-900 uppercase tracking-tight">Saldo Real</span>
                      <span className={`font-mono text-lg font-black ${analysis.summary.remainingBalance >= 0 ? 'text-blue-600' : 'text-rose-600'}`}>
                        {fmt(analysis.summary.remainingBalance)}
                      </span>
                    </div>
                  </div>
                </div>

                {/* Terceiros Card */}
                <div className="bg-slate-900 text-white p-6 space-y-4 shadow-2xl rounded-2xl">
                  <div className="flex items-center gap-2 border-b border-slate-800 pb-3">
                    <ArrowRightLeft size={14} className="text-blue-400" />
                    <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Compensações</h4>
                  </div>
                  <div className="flex items-center justify-between">
                    <div>
                      <p className="text-[9px] font-bold text-slate-500 uppercase tracking-tighter mb-1">Total de Terceiros</p>
                      <p className="text-lg font-mono font-black text-blue-400">
                        {fmt(items.filter(i => i.category === 'thirdParty').reduce((a, b) => a + b.value, 0))}
                      </p>
                    </div>
                    <div className="bg-slate-800 p-3 rounded-lg max-w-[120px]">
                      <p className="text-[8px] text-slate-400 uppercase leading-tight font-medium">Estes valores são neutros no cálculo de risco.</p>
                    </div>
                  </div>
                </div>
              </div>
            )}

            {!analysis && !loading && (
              <div className="bg-slate-100 border border-dashed border-slate-300 p-12 text-center rounded-2xl">
                <LayoutGrid size={32} className="mx-auto text-slate-300 mb-4 opacity-50" />
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Sem Análise Ativa</p>
              </div>
            )}
          </div>
        </div>
      </main>

      <footer className="max-w-6xl mx-auto px-8 py-12 border-t border-slate-200 mt-16 flex flex-col md:flex-row justify-between items-center gap-4 opacity-40">
        <div className="flex items-center gap-3">
          <div className="w-6 h-6 bg-slate-900 rounded flex items-center justify-center font-black text-[10px] text-white">MF</div>
          <span className="text-[10px] font-black uppercase tracking-widest">Master Finance Engine</span>
        </div>
        <div className="text-[9px] font-mono uppercase tracking-widest">© 2025 • Monitoramento de Saúde Financeira em Tempo Real</div>
      </footer>
    </div>
  );
};

export default App;

import React from 'react';
import { FinanceItem } from '../types';
import { Trash2 } from 'lucide-react';

interface ExpenseTableProps {
  title: string;
  items: FinanceItem[];
  icon: string;
  type: 'income' | 'expense' | 'neutral';
  onRemove: (id: string) => void;
  onUpdate: (id: string, updates: Partial<FinanceItem>) => void;
}

const ExpenseTable: React.FC<ExpenseTableProps> = ({ title, items, icon, type, onRemove, onUpdate }) => {
  const total = items.reduce((acc, curr) => acc + curr.value, 0);

  const fmt = (val: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  const handleValueChange = (id: string, rawValue: string) => {
    const digits = rawValue.replace(/\D/g, '');
    const numericValue = digits ? parseInt(digits) / 100 : 0;
    onUpdate(id, { value: numericValue });
  };

  return (
    <div className="bg-white border border-slate-200 shadow-sm overflow-hidden mb-6 rounded-sm">
      <div className="bg-slate-50 px-4 py-2 border-b border-slate-200 flex justify-between items-center">
        <h3 className="text-[11px] font-black text-slate-700 flex items-center gap-2 uppercase tracking-widest">
          <span>{icon}</span> {title}
        </h3>
        <span className={`text-xs font-mono font-bold ${type === 'expense' ? 'text-rose-600' : 'text-emerald-600'}`}>
          SUBTOTAL: {fmt(total)}
        </span>
      </div>
      <div className="overflow-x-auto">
        <table className="w-full text-[11px] font-mono border-collapse">
          <thead>
            <tr className="bg-slate-50/50 border-b border-slate-200 text-slate-400">
              <th className="px-4 py-2 text-left font-bold border-r border-slate-100">DESCRIÇÃO</th>
              <th className="px-4 py-2 text-right font-bold border-r border-slate-100 w-32">VALOR</th>
              <th className="px-4 py-2 text-center font-bold border-r border-slate-100 w-32">PARCELA ATUAL</th>
              <th className="px-4 py-2 text-center font-bold w-32">TOTAL PARCELAS</th>
              <th className="px-2 py-2 w-10"></th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {items.length > 0 ? (
              items.map((item) => (
                <tr key={item.id} className="hover:bg-blue-50/30 transition-colors group">
                  <td className="px-2 py-1 border-r border-slate-100">
                    <input 
                      type="text"
                      value={item.description}
                      onChange={(e) => onUpdate(item.id, { description: e.target.value })}
                      className="w-full bg-transparent px-2 py-1 outline-none text-slate-600 focus:bg-white focus:shadow-inner"
                    />
                  </td>
                  <td className="px-2 py-1 text-right border-r border-slate-100">
                    <input 
                      type="text"
                      value={fmt(item.value)}
                      onChange={(e) => handleValueChange(item.id, e.target.value)}
                      className={`w-full bg-transparent text-right px-2 py-1 font-bold outline-none focus:bg-white focus:shadow-inner ${type === 'expense' ? 'text-rose-500' : 'text-emerald-600'}`}
                    />
                  </td>
                  <td className="px-2 py-1 text-center border-r border-slate-100">
                    <input 
                      type="number"
                      min="0"
                      placeholder="-"
                      value={item.paidInstallments ?? ''}
                      onChange={(e) => onUpdate(item.id, { paidInstallments: e.target.value ? parseInt(e.target.value) : undefined })}
                      className="w-16 bg-slate-100 rounded text-center py-0.5 font-bold text-slate-500 outline-none focus:bg-blue-100 placeholder:text-slate-300"
                    />
                  </td>
                  <td className="px-2 py-1 text-center">
                    <input 
                      type="number"
                      min="1"
                      placeholder="-"
                      value={item.totalInstallments ?? ''}
                      onChange={(e) => onUpdate(item.id, { totalInstallments: e.target.value ? parseInt(e.target.value) : undefined })}
                      className="w-16 bg-slate-100 rounded text-center py-0.5 font-bold text-slate-500 outline-none focus:bg-blue-100 placeholder:text-slate-300"
                    />
                  </td>
                  <td className="px-2 py-1 text-center">
                    <button 
                      onClick={() => onRemove(item.id)}
                      className="text-slate-300 hover:text-rose-500 transition-all p-1.5 rounded-full hover:bg-rose-50"
                    >
                      <Trash2 size={12} />
                    </button>
                  </td>
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan={5} className="px-4 py-8 text-center text-slate-300 italic uppercase tracking-widest text-[9px]">
                  Nenhum registro encontrado nesta categoria
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default ExpenseTable;

