  const [loading, setLoading] = useState(false);
  const [parsing, setParsing] = useState(false);
  const [nlpText, setNlpText] = useState('');

  // Estados para o formulário manual
  const [manualDesc, setManualDesc] = useState('');
  const [manualVal, setManualVal] = useState('');
  const [manualCat, setManualCat] = useState<'house' | 'fixed' | 'work' | 'thirdParty'>('house');
  const [manualInstallments, setManualInstallments] = useState('');

  useEffect(() => {
    localStorage.setItem('mf_ledgers', JSON.stringify(ledgers));
  }, [ledgers]);

  const activeLedger = useMemo(() => {
    return ledgers.find(l => l.id === activeLedgerId) || ledgers[0];
  }, [ledgers, activeLedgerId]);

  const items = activeLedger?.items || [];

  const addLedger = () => {
    const newL = createInitialLedger();
    setLedgers([...ledgers, newL]);
    setActiveLedgerId(newL.id);
    setAnalysis(null);
  };

  const removeLedger = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (ledgers.length === 1) return;
    const newLedgers = ledgers.filter(l => l.id !== id);
    setLedgers(newLedgers);
    if (activeLedgerId === id) {
      setActiveLedgerId(newLedgers[0].id);
    }
    setAnalysis(null);
  };

  const handleManualValueChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const digits = e.target.value.replace(/\D/g, '');
    if (!digits) { setManualVal(''); return; }
    const amount = parseInt(digits) / 100;
    setManualVal(new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(amount));
  };

  const addManualItem = () => {
    const numericValue = parseFloat(manualVal.replace(/[^\d,]/g, '').replace(',', '.')) || 0;
    if (!manualDesc || numericValue <= 0) return;

    let paid: number | undefined;
    let total: number | undefined;

    if (manualInstallments.includes('/')) {
      const [p, t] = manualInstallments.split('/').map(s => parseInt(s.trim()));
      paid = isNaN(p) ? undefined : p;
      total = isNaN(t) ? undefined : t;
    } else if (manualInstallments) {
      total = parseInt(manualInstallments);
    }

    const newItem: FinanceItem = {
      id: Math.random().toString(36).substr(2, 9),
      description: manualDesc,
      value: numericValue,
      category: manualCat,
      paidInstallments: paid,
      totalInstallments: total,
      status: 'pending'
    };

    setLedgers(prev => prev.map(l => l.id === activeLedgerId ? { ...l, items: [...l.items, newItem] } : l));

    // Reset form
    setManualDesc('');
    setManualVal('');
    setManualInstallments('');
  };

  const processNlp = async () => {
    if (!nlpText.trim()) return;
    setParsing(true);
    try {
      const parsedItems = await parseNaturalLanguage(nlpText);
      const newFinanceItems: FinanceItem[] = parsedItems.map(item => ({
        id: Math.random().toString(36).substr(2, 9),
        description: item.description || 'Sem descrição',
        value: item.value || 0,
        category: (item.category as any) || 'house',
        paidInstallments: item.paidInstallments,
        totalInstallments: item.totalInstallments,
        status: 'pending'
      }));

      setLedgers(prev => prev.map(l => l.id === activeLedgerId ? { ...l, items: [...l.items, ...newFinanceItems] } : l));
      setNlpText('');
    } catch (err) {
      alert("Erro ao processar texto pela IA.");
    } finally {
      setParsing(false);
    }
  };

  const removeItem = (id: string) => {
    setLedgers(prev => prev.map(l => l.id === activeLedgerId ? { ...l, items: l.items.filter(i => i.id !== id) } : l));
  };

  const updateItem = (id: string, updates: Partial<FinanceItem>) => {
    setLedgers(prev => prev.map(l => l.id === activeLedgerId ? { ...l, items: l.items.map(i => i.id === id ? { ...i, ...updates } : i) } : l));
  };

  const runAnalysis = async () => {
    if (items.length === 0) return;
    setLoading(true);
    try {
      const result = await analyzeFinanceData(items);
      setAnalysis(result);
    } catch (err) {
      alert('Erro na análise Master Finance.');
    } finally {
      setLoading(false);
    }
  };

  const fmt = (val: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  return (
    <div className="min-h-screen bg-slate-50 font-sans text-slate-900 selection:bg-blue-100">
      {/* Header Master Finance */}
      <nav className="bg-slate-900 text-white h-16 flex items-center px-8 sticky top-0 z-50 shadow-2xl">
        <div className="flex items-center gap-4">
          <div className="w-10 h-10 bg-blue-600 rounded-lg flex items-center justify-center font-black text-lg shadow-lg">MF</div>
          <div>
            <h1 className="text-sm font-black tracking-tighter uppercase leading-none">Master Finance</h1>
            <p className="text-blue-400 font-mono text-[9px] tracking-[0.3em] uppercase opacity-80">Gestão de Fluxo Profissional</p>
          </div>
        </div>
      </nav>

      {/* Tabs System with Close Button */}
      <div className="bg-white border-b border-slate-200 sticky top-16 z-40 px-8 flex items-center gap-2 py-3 overflow-x-auto no-scrollbar">
        {ledgers.map(l => (
          <div 
            key={l.id}
            onClick={() => { setActiveLedgerId(l.id); setAnalysis(null); }}
            className={`group relative flex items-center gap-2 px-4 py-2 text-[10px] font-black uppercase tracking-widest whitespace-nowrap transition-all rounded-md border cursor-pointer ${activeLedgerId === l.id ? 'bg-slate-900 text-white border-slate-900 shadow-md' : 'bg-transparent text-slate-400 border-transparent hover:bg-slate-100'}`}
          >
            <span>{l.name}</span>
            {ledgers.length > 1 && (
              <button 
                onClick={(e) => removeLedger(e, l.id)}
                className={`p-0.5 rounded-full hover:bg-rose-500 hover:text-white transition-colors ${activeLedgerId === l.id ? 'text-slate-500' : 'text-slate-300'}`}
              >
                <X size={12} />
              </button>
            )}
          </div>
        ))}
        <button 
          onClick={addLedger}
          className="p-2 text-slate-400 hover:text-blue-600 transition-colors"
          title="Nova Planilha"
        >
          <Plus size={18} />
        </button>
      </div>

      <main className="max-w-6xl mx-auto p-8 space-y-8">

        {/* Manual Input Form */}
        <section className="bg-white border border-slate-200 shadow-sm rounded-xl overflow-hidden p-6">
          <div className="flex items-center gap-2 mb-6 border-b border-slate-100 pb-3">
            <Plus size={16} className="text-blue-600" />
            <h2 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Lançamento Estruturado</h2>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-12 gap-4 items-end">
            <div className="md:col-span-2">
              <label className="flex items-center gap-1.5 text-[9px] font-black text-slate-400 uppercase mb-1.5">
                <Tag size={10} /> Categoria
              </label>
              <select 
                value={manualCat} 
                onChange={e => setManualCat(e.target.value as any)}
                className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2.5 text-xs font-bold focus:ring-2 focus:ring-blue-500/20 outline-none"
              >
                <option value="house">🏠 Casa</option>
                <option value="fixed">📅 Mensal Fixa</option>
                <option value="work">📥 Trabalho</option>
                <option value="thirdParty">💳 Terceiros</option>
              </select>
            </div>
            <div className="md:col-span-4">
              <label className="flex items-center gap-1.5 text-[9px] font-black text-slate-400 uppercase mb-1.5">
                <TypeIcon size={10} /> Descrição
              </label>
              <input 
                type="text" 
                placeholder="Ex: Aluguel" 
                value={manualDesc}
                onChange={e => setManualDesc(e.target.value)}
                className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2.5 text-xs focus:ring-2 focus:ring-blue-500/20 outline-none" 
              />
            </div>
            <div className="md:col-span-2">
              <label className="flex items-center gap-1.5 text-[9px] font-black text-slate-400 uppercase mb-1.5">
                <DollarSign size={10} /> Valor
              </label>
              <input 
                type="text" 
                placeholder="R$ 0,00" 
                value={manualVal}
                onChange={handleManualValueChange}
                className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2.5 text-xs font-mono font-bold focus:ring-2 focus:ring-blue-500/20 outline-none" 
              />
            </div>
            <div className="md:col-span-2">
              <label className="flex items-center gap-1.5 text-[9px] font-black text-slate-400 uppercase mb-1.5">
                <History size={10} /> Parcela (ex: 3/10)
              </label>
              <input 
                type="text" 
                placeholder="Unica ou 1/12" 
                value={manualInstallments}
                onChange={e => setManualInstallments(e.target.value)}
                className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2.5 text-xs font-bold focus:ring-2 focus:ring-blue-500/20 outline-none" 
              />
            </div>
            <div className="md:col-span-2">
              <button 
                onClick={addManualItem}
                className="w-full bg-blue-600 hover:bg-blue-700 text-white font-black py-2.5 rounded-lg text-[10px] uppercase tracking-widest transition-all shadow-md active:scale-95"
              >
                Lançar
              </button>
            </div>
          </div>
        </section>

        {/* NLP Input Section (Collapsible or secondary) */}
        <details className="group bg-white border border-slate-200 shadow-sm rounded-xl overflow-hidden">
          <summary className="bg-slate-50 px-6 py-3 border-b border-slate-100 flex items-center justify-between cursor-pointer list-none">
            <div className="flex items-center gap-2">
              <Sparkles size={14} className="text-blue-600" />
              <h2 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Comando Rápido (IA) - Digitação Livre</h2>
            </div>
            <Plus size={14} className="group-open:rotate-45 transition-transform text-slate-400" />
          </summary>
          <div className="p-6 space-y-4">
            <textarea 
              value={nlpText}
              onChange={(e) => setNlpText(e.target.value)}
              placeholder="Digite livremente: 'Paguei aluguel 1200, recebi 5000 do trabalho...'"
              className="w-full h-24 bg-slate-50 border border-slate-200 rounded-lg p-4 text-sm focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 outline-none transition-all resize-none font-medium"
            />
            <div className="flex justify-end">
              <button 
                onClick={processNlp}
                disabled={parsing || !nlpText.trim()}
                className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 disabled:bg-slate-200 text-white text-[10px] font-black uppercase px-6 py-3 rounded-lg transition-all shadow-lg"
              >
                {parsing ? <div className="w-3 h-3 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : <Sparkles size={14} />}
                Processar e Lançar
              </button>
            </div>
          </div>
        </details>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
          <div className="lg:col-span-8 space-y-8">
            <ExpenseTable 
              title="🏠 Contas da Casa" icon="" type="expense" 
              items={items.filter(i => i.category === 'house')} 
              onRemove={removeItem} onUpdate={updateItem}
            />
            <ExpenseTable 
              title="📅 Contas Mensais / Fixas" icon="" type="expense" 
              items={items.filter(i => i.category === 'fixed')} 
              onRemove={removeItem} onUpdate={updateItem}
            />
            <ExpenseTable 
              title="📥 Entradas (Trabalho)" icon="" type="income" 
              items={items.filter(i => i.category === 'work')} 
              onRemove={removeItem} onUpdate={updateItem}
            />
            <ExpenseTable 
              title="💳 Entradas (Terceiros / Cartão)" icon="" type="neutral" 
              items={items.filter(i => i.category === 'thirdParty')} 
              onRemove={removeItem} onUpdate={updateItem}
            />
          </div>

          <div className="lg:col-span-4 space-y-6 sticky top-40">
            <button 
              onClick={runAnalysis}
              disabled={loading || items.length === 0}
              className="w-full bg-slate-900 text-white font-black py-5 rounded-xl uppercase text-[11px] tracking-[0.2em] shadow-2xl hover:bg-slate-800 hover:-translate-y-0.5 active:translate-y-0 disabled:bg-slate-300 transition-all flex items-center justify-center gap-3"
            >
              {loading ? <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : <Calculator size={20} />}
              Análise Master
            </button>

            {analysis && (
              <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
                {/* Saúde Card */}
                <div className={`p-6 border-2 shadow-xl rounded-2xl ${
                  analysis.summary.status === 'Saudável' ? 'bg-emerald-50 border-emerald-200' : 
                  analysis.summary.status === 'Atenção' ? 'bg-amber-50 border-amber-200' : 'bg-rose-50 border-rose-200'
                }`}>
                  <span className="text-[10px] font-black uppercase text-slate-400 block mb-2 tracking-widest">Saúde Financeira</span>
                  <div className="flex justify-between items-end mb-4">
                    <h3 className={`text-2xl font-black uppercase tracking-tighter ${
                      analysis.summary.status === 'Saudável' ? 'text-emerald-700' : 
                      analysis.summary.status === 'Atenção' ? 'text-amber-700' : 'text-rose-700'
