                  {analysis.summary.alertMessage && (
                    <div className="mt-6 bg-white border border-rose-200 p-4 rounded-xl text-rose-700 text-[11px] font-bold leading-relaxed shadow-sm">
                      <div className="flex items-start gap-3">
                        <AlertTriangle size={18} className="shrink-0" />
                        <span dangerouslySetInnerHTML={{ __html: analysis.summary.alertMessage.replace(/\*\*/g, '') }} />
                      </div>
                    </div>
                  )}
                </div>

                {/* Resumo Card */}
                <div className="bg-white border border-slate-200 p-6 space-y-6 shadow-sm rounded-2xl">
                  <div className="flex items-center gap-2 border-b border-slate-100 pb-3">
                    <History size={14} className="text-slate-400" />
                    <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Resumo do Caixa</h4>
                  </div>
                  <div className="space-y-4">
                    <div className="flex justify-between items-center group">
                      <span className="text-[11px] font-bold text-slate-400 uppercase">Receita Líquida</span>
                      <span className="font-mono font-black text-emerald-600 text-sm">{fmt(analysis.summary.totalWorkIncome)}</span>
                    </div>
                    <div className="flex justify-between items-center group">
                      <span className="text-[11px] font-bold text-slate-400 uppercase">Gastos Genuínos</span>
                      <span className="font-mono font-black text-rose-500 text-sm">{fmt(analysis.summary.totalExpenses)}</span>
                    </div>
                    <div className="pt-4 border-t border-slate-100 flex justify-between items-center">
                      <span className="text-[11px] font-black text-slate-900 uppercase tracking-tight">Saldo Final</span>
                      <span className={`font-mono text-lg font-black ${analysis.summary.remainingBalance >= 0 ? 'text-blue-600' : 'text-rose-600'}`}>
                        {fmt(analysis.summary.remainingBalance)}
                      </span>
                    </div>
                  </div>
                </div>
              </div>
            )}
          </div>
        </div>
      </main>

      <footer className="max-w-6xl mx-auto px-8 py-12 border-t border-slate-200 mt-16 flex flex-col md:flex-row justify-between items-center gap-4 opacity-40">
