          <span className="text-[10px] font-black uppercase tracking-widest">Master Finance Engine</span>
        </div>
        <div className="text-[9px] font-mono uppercase tracking-widest">Controle de Fluxo Rigoroso © 2025</div>
      </footer>
    </div>
  );
};

