        </span>
      </div>
      <div className="overflow-x-auto">
        <table className="w-full text-[11px] font-mono border-collapse">
          <thead>
            <tr className="bg-slate-50/50 border-b border-slate-200 text-slate-400">
              <th className="px-4 py-2 text-left font-black border-r border-slate-100 uppercase tracking-tighter">Descrição</th>
              <th className="px-4 py-2 text-right font-black border-r border-slate-100 w-36 uppercase tracking-tighter">Valor</th>
              <th className="px-4 py-2 text-center font-black w-28 uppercase tracking-tighter">Parcelas</th>
              <th className="px-2 py-2 w-10"></th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {items.length > 0 ? (
              items.map((item) => (
                <tr key={item.id} className="hover:bg-blue-50/30 transition-colors group">
                  <td className="px-1 py-1 border-r border-slate-100">
                    <input 
                      type="text"
                      value={item.description}
                      onChange={(e) => onUpdate(item.id, { description: e.target.value })}
                      className="w-full bg-transparent px-3 py-1.5 outline-none text-slate-600 focus:bg-white focus:shadow-sm rounded transition-all"
                    />
                  </td>
                  <td className="px-1 py-1 text-right border-r border-slate-100">
                    <input 
                      type="text"
                      value={fmt(item.value)}
                      onChange={(e) => handleValueChange(item.id, e.target.value)}
                      className={`w-full bg-transparent text-right px-3 py-1.5 font-bold outline-none focus:bg-white focus:shadow-sm rounded transition-all ${type === 'expense' ? 'text-rose-500' : type === 'income' ? 'text-emerald-600' : 'text-blue-600'}`}
                    />
                  </td>
                  <td className="px-1 py-1 text-center">
                    <input 
                      type="text"
                      placeholder="-"
                      value={item.totalInstallments ? (item.paidInstallments ? `${item.paidInstallments}/${item.totalInstallments}` : `${item.totalInstallments}`) : ''}
                      onChange={(e) => handleInstallmentChange(item.id, e.target.value)}
                      className="w-full bg-transparent text-center py-1.5 font-black text-slate-400 outline-none focus:bg-white focus:shadow-sm rounded transition-all placeholder:text-slate-200"
                    />
                  </td>
                  <td className="px-2 py-1 text-center">
                    <button 
                      onClick={() => onRemove(item.id)}
                      className="text-slate-200 hover:text-rose-500 transition-all p-1.5 rounded-full hover:bg-rose-50"
                    >
                      <Trash2 size={12} />
                    </button>
                  </td>
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan={4} className="px-4 py-10 text-center text-slate-300 italic uppercase tracking-[0.3em] text-[8px]">
                  Nenhum registro
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

