            <tr className="bg-slate-50/50 border-b border-slate-200 text-slate-400">
              <th className="px-2 py-2 text-center font-black border-r border-slate-100 w-24 uppercase tracking-tighter">Status</th>
              <th className="px-4 py-2 text-left font-black border-r border-slate-100 uppercase tracking-tighter">Descrição</th>
              <th className="px-4 py-2 text-right font-black border-r border-slate-100 w-36 uppercase tracking-tighter">Valor</th>
              <th className="px-4 py-2 text-center font-black w-28 uppercase tracking-tighter">Parcelas</th>
              <th className="px-2 py-2 w-10"></th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {items.length > 0 ? (
              items.map((item) => (
                <tr key={item.id} className={`hover:bg-blue-50/30 transition-colors group ${item.status === 'paid' ? 'bg-slate-50/50 opacity-80' : ''}`}>
                  <td className="px-1 py-1 border-r border-slate-100">
                    <div className="flex justify-center px-1">
                      <select
                        value={item.status}
                        onChange={(e) => onUpdate(item.id, { status: e.target.value as any })}
                        className={`w-full text-[9px] font-black uppercase py-1 rounded border outline-none transition-all cursor-pointer text-center ${
                          item.status === 'paid' 
                            ? 'bg-emerald-100 text-emerald-700 border-emerald-200' 
                            : 'bg-amber-100 text-amber-700 border-amber-200'
                        }`}
                      >
                        <option value="pending">Pendente</option>
                        <option value="paid">Pago</option>
                      </select>
                    </div>
                  </td>
                  <td className="px-1 py-1 border-r border-slate-100">
                    <input 
                      type="text"
                      value={item.description}
                      onChange={(e) => onUpdate(item.id, { description: e.target.value })}
                      className={`w-full bg-transparent px-3 py-1.5 outline-none text-slate-600 focus:bg-white focus:shadow-sm rounded transition-all ${item.status === 'paid' ? 'line-through text-slate-400' : ''}`}
                    />
                  </td>
                  <td className="px-1 py-1 text-right border-r border-slate-100">
                    <input 
                      type="text"
                      value={fmt(item.value)}
                      onChange={(e) => handleValueChange(item.id, e.target.value)}
                      className={`w-full bg-transparent text-right px-3 py-1.5 font-bold outline-none focus:bg-white focus:shadow-sm rounded transition-all ${
                        item.status === 'paid' 
                          ? 'text-slate-400' 
                          : type === 'expense' ? 'text-rose-500' : type === 'income' ? 'text-emerald-600' : 'text-blue-600'
                      }`}
                    />
                  </td>
                  <td className="px-1 py-1 text-center">
                    <input 
                      type="text"
                      placeholder="-"
                      value={item.totalInstallments ? (item.paidInstallments ? `${item.paidInstallments}/${item.totalInstallments}` : `${item.totalInstallments}`) : ''}
                      onChange={(e) => handleInstallmentChange(item.id, e.target.value)}
                      className="w-full bg-transparent text-center py-1.5 font-black text-slate-400 outline-none focus:bg-white focus:shadow-sm rounded transition-all placeholder:text-slate-200"
                    />
                  </td>
                  <td className="px-2 py-1 text-center">
                    <button 
                      onClick={() => onRemove(item.id)}
                      className="text-slate-200 hover:text-rose-500 transition-all p-1.5 rounded-full hover:bg-rose-50"
                    >
                      <Trash2 size={12} />
                    </button>
                  </td>
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan={5} className="px-4 py-10 text-center text-slate-300 italic uppercase tracking-[0.3em] text-[8px]">
                  Nenhum registro
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default ExpenseTable;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Plus,
  AlertTriangle, 
  Calculator,
  LayoutGrid,
  History,
  X,
  Sparkles,
  ArrowRightLeft,
  Wallet,
  Tag,
  DollarSign,
  Type as TypeIcon,
  CheckCircle,
  Clock
} from 'lucide-react';
import { FinanceAnalysis, FinanceItem, HealthStatus, Ledger } from './types';
import { analyzeFinanceData, parseNaturalLanguage } from './services/geminiService';
import ExpenseTable from './components/ExpenseTable';

const App: React.FC = () => {
  const createInitialLedger = (): Ledger => ({
    id: 'ledger-' + Date.now(),
    name: `Mês ${new Date().getMonth() + 1}/${new Date().getFullYear()}`,
    items: []
  });

  const [ledgers, setLedgers] = useState<Ledger[]>(() => {
    const saved = localStorage.getItem('mf_ledgers');
    return saved ? JSON.parse(saved) : [createInitialLedger()];
  });

  const [activeLedgerId, setActiveLedgerId] = useState<string>(ledgers[0]?.id || '');
  const [analysis, setAnalysis] = useState<FinanceAnalysis | null>(null);
  const [loading, setLoading] = useState(false);
  const [parsing, setParsing] = useState(false);
  const [nlpText, setNlpText] = useState('');

  // Estados para o formulário manual
  const [manualDesc, setManualDesc] = useState('');
  const [manualVal, setManualVal] = useState('');
  const [manualCat, setManualCat] = useState<'house' | 'fixed' | 'work' | 'thirdParty'>('house');
  const [manualInstallments, setManualInstallments] = useState('');

  useEffect(() => {
    localStorage.setItem('mf_ledgers', JSON.stringify(ledgers));
  }, [ledgers]);

  const activeLedger = useMemo(() => {
    return ledgers.find(l => l.id === activeLedgerId) || ledgers[0];
  }, [ledgers, activeLedgerId]);

  const items = activeLedger?.items || [];

  const addLedger = () => {
    const newL = createInitialLedger();
    setLedgers([...ledgers, newL]);
    setActiveLedgerId(newL.id);
    setAnalysis(null);
  };

  const removeLedger = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (ledgers.length === 1) return;
    const newLedgers = ledgers.filter(l => l.id !== id);
    setLedgers(newLedgers);
    if (activeLedgerId === id) {
      setActiveLedgerId(newLedgers[0].id);
    }
    setAnalysis(null);
  };

  const handleManualValueChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const digits = e.target.value.replace(/\D/g, '');
    if (!digits) { setManualVal(''); return; }
    const amount = parseInt(digits) / 100;
    setManualVal(new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(amount));
  };

  const addManualItem = () => {
    const numericValue = parseFloat(manualVal.replace(/[^\d,]/g, '').replace(',', '.')) || 0;
    if (!manualDesc || numericValue <= 0) return;

    let paid: number | undefined;
    let total: number | undefined;

    if (manualInstallments.includes('/')) {
      const [p, t] = manualInstallments.split('/').map(s => parseInt(s.trim()));
      paid = isNaN(p) ? undefined : p;
      total = isNaN(t) ? undefined : t;
    } else if (manualInstallments) {
      total = parseInt(manualInstallments);
    }

    const newItem: FinanceItem = {
      id: Math.random().toString(36).substr(2, 9),
      description: manualDesc,
      value: numericValue,
      category: manualCat,
      paidInstallments: paid,
      totalInstallments: total,
      status: 'pending'
    };

    setLedgers(prev => prev.map(l => l.id === activeLedgerId ? { ...l, items: [...l.items, newItem] } : l));

    // Reset form
    setManualDesc('');
    setManualVal('');
    setManualInstallments('');
  };

  const processNlp = async () => {
    if (!nlpText.trim()) return;
    setParsing(true);
    try {
      const parsedItems = await parseNaturalLanguage(nlpText);
      const newFinanceItems: FinanceItem[] = parsedItems.map(item => ({
        id: Math.random().toString(36).substr(2, 9),
        description: item.description || 'Sem descrição',
        value: item.value || 0,
        category: (item.category as any) || 'house',
        paidInstallments: item.paidInstallments,
        totalInstallments: item.totalInstallments,
        status: 'pending'
      }));

      setLedgers(prev => prev.map(l => l.id === activeLedgerId ? { ...l, items: [...l.items, ...newFinanceItems] } : l));
      setNlpText('');
    } catch (err) {
      alert("Erro ao processar texto pela IA.");
    } finally {
      setParsing(false);
    }
  };

  const removeItem = (id: string) => {
    setLedgers(prev => prev.map(l => l.id === activeLedgerId ? { ...l, items: l.items.filter(i => i.id !== id) } : l));
  };

  const updateItem = (id: string, updates: Partial<FinanceItem>) => {
    setLedgers(prev => prev.map(l => l.id === activeLedgerId ? { ...l, items: l.items.map(i => i.id === id ? { ...i, ...updates } : i) } : l));
  };

  const runAnalysis = async () => {
    if (items.length === 0) return;
    setLoading(true);
    try {
      const result = await analyzeFinanceData(items);
      setAnalysis(result);
    } catch (err) {
      alert('Erro na análise Master Finance.');
    } finally {
      setLoading(false);
    }
  };

  const fmt = (val: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  // Cálculos para o resumo de pagos e pendentes
  const summaryData = useMemo(() => {
    const expenses = items.filter(i => i.category === 'house' || i.category === 'fixed');
    const paidItems = expenses.filter(i => i.status === 'paid');
    const pendingItems = expenses.filter(i => i.status === 'pending');

    const totalPaid = paidItems.reduce((acc, curr) => acc + curr.value, 0);
    const totalPending = pendingItems.reduce((acc, curr) => acc + curr.value, 0);

    return { paidItems, totalPaid, totalPending };
  }, [items]);

  return (
    <div className="min-h-screen bg-slate-50 font-sans text-slate-900 selection:bg-blue-100 pb-20">
      {/* Header Master Finance */}
      <nav className="bg-slate-900 text-white h-16 flex items-center px-8 sticky top-0 z-50 shadow-2xl">
        <div className="flex items-center gap-4">
          <div className="w-10 h-10 bg-blue-600 rounded-lg flex items-center justify-center font-black text-lg shadow-lg">MF</div>
          <div>
            <h1 className="text-sm font-black tracking-tighter uppercase leading-none">Master Finance</h1>
            <p className="text-blue-400 font-mono text-[9px] tracking-[0.3em] uppercase opacity-80">Gestão de Fluxo Profissional</p>
          </div>
        </div>
      </nav>

      {/* Tabs System */}
      <div className="bg-white border-b border-slate-200 sticky top-16 z-40 px-8 flex items-center gap-2 py-3 overflow-x-auto no-scrollbar shadow-sm">
        {ledgers.map(l => (
          <div 
            key={l.id}
            onClick={() => { setActiveLedgerId(l.id); setAnalysis(null); }}
            className={`group relative flex items-center gap-2 px-4 py-2 text-[10px] font-black uppercase tracking-widest whitespace-nowrap transition-all rounded-md border cursor-pointer ${activeLedgerId === l.id ? 'bg-slate-900 text-white border-slate-900 shadow-md' : 'bg-transparent text-slate-400 border-transparent hover:bg-slate-100'}`}
          >
            <span>{l.name}</span>
            {ledgers.length > 1 && (
              <button 
                onClick={(e) => removeLedger(e, l.id)}
                className={`p-0.5 rounded-full hover:bg-rose-500 hover:text-white transition-colors ${activeLedgerId === l.id ? 'text-slate-500' : 'text-slate-300'}`}
              >
                <X size={12} />
              </button>
            )}
          </div>
        ))}
        <button 
          onClick={addLedger}
          className="p-2 text-slate-400 hover:text-blue-600 transition-colors"
          title="Nova Planilha"
        >
          <Plus size={18} />
        </button>
      </div>

      <main className="max-w-6xl mx-auto p-8 space-y-8">

        {/* Manual Input Form */}
        <section className="bg-white border border-slate-200 shadow-sm rounded-xl overflow-hidden p-6">
          <div className="flex items-center gap-2 mb-6 border-b border-slate-100 pb-3">
            <Plus size={16} className="text-blue-600" />
            <h2 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Lançamento Estruturado</h2>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-12 gap-4 items-end">
            <div className="md:col-span-2">
              <label className="flex items-center gap-1.5 text-[9px] font-black text-slate-400 uppercase mb-1.5">
                <Tag size={10} /> Categoria
              </label>
              <select 
                value={manualCat} 
                onChange={e => setManualCat(e.target.value as any)}
                className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2.5 text-xs font-bold focus:ring-2 focus:ring-blue-500/20 outline-none"
              >
                <option value="house">🏠 Casa</option>
                <option value="fixed">📅 Mensal Fixa</option>
                <option value="work">📥 Trabalho</option>
                <option value="thirdParty">💳 Terceiros</option>
              </select>
            </div>
            <div className="md:col-span-4">
              <label className="flex items-center gap-1.5 text-[9px] font-black text-slate-400 uppercase mb-1.5">
                <TypeIcon size={10} /> Descrição
              </label>
              <input 
                type="text" 
                placeholder="Ex: Aluguel" 
                value={manualDesc}
                onChange={e => setManualDesc(e.target.value)}
                className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2.5 text-xs focus:ring-2 focus:ring-blue-500/20 outline-none" 
              />
            </div>
            <div className="md:col-span-2">
              <label className="flex items-center gap-1.5 text-[9px] font-black text-slate-400 uppercase mb-1.5">
                <DollarSign size={10} /> Valor
              </label>
              <input 
                type="text" 
                placeholder="R$ 0,00" 
                value={manualVal}
                onChange={handleManualValueChange}
                className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2.5 text-xs font-mono font-bold focus:ring-2 focus:ring-blue-500/20 outline-none" 
              />
            </div>
            <div className="md:col-span-2">
              <label className="flex items-center gap-1.5 text-[9px] font-black text-slate-400 uppercase mb-1.5">
                <History size={10} /> Parcela (ex: 3/10)
              </label>
              <input 
                type="text" 
                placeholder="Unica ou 1/12" 
                value={manualInstallments}
                onChange={e => setManualInstallments(e.target.value)}
                className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2.5 text-xs font-bold focus:ring-2 focus:ring-blue-500/20 outline-none" 
              />
            </div>
            <div className="md:col-span-2">
              <button 
                onClick={addManualItem}
                className="w-full bg-blue-600 hover:bg-blue-700 text-white font-black py-2.5 rounded-lg text-[10px] uppercase tracking-widest transition-all shadow-md active:scale-95"
              >
                Lançar
              </button>
            </div>
          </div>
        </section>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
          <div className="lg:col-span-8 space-y-8">
            <ExpenseTable 
              title="🏠 Contas da Casa" icon="" type="expense" 
              items={items.filter(i => i.category === 'house')} 
              onRemove={removeItem} onUpdate={updateItem}
            />
            <ExpenseTable 
              title="📅 Contas Mensais / Fixas" icon="" type="expense" 
              items={items.filter(i => i.category === 'fixed')} 
              onRemove={removeItem} onUpdate={updateItem}
            />
            <ExpenseTable 
              title="📥 Entradas (Trabalho)" icon="" type="income" 
              items={items.filter(i => i.category === 'work')} 
              onRemove={removeItem} onUpdate={updateItem}
            />
            <ExpenseTable 
              title="💳 Entradas (Terceiros / Cartão)" icon="" type="neutral" 
              items={items.filter(i => i.category === 'thirdParty')} 
              onRemove={removeItem} onUpdate={updateItem}
            />

            {/* Nova Seção: Relação de Contas Pagas e Falta Pagar */}
            <div className="bg-white border border-slate-200 rounded-2xl overflow-hidden shadow-sm animate-in fade-in slide-in-from-bottom-4 duration-700">
              <div className="bg-slate-900 text-white px-6 py-4 flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <CheckCircle size={20} className="text-emerald-400" />
                  <h3 className="text-[11px] font-black uppercase tracking-[0.2em]">Relatório de Liquidação</h3>
                </div>
                <div className="text-[9px] font-mono text-slate-400">STATUS DE PAGAMENTO ATUALIZADO</div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 divide-y md:divide-y-0 md:divide-x divide-slate-100">
                {/* Lado Esquerdo: Lista de Pagos */}
                <div className="p-6">
                  <h4 className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                    <CheckCircle size={12} className="text-emerald-500" /> Contas Liquidadas
                  </h4>
                  <div className="space-y-2 max-h-60 overflow-y-auto pr-2 no-scrollbar">
                    {summaryData.paidItems.length > 0 ? summaryData.paidItems.map(item => (
                      <div key={item.id} className="flex justify-between items-center py-2 border-b border-slate-50 last:border-0 group">
                        <span className="text-xs font-bold text-slate-600 truncate max-w-[150px]">{item.description}</span>
                        <span className="text-xs font-mono font-black text-emerald-600">{fmt(item.value)}</span>
                      </div>
                    )) : (
                      <div className="text-[10px] text-slate-300 italic py-4">Nenhuma conta marcada como paga.</div>
                    )}
                  </div>
                  <div className="mt-6 pt-4 border-t border-slate-100 flex justify-between items-center">
                    <span className="text-[10px] font-black text-slate-900 uppercase">Total Liquidado</span>
                    <span className="text-lg font-mono font-black text-emerald-600">{fmt(summaryData.totalPaid)}</span>
                  </div>
                </div>

                {/* Lado Direito: Resumo do que Falta */}
                <div className="p-6 bg-slate-50/50">
                  <h4 className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                    <Clock size={12} className="text-amber-500" /> Compromissos Pendentes
                  </h4>
                  <div className="space-y-6">
                    <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm">
                      <p className="text-[9px] font-black text-slate-400 uppercase mb-1">Falta Pagar</p>
                      <p className="text-3xl font-mono font-black text-rose-500 tracking-tighter">
                        {fmt(summaryData.totalPending)}
                      </p>
                      <div className="mt-4 w-full h-1.5 bg-slate-100 rounded-full overflow-hidden">
                        <div 
                          className="h-full bg-rose-500 transition-all duration-1000"
                          style={{ width: `${Math.min((summaryData.totalPending / (summaryData.totalPaid + summaryData.totalPending || 1)) * 100, 100)}%` }}
                        />
                      </div>
                    </div>

                    <div className="bg-slate-900 text-white p-5 rounded-xl">
                      <div className="flex justify-between items-center mb-2">
                        <span className="text-[9px] font-black text-slate-400 uppercase">Total Estimado do Mês</span>
                        <span className="text-xs font-mono font-bold text-blue-400">{fmt(summaryData.totalPaid + summaryData.totalPending)}</span>
                      </div>
                      <p className="text-[10px] leading-relaxed text-slate-400 font-medium">
                        Você já liquidou <span className="text-emerald-400 font-black">{((summaryData.totalPaid / (summaryData.totalPaid + summaryData.totalPending || 1)) * 100).toFixed(0)}%</span> das suas obrigações financeiras deste período.
                      </p>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>

          {/* Lateral de Análise */}
          <div className="lg:col-span-4 space-y-6 sticky top-40">
            <button 
              onClick={runAnalysis}
              disabled={loading || items.length === 0}
