                  <h4 className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-4 flex items-center gap-2"><CheckCircle size={12} className="text-emerald-500" /> Contas Liquidadas</h4>
                  <div className="space-y-2 max-h-60 overflow-y-auto pr-2 no-scrollbar">
                    {summaryData.paidItems.length > 0 ? summaryData.paidItems.map(item => (
                      <div key={item.id} className="flex justify-between items-center py-2 border-b border-slate-50 last:border-0 group">
                        <span className="text-xs font-bold text-slate-600 truncate max-w-[150px]">{item.description}</span>
