                  </div>
                  <div className="mt-6 pt-4 border-t border-slate-100 flex justify-between items-center">
                    <span className="text-[10px] font-black text-slate-900 uppercase">Total Pago</span>
                    <span className="text-lg font-mono font-black text-emerald-600">{fmt(summaryData.totalPaid)}</span>
