    return ledgers.find(l => l.id === activeLedgerId) || ledgers[0];
  }, [ledgers, activeLedgerId]);

  const items = activeLedger?.items || [];

  const addLedger = () => {
    const newL = createInitialLedger();
    setLedgers([...ledgers, newL]);
    setActiveLedgerId(newL.id);
    setAnalysis(null);
  };

  const duplicateActiveLedger = () => {
    if (!activeLedger) return;
    const newL: Ledger = {
      ...activeLedger,
      id: 'ledger-' + Date.now(),
      name: `${activeLedger.name} (Cópia)`,
      items: activeLedger.items.map(item => ({ 
        ...item, 
        id: Math.random().toString(36).substr(2, 9) 
      }))
    };
    setLedgers([...ledgers, newL]);
    setActiveLedgerId(newL.id);
    setAnalysis(null);
  };

  const removeLedger = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (ledgers.length === 1) return;
    const newLedgers = ledgers.filter(l => l.id !== id);
    setLedgers(newLedgers);
    if (activeLedgerId === id) {
      setActiveLedgerId(newLedgers[0].id);
    }
    setAnalysis(null);
  };

  const handleManualValueChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const digits = e.target.value.replace(/\D/g, '');
    if (!digits) { setMVal(''); return; }
    const amount = parseInt(digits) / 100;
    setMVal(new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(amount));
  };

  const addManualItem = () => {
    const numericValue = parseFloat(mVal.replace(/[^\d,]/g, '').replace(',', '.')) || 0;
    if (!mDesc || numericValue <= 0) return;

    const paid = mInstPaid ? parseInt(mInstPaid) : undefined;
    const total = mInstTotal ? parseInt(mInstTotal) : undefined;

    const newItem: FinanceItem = {
      id: Math.random().toString(36).substr(2, 9),
      description: mDesc,
      value: numericValue,
      category: mCat,
      paidInstallments: paid,
      totalInstallments: total,
      status: 'pending'
    };

    setLedgers(prev => prev.map(l => l.id === activeLedgerId ? { ...l, items: [...l.items, newItem] } : l));

    setMDesc('');
    setMVal('');
    setMInstPaid('');
    setMInstTotal('');
  };

  const processNlp = async () => {
    if (!nlpText.trim()) return;
    setParsing(true);
    try {
      const parsedItems = await parseNaturalLanguage(nlpText);
      const newItems: FinanceItem[] = parsedItems.map(item => ({
        id: Math.random().toString(36).substr(2, 9),
        description: item.description || 'Sem descrição',
        value: item.value || 0,
        category: (item.category as any) || 'house',
        paidInstallments: item.paidInstallments,
        totalInstallments: item.totalInstallments,
        status: 'pending'
      }));
      setLedgers(prev => prev.map(l => l.id === activeLedgerId ? { ...l, items: [...l.items, ...newItems] } : l));
      setNlpText('');
    } catch (err) {
      alert("Erro ao processar texto pela IA.");
    } finally {
      setParsing(false);
    }
  };

  const removeItem = (id: string) => {
    setLedgers(prev => prev.map(l => l.id === activeLedgerId ? { ...l, items: l.items.filter(i => i.id !== id) } : l));
  };

  const updateItem = (id: string, updates: Partial<FinanceItem>) => {
    setLedgers(prev => prev.map(l => l.id === activeLedgerId ? { ...l, items: l.items.map(i => i.id === id ? { ...i, ...updates } : i) } : l));
  };

  const runAnalysis = async () => {
    if (items.length === 0) return;
    setLoading(true);
    try {
      const result = await analyzeFinanceData(items);
      setAnalysis(result);
    } catch (err) {
      alert('Erro na análise Master Finance.');
    } finally {
      setLoading(false);
    }
  };

  const fmt = (val: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  const summaryData = useMemo(() => {
    const expenses = items.filter(i => i.category === 'house' || i.category === 'fixed');
    const paidItems = expenses.filter(i => i.status === 'paid');
    const pendingItems = expenses.filter(i => i.status === 'pending');
    const totalPaid = paidItems.reduce((acc, curr) => acc + curr.value, 0);
    const totalPending = pendingItems.reduce((acc, curr) => acc + curr.value, 0);
    return { paidItems, totalPaid, totalPending };
  }, [items]);

  return (
    <div className="min-h-screen bg-slate-50 font-sans text-slate-900 selection:bg-blue-100 pb-20">
      {/* Header */}
      <nav className="bg-slate-900 text-white h-16 flex items-center px-8 sticky top-0 z-50 shadow-2xl">
        <div className="flex items-center gap-4">
          <div className="w-10 h-10 bg-blue-600 rounded-lg flex items-center justify-center font-black text-lg shadow-lg">MF</div>
          <div>
            <h1 className="text-sm font-black tracking-tighter uppercase leading-none">Master Finance</h1>
            <p className="text-blue-400 font-mono text-[9px] tracking-[0.3em] uppercase opacity-80">Gestão de Fluxo Profissional</p>
          </div>
        </div>
      </nav>

      {/* Tabs */}
      <div className="bg-white border-b border-slate-200 sticky top-16 z-40 px-8 flex items-center gap-2 py-3 overflow-x-auto no-scrollbar shadow-sm">
        {ledgers.map(l => (
          <div 
            key={l.id}
            onClick={() => { setActiveLedgerId(l.id); setAnalysis(null); }}
            className={`group relative flex items-center gap-2 px-4 py-2 text-[10px] font-black uppercase tracking-widest whitespace-nowrap transition-all rounded-md border cursor-pointer ${activeLedgerId === l.id ? 'bg-slate-900 text-white border-slate-900 shadow-md' : 'bg-transparent text-slate-400 border-transparent hover:bg-slate-100'}`}
          >
            <span>{l.name}</span>
            {ledgers.length > 1 && (
              <button 
                onClick={(e) => removeLedger(e, l.id)}
                className={`p-0.5 rounded-full hover:bg-rose-500 hover:text-white transition-colors ${activeLedgerId === l.id ? 'text-slate-500' : 'text-slate-300'}`}
              >
                <X size={12} />
              </button>
            )}
          </div>
        ))}
        <div className="flex items-center gap-1 border-l border-slate-200 ml-2 pl-2">
          <button onClick={addLedger} className="p-2 text-slate-400 hover:text-blue-600 transition-colors" title="Nova Planilha"><Plus size={18} /></button>
          <button onClick={duplicateActiveLedger} className="p-2 text-slate-400 hover:text-emerald-600 transition-colors" title="Duplicar Planilha Ativa"><Copy size={16} /></button>
        </div>
      </div>

      <main className="max-w-6xl mx-auto p-8 space-y-8">

        {/* Manual Input Form */}
        <section className="bg-white border border-slate-200 shadow-sm rounded-xl overflow-hidden p-6">
          <div className="flex items-center gap-2 mb-6 border-b border-slate-100 pb-3">
            <Plus size={16} className="text-blue-600" />
            <h2 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Lançamento de Conta</h2>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-12 gap-4 items-end">
            <div className="md:col-span-2">
              <label className="flex items-center gap-1.5 text-[9px] font-black text-slate-400 uppercase mb-1.5"><Tag size={10} /> Categoria</label>
              <select 
                value={mCat} 
                onChange={e => setMCat(e.target.value as any)}
                className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2.5 text-xs font-bold focus:ring-2 focus:ring-blue-500/20 outline-none transition-all"
              >
                <option value="house">🏠 Casa</option>
                <option value="fixed">📅 Mensal Fixa</option>
                <option value="work">📥 Trabalho</option>
                <option value="thirdParty">💳 Terceiros</option>
              </select>
            </div>
            <div className="md:col-span-4">
              <label className="flex items-center gap-1.5 text-[9px] font-black text-slate-400 uppercase mb-1.5"><TypeIcon size={10} /> Descrição</label>
              <input 
                type="text" placeholder="Ex: Aluguel ou Internet" value={mDesc} onChange={e => setMDesc(e.target.value)}
                className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2.5 text-xs focus:ring-2 focus:ring-blue-500/20 outline-none transition-all" 
              />
            </div>
            <div className="md:col-span-2">
              <label className="flex items-center gap-1.5 text-[9px] font-black text-slate-400 uppercase mb-1.5"><DollarSign size={10} /> Valor</label>
              <input 
                type="text" placeholder="R$ 0,00" value={mVal} onChange={handleManualValueChange}
                className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2.5 text-xs font-mono font-bold focus:ring-2 focus:ring-blue-500/20 outline-none transition-all" 
              />
            </div>
            <div className="md:col-span-2">
              <label className="flex items-center gap-1.5 text-[9px] font-black text-slate-400 uppercase mb-1.5"><History size={10} /> Parcelas</label>
              <div className="flex items-center bg-slate-50 border border-slate-200 rounded-lg px-2 py-2 text-xs transition-all focus-within:ring-2 focus-within:ring-blue-500/20">
                <input 
                  type="number" placeholder="Atu" value={mInstPaid} onChange={e => setMInstPaid(e.target.value)}
                  className="w-full text-right bg-transparent outline-none font-bold [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none" 
                />
                <span className="px-2 font-black text-slate-300">/</span>
                <input 
                  type="number" placeholder="Tot" value={mInstTotal} onChange={e => setMInstTotal(e.target.value)}
                  className="w-full text-left bg-transparent outline-none font-bold [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none" 
                />
              </div>
            </div>
            <div className="md:col-span-2">
              <button onClick={addManualItem} className="w-full bg-blue-600 hover:bg-blue-700 text-white font-black py-2.5 rounded-lg text-[10px] uppercase tracking-widest transition-all shadow-md active:scale-95">Lançar</button>
            </div>
          </div>
        </section>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
          <div className="lg:col-span-8 space-y-8">
            <ExpenseTable title="🏠 Contas da Casa" icon="" type="expense" showStatus={true} items={items.filter(i => i.category === 'house')} onRemove={removeItem} onUpdate={updateItem} />
            <ExpenseTable title="📅 Contas Mensais / Fixas" icon="" type="expense" showStatus={true} items={items.filter(i => i.category === 'fixed')} onRemove={removeItem} onUpdate={updateItem} />
            <ExpenseTable title="📥 Entradas (Trabalho)" icon="" type="income" items={items.filter(i => i.category === 'work')} onRemove={removeItem} onUpdate={updateItem} />
            <ExpenseTable title="💳 Entradas (Terceiros / Cartão)" icon="" type="neutral" items={items.filter(i => i.category === 'thirdParty')} onRemove={removeItem} onUpdate={updateItem} />

            {/* Settlement Report */}
            <div className="bg-white border border-slate-200 rounded-2xl overflow-hidden shadow-sm animate-in fade-in slide-in-from-bottom-4 duration-700">
              <div className="bg-slate-900 text-white px-6 py-4 flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <CheckCircle size={20} className="text-emerald-400" />
                  <h3 className="text-[11px] font-black uppercase tracking-[0.2em]">Relatório de Liquidação</h3>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 divide-y md:divide-y-0 md:divide-x divide-slate-100">
                <div className="p-6">
                  <h4 className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-4 flex items-center gap-2"><CheckCircle size={12} className="text-emerald-500" /> Contas Liquidadas</h4>
                  <div className="space-y-2 max-h-60 overflow-y-auto pr-2 no-scrollbar">
                    {summaryData.paidItems.length > 0 ? summaryData.paidItems.map(item => (
                      <div key={item.id} className="flex justify-between items-center py-2 border-b border-slate-50 last:border-0 group">
                        <span className="text-xs font-bold text-slate-600 truncate max-w-[150px]">{item.description}</span>
                        <span className="text-xs font-mono font-black text-emerald-600">{fmt(item.value)}</span>
                      </div>
                    )) : <div className="text-[10px] text-slate-300 italic py-4 uppercase">Nada liquidado ainda</div>}
                  </div>
                  <div className="mt-6 pt-4 border-t border-slate-100 flex justify-between items-center">
                    <span className="text-[10px] font-black text-slate-900 uppercase">Total Pago</span>
                    <span className="text-lg font-mono font-black text-emerald-600">{fmt(summaryData.totalPaid)}</span>
                  </div>
                </div>

                <div className="p-6 bg-slate-50/50">
                  <h4 className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-4 flex items-center gap-2"><Clock size={12} className="text-amber-500" /> Restante a Pagar</h4>
                  <div className="space-y-6">
                    <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm">
                      <p className="text-[9px] font-black text-slate-400 uppercase mb-1">Saldo Devedor</p>
                      <p className="text-3xl font-mono font-black text-rose-500 tracking-tighter">{fmt(summaryData.totalPending)}</p>
                    </div>
                    <div className="bg-slate-900 text-white p-5 rounded-xl">
                      <p className="text-[10px] leading-relaxed text-slate-400 font-medium">
                        Você já liquidou <span className="text-emerald-400 font-black">{((summaryData.totalPaid / (summaryData.totalPaid + summaryData.totalPending || 1)) * 100).toFixed(0)}%</span> das suas contas.
                      </p>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>

          {/* Analysis Sidebar */}
          <div className="lg:col-span-4 space-y-6 sticky top-40">
            <button 
              onClick={runAnalysis} disabled={loading || items.length === 0}
              className="w-full bg-slate-900 text-white font-black py-5 rounded-xl uppercase text-[11px] tracking-[0.2em] shadow-2xl hover:bg-slate-800 hover:-translate-y-0.5 transition-all flex items-center justify-center gap-3 disabled:bg-slate-300"
            >
              {loading ? <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : <Calculator size={20} />}
              Análise Master
            </button>

            {analysis && (
              <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
                <div className={`p-6 border-2 shadow-xl rounded-2xl ${analysis.summary.status === 'Saudável' ? 'bg-emerald-50 border-emerald-200' : analysis.summary.status === 'Atenção' ? 'bg-amber-50 border-amber-200' : 'bg-rose-50 border-rose-200'}`}>
                  <span className="text-[10px] font-black uppercase text-slate-400 block mb-2 tracking-widest">Saúde Financeira</span>
                  <div className="flex justify-between items-end mb-4">
                    <h3 className={`text-2xl font-black uppercase tracking-tighter ${analysis.summary.status === 'Saudável' ? 'text-emerald-700' : analysis.summary.status === 'Atenção' ? 'text-amber-700' : 'text-rose-700'}`}>{analysis.summary.status}</h3>
                    <span className="text-lg font-mono font-black opacity-70">{(analysis.summary.compromisePercentage * 100).toFixed(0)}%</span>
                  </div>
                  <div className="w-full h-2 bg-slate-200/50 rounded-full overflow-hidden">
                    <div className={`h-full transition-all duration-1000 ${analysis.summary.compromisePercentage > 0.8 ? 'bg-rose-500' : analysis.summary.compromisePercentage > 0.5 ? 'bg-amber-500' : 'bg-emerald-500'}`} style={{ width: `${Math.min(analysis.summary.compromisePercentage * 100, 100)}%` }} />
                  </div>
                  {analysis.summary.alertMessage && <div className="mt-6 bg-white border border-rose-200 p-4 rounded-xl text-rose-700 text-[11px] font-bold shadow-sm flex items-start gap-3"><AlertTriangle size={18} className="shrink-0" /><span dangerouslySetInnerHTML={{ __html: analysis.summary.alertMessage.replace(/\*\*/g, '') }} /></div>}
                </div>
              </div>
            )}

            {/* AI Assistant (NLP) section below main analysis */}
            <details className="group bg-white border border-slate-200 shadow-sm rounded-xl overflow-hidden">
              <summary className="bg-slate-50 px-6 py-3 border-b border-slate-100 flex items-center justify-between cursor-pointer list-none">
                <div className="flex items-center gap-2"><Sparkles size={14} className="text-blue-600" /><h2 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Digitação por IA</h2></div>
                <Plus size={14} className="group-open:rotate-45 transition-transform text-slate-400" />
              </summary>
              <div className="p-6 space-y-4">
                <textarea value={nlpText} onChange={(e) => setNlpText(e.target.value)} placeholder="Ex: 'Paguei 150 de luz e recebi 500 de bônus'" className="w-full h-24 bg-slate-50 border border-slate-200 rounded-lg p-3 text-xs outline-none focus:ring-2 focus:ring-blue-500/20 transition-all resize-none" />
                <button onClick={processNlp} disabled={parsing || !nlpText.trim()} className="w-full bg-blue-600 text-white font-black py-2.5 rounded-lg text-[10px] uppercase shadow-md active:scale-95 disabled:bg-slate-200">
                  {parsing ? 'Processando...' : 'Lançar com IA'}
                </button>
              </div>
            </details>
          </div>
        </div>
      </main>

      <footer className="max-w-6xl mx-auto px-8 py-12 border-t border-slate-200 mt-16 flex flex-col md:flex-row justify-between items-center gap-4 opacity-40">
        <div className="flex items-center gap-3"><div className="w-6 h-6 bg-slate-900 rounded flex items-center justify-center font-black text-[10px] text-white">MF</div><span className="text-[10px] font-black uppercase tracking-widest">Master Finance Engine</span></div>
        <div className="text-[9px] font-mono uppercase tracking-widest">© 2025 • Monitoramento de Fluxo Profissional</div>
      </footer>
    </div>
  );
};

export default App;

import React from 'react';
import { FinanceItem } from '../types';
import { Trash2 } from 'lucide-react';

interface ExpenseTableProps {
  title: string;
  items: FinanceItem[];
  icon: string;
  type: 'income' | 'expense' | 'neutral';
  showStatus?: boolean;
  onRemove: (id: string) => void;
  onUpdate: (id: string, updates: Partial<FinanceItem>) => void;
}

const ExpenseTable: React.FC<ExpenseTableProps> = ({ 
  title, 
  items, 
  icon, 
  type, 
  showStatus = false,
  onRemove, 
  onUpdate 
}) => {
  const total = items.reduce((acc, curr) => acc + curr.value, 0);

  const fmt = (val: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  const handleValueChange = (id: string, rawValue: string) => {
    const digits = rawValue.replace(/\D/g, '');
    const numericValue = digits ? parseInt(digits) / 100 : 0;
    onUpdate(id, { value: numericValue });
  };

  return (
    <div className="bg-white border border-slate-200 shadow-sm overflow-hidden mb-6 rounded-lg">
      <div className="bg-slate-50 px-4 py-2 border-b border-slate-200 flex justify-between items-center">
        <h3 className="text-[10px] font-black text-slate-500 flex items-center gap-2 uppercase tracking-[0.2em]">
          <span>{icon}</span> {title}
        </h3>
        <span className={`text-xs font-mono font-bold ${type === 'expense' ? 'text-rose-600' : type === 'income' ? 'text-emerald-600' : 'text-blue-600'}`}>
          {fmt(total)}
        </span>
      </div>
      <div className="overflow-x-auto">
        <table className="w-full text-[11px] font-mono border-collapse">
          <thead>
            <tr className="bg-slate-50/50 border-b border-slate-200 text-slate-400">
              {showStatus && <th className="px-2 py-2 text-center font-black border-r border-slate-100 w-24 uppercase tracking-tighter">Status</th>}
              <th className="px-4 py-2 text-left font-black border-r border-slate-100 uppercase tracking-tighter">Descrição</th>
              <th className="px-4 py-2 text-right font-black border-r border-slate-100 w-36 uppercase tracking-tighter">Valor</th>
              <th className="px-4 py-2 text-center font-black w-28 uppercase tracking-tighter">Parcelas</th>
              <th className="px-2 py-2 w-10"></th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {items.length > 0 ? (
              items.map((item) => (
                <tr key={item.id} className={`hover:bg-blue-50/30 transition-colors group ${item.status === 'paid' ? 'bg-slate-50/50 opacity-80' : ''}`}>
                  {showStatus && (
                    <td className="px-1 py-1 border-r border-slate-100">
                      <div className="flex justify-center px-1">
                        <select
                          value={item.status}
                          onChange={(e) => onUpdate(item.id, { status: e.target.value as any })}
                          className={`w-full text-[9px] font-black uppercase py-1 rounded border outline-none transition-all cursor-pointer text-center ${
                            item.status === 'paid' 
                              ? 'bg-emerald-100 text-emerald-700 border-emerald-200' 
                              : 'bg-amber-100 text-amber-700 border-amber-200'
                          }`}
                        >
                          <option value="pending">Pendente</option>
                          <option value="paid">Pago</option>
                        </select>
                      </div>
                    </td>
                  )}
                  <td className="px-1 py-1 border-r border-slate-100">
                    <input 
                      type="text"
                      value={item.description}
                      onChange={(e) => onUpdate(item.id, { description: e.target.value })}
                      className={`w-full bg-transparent px-3 py-1.5 outline-none text-slate-600 focus:bg-white focus:shadow-sm rounded transition-all ${item.status === 'paid' ? 'line-through text-slate-400' : ''}`}
                    />
                  </td>
                  <td className="px-1 py-1 text-right border-r border-slate-100">
                    <input 
                      type="text"
                      value={fmt(item.value)}
                      onChange={(e) => handleValueChange(item.id, e.target.value)}
                      className={`w-full bg-transparent text-right px-3 py-1.5 font-bold outline-none focus:bg-white focus:shadow-sm rounded transition-all ${
                        item.status === 'paid' 
                          ? 'text-slate-400' 
                          : type === 'expense' ? 'text-rose-500' : type === 'income' ? 'text-emerald-600' : 'text-blue-600'
                      }`}
                    />
                  </td>
                  <td className="px-1 py-1 text-center">
                    <div className="flex items-center justify-center gap-1 text-[10px] font-black text-slate-400">
                      <input 
                        type="number"
                        value={item.paidInstallments ?? ''}
                        onChange={(e) => onUpdate(item.id, { paidInstallments: e.target.value ? parseInt(e.target.value) : undefined })}
                        placeholder="0"
                        className="w-8 bg-transparent text-right outline-none focus:text-blue-600 transition-colors [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none"
                      />
                      <span className="text-slate-300">/</span>
                      <input 
                        type="number"
                        value={item.totalInstallments ?? ''}
                        onChange={(e) => onUpdate(item.id, { totalInstallments: e.target.value ? parseInt(e.target.value) : undefined })}
                        placeholder="0"
                        className="w-8 bg-transparent text-left outline-none focus:text-blue-600 transition-colors [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none"
                      />
                    </div>
                  </td>
                  <td className="px-2 py-1 text-center">
                    <button 
                      onClick={() => onRemove(item.id)}
                      className="text-slate-200 hover:text-rose-500 transition-all p-1.5 rounded-full hover:bg-rose-50"
                    >
                      <Trash2 size={12} />
                    </button>
                  </td>
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan={showStatus ? 5 : 4} className="px-4 py-10 text-center text-slate-300 italic uppercase tracking-[0.3em] text-[8px]">
                  Nenhum registro
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

