    if (items.length === 0) return;
    setLoading(true);
    try {
      const result = await analyzeFinanceData(items);
      setAnalysis(result);
    } catch (err) {
      alert('Erro na análise Master Finance.');
    } finally {
      setLoading(false);
    }
  };

  // Logic to handle AI natural language processing
