            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Painel Individual</p>
          </div>
        </div>
        <button onClick={onRemove} className="text-rose-500 hover:bg-rose-50 px-3 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all">
