               <div className="flex items-center gap-2"><Sparkles size={14} className="text-blue-600" /><h2 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">IA Assistant</h2></div>
               <Plus size={14} className="group-open:rotate-45 transition-transform" />
