               <textarea value={nlpText} onChange={(e) => setNlpText(e.target.value)} placeholder="Diga o que gastou hoje..." className="w-full h-20 bg-slate-50 border border-slate-200 rounded-lg p-3 text-xs outline-none focus:ring-2 focus:ring-blue-500/10 resize-none" />
               <button onClick={handleNLP} disabled={parsing || !nlpText} className="w-full bg-blue-600 text-white font-black py-2 rounded-lg text-[9px] uppercase tracking-widest shadow active:scale-95 disabled:bg-slate-100">
                 {parsing ? "Processando..." : "Processar Voz/Texto"}
               </button>
             </div>
           </details>
        </div>
      </div>
    </div>
  );
};

