              className="bg-transparent text-[10px] font-black uppercase tracking-widest px-4 py-2 outline-none cursor-pointer hover:bg-white rounded-lg transition-all"
            >
              {months.map((m, i) => <option key={i} value={i+1}>{m}</option>)}
            </select>
            <div className="w-[1px] h-4 bg-slate-300"></div>
