      <main className="flex-1 max-w-7xl mx-auto w-full p-8 space-y-8 pb-24">
        {/* Resumo Consolidado */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-5 transform transition-transform hover:scale-[1.02]">
            <div className="w-12 h-12 bg-emerald-50 text-emerald-600 rounded-2xl flex items-center justify-center"><TrendingUp size={24} /></div>
            <div>
