              <p className="text-xl font-mono font-black text-emerald-600">
                {fmt(ledger.items.filter(i => i.category === 'work').reduce((a, b) => a + b.value, 0))}
              </p>
            </div>
          </div>
          <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-5 transform transition-transform hover:scale-[1.02]">
            <div className="w-12 h-12 bg-rose-50 text-rose-600 rounded-2xl flex items-center justify-center"><AlertCircle size={24} /></div>
            <div>
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Gasto Total (Casa + Fixo)</p>
              <p className="text-xl font-mono font-black text-rose-600">
                {fmt(ledger.items.filter(i => i.category === 'house' || i.category === 'fixed').reduce((a, b) => a + b.value, 0))}
              </p>
            </div>
          </div>
          <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-5 transform transition-transform hover:scale-[1.02]">
            <div className="w-12 h-12 bg-blue-50 text-blue-600 rounded-2xl flex items-center justify-center"><CheckCircle size={24} /></div>
            <div>
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Liquidado (Pago)</p>
              <p className="text-xl font-mono font-black text-blue-600">
                {fmt(ledger.items.filter(i => i.status === 'paid').reduce((a, b) => a + b.value, 0))}
              </p>
            </div>
          </div>
        </div>

        {/* Formulário de Lançamento Manual (Modelo Anterior Restaurado) */}
        <section className="bg-white border border-slate-200 shadow-md rounded-2xl overflow-hidden p-6 md:p-8">
          <div className="flex items-center gap-3 mb-8 border-b border-slate-100 pb-4">
