                        {(analysis.summary.compromisePercentage * 100).toFixed(1)}%
                      </span>
                    </div>
                    <div className="h-2 w-full bg-slate-200 rounded-full overflow-hidden">
                      <div className={`h-full transition-all duration-1000 ${analysis.summary.compromisePercentage > 0.8 ? 'bg-rose-600' : analysis.summary.compromisePercentage > 0.5 ? 'bg-amber-500' : 'bg-emerald-500'}`} style={{ width: `${Math.min(analysis.summary.compromisePercentage * 100, 100)}%` }}></div>
