      </footer>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Calculator, 
  UserCircle,
  Plus,
  Tag,
  DollarSign,
  Type as TypeIcon,
  History,
  Sparkles,
  AlertTriangle,
  Copy
} from 'lucide-react';
import { FinanceItem, HealthStatus, FinanceAnalysis } from './types';
import ExpenseTable from './components/ExpenseTable';
import { analyzeFinanceData, parseNaturalLanguage } from './services/geminiService';

const App: React.FC = () => {
  // Estado global de todos os meses/anos: Record<"MES-ANO", FinanceItem[]>
  const [allLedgers, setAllLedgers] = useState<Record<string, FinanceItem[]>>(() => {
    const saved = localStorage.getItem('mf_ledgers_v2');
    if (saved) return JSON.parse(saved);
    return {};
  });

  const [globalFilter, setGlobalFilter] = useState({ 
    month: new Date().getMonth() + 1, 
    year: 2026 // Ano inicial conforme solicitado
  });

  const currentKey = `${globalFilter.month}-${globalFilter.year}`;
  const currentItems = allLedgers[currentKey] || [];

  const [analysis, setAnalysis] = useState<FinanceAnalysis | null>(null);
  const [loading, setLoading] = useState(false);
  const [parsing, setParsing] = useState(false);
  const [nlpText, setNlpText] = useState('');

  // Estados do Formulário Manual
  const [mDesc, setMDesc] = useState('');
  const [mVal, setMVal] = useState('');
  const [mCat, setMCat] = useState<'house' | 'fixed' | 'work' | 'thirdParty'>('house');
  const [mInstPaid, setMInstPaid] = useState('');
  const [mInstTotal, setMInstTotal] = useState('');

  useEffect(() => {
    localStorage.setItem('mf_ledgers_v2', JSON.stringify(allLedgers));
  }, [allLedgers]);

  // Limpa análise ao trocar de mês
  useEffect(() => {
    setAnalysis(null);
  }, [currentKey]);

  const updateItem = (id: string, updates: Partial<FinanceItem>) => {
    setAllLedgers(prev => ({
      ...prev,
      [currentKey]: (prev[currentKey] || []).map(i => i.id === id ? { ...i, ...updates } : i)
    }));
  };

  const removeItem = (id: string) => {
    setAllLedgers(prev => ({
      ...prev,
      [currentKey]: (prev[currentKey] || []).filter(i => i.id !== id)
    }));
  };

  const handleManualValueChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const digits = e.target.value.replace(/\D/g, '');
    if (!digits) { setMVal(''); return; }
    const amount = parseInt(digits) / 100;
    setMVal(new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(amount));
  };

  const addManualItem = () => {
    const numericValue = parseFloat(mVal.replace(/[^\d,]/g, '').replace(',', '.')) || 0;
    if (!mDesc || numericValue <= 0) return;

    const newItem: FinanceItem = {
      id: Math.random().toString(36).substr(2, 9),
      description: mDesc,
      value: numericValue,
      category: mCat,
      paidInstallments: mInstPaid ? parseInt(mInstPaid) : undefined,
      totalInstallments: mInstTotal ? parseInt(mInstTotal) : undefined,
      status: 'pending'
    };

    setAllLedgers(prev => ({
      ...prev,
      [currentKey]: [...(prev[currentKey] || []), newItem]
    }));
    setMDesc(''); setMVal(''); setMInstPaid(''); setMInstTotal('');
  };

  const copyPreviousMonth = () => {
    const prevMonth = globalFilter.month === 1 ? 12 : globalFilter.month - 1;
    const prevYear = globalFilter.month === 1 ? globalFilter.year - 1 : globalFilter.year;
    const prevKey = `${prevMonth}-${prevYear}`;
    const prevItems = allLedgers[prevKey] || [];

    if (prevItems.length === 0) {
      alert(`Nenhum dado encontrado em ${months[prevMonth - 1]}/${prevYear} para copiar.`);
      return;
    }

    if (confirm(`Deseja copiar todos os ${prevItems.length} itens de ${months[prevMonth - 1]}/${prevYear}?`)) {
      const clonedItems = prevItems.map(item => ({
        ...item,
        id: Math.random().toString(36).substr(2, 9),
        status: 'pending' as const // Sempre inicia como pendente no novo mês
      }));

      setAllLedgers(prev => ({
        ...prev,
        [currentKey]: [...(prev[currentKey] || []), ...clonedItems]
      }));
    }
  };

  const runAnalysis = async () => {
    if (currentItems.length === 0) return;
    setLoading(true);
    try {
      const result = await analyzeFinanceData(currentItems);
      setAnalysis(result);
    } catch (err) {
      alert('Erro na análise Master Finance.');
    } finally {
      setLoading(false);
    }
  };

  const handleNLP = async () => {
    if (!nlpText.trim()) return;
    setParsing(true);
    try {
      const parsedItems = await parseNaturalLanguage(nlpText);
      const newItems: FinanceItem[] = parsedItems.map(item => ({
        id: Math.random().toString(36).substr(2, 9),
        description: item.description || 'Novo Item',
        value: item.value || 0,
        category: item.category as any || 'house',
        paidInstallments: item.paidInstallments,
        totalInstallments: item.totalInstallments,
        status: 'pending'
      }));
      setAllLedgers(prev => ({
        ...prev,
        [currentKey]: [...(prev[currentKey] || []), ...newItems]
      }));
      setNlpText('');
    } catch (err) {
      alert('Erro ao processar com IA.');
    } finally {
      setParsing(false);
    }
  };

  const fmt = (v: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v);

  const totals = useMemo(() => {
    const workIncome = currentItems.filter(i => i.category === 'work').reduce((a, b) => a + b.value, 0);
    const expenses = currentItems.filter(i => i.category === 'house' || i.category === 'fixed');
    const totalExpenses = expenses.reduce((a, b) => a + b.value, 0);
    const paidExpenses = expenses.filter(i => i.status === 'paid').reduce((a, b) => a + b.value, 0);
    const pendingExpenses = expenses.filter(i => i.status === 'pending').reduce((a, b) => a + b.value, 0);

    return { workIncome, totalExpenses, paidExpenses, pendingExpenses };
  }, [currentItems]);

  const years = [2026, 2027, 2028, 2029, 2030];
  const months = ["Janeiro", "Fevereiro", "Março", "Abril", "Maio", "Junho", "Julho", "Agosto", "Setembro", "Outubro", "Novembro", "Dezembro"];

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col font-sans text-slate-900">
      <header className="bg-white border-b border-slate-200 h-20 flex items-center justify-between px-8 sticky top-0 z-50">
        <div className="flex items-center gap-4">
          <div className="w-10 h-10 bg-slate-900 rounded-xl flex items-center justify-center font-black text-white text-xs shadow-xl">MF</div>
          <div>
            <h1 className="text-sm font-black uppercase tracking-[0.2em] text-slate-800">Master Finance</h1>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Controle por Mês/Ano</p>
          </div>
        </div>
        <div className="flex items-center gap-6">
          <div className="flex items-center bg-slate-100 border border-slate-200 rounded-xl p-1">
            <select value={globalFilter.month} onChange={(e) => setGlobalFilter(prev => ({ ...prev, month: parseInt(e.target.value) }))} className="bg-transparent text-[10px] font-black uppercase tracking-widest px-4 py-2 outline-none cursor-pointer">
              {months.map((m, i) => <option key={i} value={i+1}>{m}</option>)}
            </select>
            <div className="w-[1px] h-4 bg-slate-300"></div>
            <select value={globalFilter.year} onChange={(e) => setGlobalFilter(prev => ({ ...prev, year: parseInt(e.target.value) }))} className="bg-transparent text-[10px] font-black uppercase tracking-widest px-4 py-2 outline-none cursor-pointer">
              {years.map(y => <option key={y} value={y}>{y}</option>)}
            </select>
          </div>
          <UserCircle size={28} className="text-slate-300" />
        </div>
      </header>

      <main className="flex-1 max-w-7xl mx-auto w-full p-8 space-y-8 pb-32">
        {/* Formulário de Lançamento Manual */}
        <section className="bg-white border border-slate-200 shadow-sm rounded-2xl p-6 md:p-8">
          <div className="flex items-center gap-3 mb-6 border-b border-slate-100 pb-4">
            <Plus size={18} className="text-blue-600" />
            <h2 className="text-[11px] font-black text-slate-700 uppercase tracking-[0.2em]">Lançamento Manual • {months[globalFilter.month - 1]}/{globalFilter.year}</h2>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-12 gap-5 items-end">
            <div className="md:col-span-2">
              <label className="flex items-center gap-2 text-[10px] font-black text-slate-400 uppercase mb-2"><Tag size={12} /> Categoria</label>
              <select value={mCat} onChange={e => setMCat(e.target.value as any)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-xs font-bold focus:ring-4 focus:ring-blue-500/5 outline-none transition-all">
                <option value="house">🏠 Casa</option>
                <option value="fixed">📅 Mensal Fixa</option>
                <option value="work">📥 Trabalho</option>
                <option value="thirdParty">💳 Terceiros</option>
              </select>
            </div>
            <div className="md:col-span-3">
              <label className="flex items-center gap-2 text-[10px] font-black text-slate-400 uppercase mb-2"><TypeIcon size={12} /> Descrição</label>
              <input type="text" placeholder="Ex: Aluguel" value={mDesc} onChange={e => setMDesc(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-xs font-bold outline-none" />
            </div>
            <div className="md:col-span-2">
              <label className="flex items-center gap-2 text-[10px] font-black text-slate-400 uppercase mb-2"><DollarSign size={12} /> Valor</label>
              <input type="text" placeholder="R$ 0,00" value={mVal} onChange={handleManualValueChange} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-xs font-mono font-bold outline-none" />
            </div>
            <div className="md:col-span-1">
              <label className="flex items-center gap-2 text-[10px] font-black text-slate-400 uppercase mb-2"><History size={12} /> Parcela</label>
              <div className="flex items-center bg-slate-50 border border-slate-200 rounded-xl px-3 py-3 text-xs">
                <input type="number" placeholder="0" value={mInstPaid} onChange={e => setMInstPaid(e.target.value)} className="w-full text-center bg-transparent outline-none font-bold" />
                <span className="px-1 font-black text-slate-300">/</span>
                <input type="number" placeholder="0" value={mInstTotal} onChange={e => setMInstTotal(e.target.value)} className="w-full text-center bg-transparent outline-none font-bold" />
              </div>
            </div>
            <div className="md:col-span-4 flex flex-col sm:flex-row gap-2">
              <button onClick={addManualItem} className="flex-1 bg-slate-900 hover:bg-slate-800 text-white font-black py-3.5 rounded-xl text-[10px] uppercase tracking-[0.2em] transition-all shadow-lg active:scale-95 flex items-center justify-center gap-2">
                <Plus size={14} /> Adicionar
              </button>
              <button onClick={copyPreviousMonth} className="flex-1 bg-white hover:bg-slate-50 text-slate-600 font-black py-3.5 rounded-xl text-[10px] uppercase tracking-[0.2em] transition-all border border-slate-200 shadow-sm active:scale-95 flex items-center justify-center gap-2">
                <Copy size={14} /> Copiar mês anterior
              </button>
            </div>
          </div>
        </section>

