        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
          <div className="lg:col-span-8 space-y-6">
            <ExpenseTable title="🏠 Contas da Casa" icon="" type="expense" showStatus={true} items={currentItems.filter(i => i.category === 'house')} onRemove={removeItem} onUpdate={updateItem} />
