import { analyzeFinanceData, parseNaturalLanguage } from './services/geminiService';

const App: React.FC = () => {
  // Estado global de todos os meses/anos: Record<"MES-ANO", FinanceItem[]>
  const [allLedgers, setAllLedgers] = useState<Record<string, FinanceItem[]>>(() => {
    const saved = localStorage.getItem('mf_ledgers_v2');
    if (saved) return JSON.parse(saved);
    return {};
  });

  const [globalFilter, setGlobalFilter] = useState({ 
    month: new Date().getMonth() + 1, 
    year: 2026 // Ano inicial 2026 conforme solicitado anteriormente
  });

  const currentKey = `${globalFilter.month}-${globalFilter.year}`;
  const currentItems = allLedgers[currentKey] || [];

  const [analysis, setAnalysis] = useState<FinanceAnalysis | null>(null);
  const [loading, setLoading] = useState(false);
  const [parsing, setParsing] = useState(false);
  const [nlpText, setNlpText] = useState('');

  // Estados do Formulário Manual
  const [mDesc, setMDesc] = useState('');
  const [mVal, setMVal] = useState('');
  const [mCat, setMCat] = useState<'house' | 'fixed' | 'work' | 'thirdParty'>('house');
  const [mInstPaid, setMInstPaid] = useState('');
  const [mInstTotal, setMInstTotal] = useState('');

  useEffect(() => {
    localStorage.setItem('mf_ledgers_v2', JSON.stringify(allLedgers));
  }, [allLedgers]);

  // Limpa análise ao trocar de mês
  useEffect(() => {
    setAnalysis(null);
  }, [currentKey]);

  const updateItem = (id: string, updates: Partial<FinanceItem>) => {
    setAllLedgers(prev => ({
      ...prev,
      [currentKey]: (prev[currentKey] || []).map(i => i.id === id ? { ...i, ...updates } : i)
    }));
  };

  const removeItem = (id: string) => {
    setAllLedgers(prev => ({
      ...prev,
      [currentKey]: (prev[currentKey] || []).filter(i => i.id !== id)
    }));
  };

  const handleManualValueChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const digits = e.target.value.replace(/\D/g, '');
    if (!digits) { setMVal(''); return; }
    const amount = parseInt(digits) / 100;
    setMVal(new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(amount));
  };

  const addManualItem = () => {
    const numericValue = parseFloat(mVal.replace(/[^\d,]/g, '').replace(',', '.')) || 0;
    if (!mDesc || numericValue <= 0) return;

    const newItem: FinanceItem = {
      id: Math.random().toString(36).substr(2, 9),
      description: mDesc,
      value: numericValue,
      category: mCat,
      paidInstallments: mInstPaid ? parseInt(mInstPaid) : undefined,
      totalInstallments: mInstTotal ? parseInt(mInstTotal) : undefined,
      status: 'pending'
    };

    setAllLedgers(prev => ({
      ...prev,
      [currentKey]: [...(prev[currentKey] || []), newItem]
    }));
    setMDesc(''); setMVal(''); setMInstPaid(''); setMInstTotal('');
  };

  const runAnalysis = async () => {
    if (currentItems.length === 0) return;
    setLoading(true);
    try {
      const result = await analyzeFinanceData(currentItems);
      setAnalysis(result);
    } catch (err) {
      alert('Erro na análise Master Finance.');
    } finally {
      setLoading(false);
    }
  };

