                    {analysis.summary.status}
                  </h3>

                  <div className="space-y-3">
                    <div className="flex justify-between items-center text-[10px] font-black uppercase text-slate-400 tracking-tighter">
                      <span>Renda Líquida:</span> <span className="text-slate-900 font-mono">{fmt(analysis.summary.totalWorkIncome)}</span>
                    </div>
                    <div className="flex justify-between items-center text-[10px] font-black uppercase text-slate-400 tracking-tighter">
                      <span>Total Gastos:</span> <span className="text-slate-900 font-mono">{fmt(analysis.summary.totalExpenses)}</span>
                    </div>
                    <div className="pt-2 border-t border-slate-100 flex justify-between items-center text-[10px] font-black uppercase tracking-tighter">
                      <span>Comprometimento:</span> 
                      <span className={(analysis.summary.compromisePercentage * 100) > 80 ? 'text-rose-600' : 'text-slate-900'}>
                        {(analysis.summary.compromisePercentage * 100).toFixed(1)}%
                      </span>
                    </div>
                  </div>
                  {analysis.summary.alertMessage && (
                    <div className="mt-4 p-4 bg-rose-50 text-rose-700 text-[10px] font-black uppercase rounded-lg border border-rose-100 flex gap-2 leading-relaxed">
                      <AlertTriangle size={14} className="shrink-0 mt-0.5" />
                      {analysis.summary.alertMessage.replace(/\*\*/g, '')}
                    </div>
                  )}
                </div>
              )}
            </div>
          </div>
        </div>
      </main>

      <footer className="h-10 flex items-center justify-center text-[8px] font-black text-slate-300 uppercase tracking-[0.4em]">
        Master Finance Engine • 2026
      </footer>
    </div>
  );
};

