  const deleteTab = (idToDelete: string) => {
    if (tabs.length <= 1) {
      alert("Ação não permitida: Você deve manter pelo menos uma planilha ativa.");
      return;
    }

    const tab = tabs.find(t => t.id === idToDelete);
    if (!tab) return;

    if (window.confirm(`Excluir permanentemente a planilha "${tab.name}"?`)) {
      const indexToDelete = tabs.findIndex(t => t.id === idToDelete);
      const newTabs = tabs.filter(t => t.id !== idToDelete);

      if (idToDelete === activeTabId) {
        const nextIndex = indexToDelete === 0 ? 0 : indexToDelete - 1;
        setActiveTabId(newTabs[nextIndex].id);
      }

      setTabs(newTabs);
    }
