  const totals = useMemo(() => {
    const items = activeTab?.items || [];
    const workIncome = items.filter(i => i.category === 'work').reduce((a, b) => a + b.value, 0);
    const expenses = items.filter(i => i.category === 'house' || i.category === 'fixed');
    const totalExpenses = expenses.reduce((a, b) => a + b.value, 0);
    const paidExpenses = expenses.filter(i => i.status === 'paid').reduce((a, b) => a + b.value, 0);
    const pendingExpenses = expenses.filter(i => i.status === 'pending').reduce((a, b) => a + b.value, 0);

    return { workIncome, totalExpenses, paidExpenses, pendingExpenses };
  }, [activeTab]);

  const runAnalysis = async () => {
    if (!activeTab || activeTab.items.length === 0) return;
    setAnalysisLoading(true);
    try {
      const result = await analyzeFinanceData(activeTab.items);
      setAnalysis(result);
    } catch (err) {
      alert('Erro na análise Master Finance.');
    } finally {
      setAnalysisLoading(false);
    }
  };

  const fmt = (v: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v);

  if (loading) {
    return (
      <div className="h-screen w-full flex flex-col items-center justify-center bg-slate-900 text-white">
        <RefreshCw className="animate-spin mb-4 text-blue-500" size={32} />
        <p className="text-[10px] font-black uppercase tracking-[0.3em] animate-pulse">Sincronizando Master Finance Cloud...</p>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col font-sans text-slate-900">
      <header className="bg-white border-b border-slate-200 h-16 flex items-center justify-between px-8 sticky top-0 z-50">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 bg-slate-900 rounded-lg flex items-center justify-center font-black text-white text-[10px]">MF</div>
          <h1 className="text-xs font-black uppercase tracking-[0.2em] text-slate-800">Master Finance</h1>
        </div>

        <div className="flex items-center gap-6">
          <div className="flex items-center gap-2">
            {syncStatus === 'synced' && <div className="flex items-center gap-1.5 text-emerald-600"><CheckCircle2 size={14} /><span className="text-[9px] font-black uppercase tracking-widest hidden sm:block">Nuvem Sincronizada</span></div>}
            {syncStatus === 'syncing' && <div className="flex items-center gap-1.5 text-amber-500"><RefreshCw size={14} className="animate-spin" /><span className="text-[9px] font-black uppercase tracking-widest hidden sm:block">Sincronizando...</span></div>}
            {syncStatus === 'error' && <div className="flex items-center gap-1.5 text-rose-600"><CloudOff size={14} /><span className="text-[9px] font-black uppercase tracking-widest hidden sm:block">Erro de Conexão</span></div>}
            {syncStatus === 'local' && <div className="flex items-center gap-1.5 text-slate-400"><Cloud size={14} /><span className="text-[9px] font-black uppercase tracking-widest hidden sm:block">Apenas Local</span></div>}
          </div>
          <UserCircle size={24} className="text-slate-300" />
        </div>
      </header>

      <main className="flex-1 max-w-7xl mx-auto w-full p-6 space-y-6">
        <div className="flex items-center border-b border-slate-200 overflow-x-auto no-scrollbar bg-white rounded-t-xl px-2">
          {tabs.map((tab) => (
            <div 
              key={tab.id}
              onClick={() => setActiveTabId(tab.id)}
              className={`flex items-center gap-3 px-6 py-4 border-b-2 transition-all cursor-pointer whitespace-nowrap group ${
                activeTabId === tab.id 
                  ? 'border-slate-900 bg-slate-50/50 text-slate-900' 
                  : 'border-transparent text-slate-400 hover:text-slate-600 hover:bg-slate-50/30'
              }`}
            >
              {activeTabId === tab.id ? (
                <input
                  type="text"
                  value={tab.name}
                  onChange={(e) => updateTabName(tab.id, e.target.value)}
                  onClick={(e) => e.stopPropagation()}
                  className="text-[10px] font-black uppercase tracking-widest bg-transparent outline-none border-none p-0 focus:ring-0 w-32 md:w-auto"
                  autoFocus
