const SYSTEM_INSTRUCTION_ANALYSIS = `
Você é o "Master Finance", assistente de gestão de fluxo de caixa.
Sua função é analisar dados financeiros e gerar um Resumo Executivo e Status de Saúde.

LOGICA DE CÁLCULO RIGOROSA:
1. Gasto Total = Soma de 'house' (Casa) + 'fixed' (Mensais).
2. Entradas (Trabalho) = Categoria 'work'. Representa o salário líquido.
3. Entradas (Terceiros) = Categoria 'thirdParty'. Tratadas como compensação. NÃO somar como renda disponível.
4. Percentual de Comprometimento = Gasto Total / Entradas (Trabalho). 
   IMPORTANTE: Retorne este valor SEMPRE como um decimal (ex: 0.7014 para 70.14% ou 5.0 para 500%).
5. ALERTA DE RISCO: Se Gasto Total > 80% das Entradas (Trabalho), o campo 'alertMessage' DEVE conter o aviso de risco.

STATUS:
- Saudável: Comprometimento <= 0.5
- Atenção: Comprometimento > 0.5 e <= 0.8
- Crítico: Comprometimento > 0.8

TOM DE VOZ: Profissional, direto, objetivo e levemente analítico.
RETORNE APENAS JSON.
`;

const SYSTEM_INSTRUCTION_PARSER = `
Você é o processador de dados do "Master Finance".
Extraia itens financeiros de texto natural e categorize-os em: house, fixed, work, thirdParty.
`;

export async function parseNaturalLanguage(text: string): Promise<Partial<FinanceItem>[]> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Extraia os dados deste texto: "${text}"`,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION_PARSER,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            description: { type: Type.STRING },
            value: { type: Type.NUMBER },
            category: { type: Type.STRING, enum: ['house', 'fixed', 'work', 'thirdParty'] },
            paidInstallments: { type: Type.NUMBER, nullable: true },
            totalInstallments: { type: Type.NUMBER, nullable: true },
          },
          required: ["description", "value", "category"]
        }
      }
    }
  });
  return JSON.parse(response.text.trim());
}

export async function analyzeFinanceData(items: FinanceItem[]): Promise<FinanceAnalysis> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const income = items.filter(i => i.category === 'work').reduce((a, b) => a + b.value, 0);
  const expenses = items.filter(i => i.category === 'house' || i.category === 'fixed').reduce((a, b) => a + b.value, 0);
  const expectedRatio = income > 0 ? expenses / income : (expenses > 0 ? 1 : 0);

  const prompt = `Analise estes dados: ${JSON.stringify(items)}. O Gasto Total é ${expenses} e a Renda Trabalho é ${income}. Calcule o comprometimento exato.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: prompt,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION_ANALYSIS,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          summary: {
            type: Type.OBJECT,
            properties: {
              totalWorkIncome: { type: Type.NUMBER },
              totalExpenses: { type: Type.NUMBER },
              remainingBalance: { type: Type.NUMBER },
              compromisePercentage: { type: Type.NUMBER, description: "Ratio decimal (ex: 0.75)" },
              status: { type: Type.STRING },
              alertMessage: { type: Type.STRING, nullable: true }
            },
            required: ["totalWorkIncome", "totalExpenses", "remainingBalance", "compromisePercentage", "status"]
          }
        },
        required: ["summary"]
      }
    }
  });

  const data = JSON.parse(response.text.trim());

  // Normalização Inteligente de Escala:
  // Se a IA retornar 70.14 para um ratio de 0.7014, nós detectamos a diferença de 100x
  const aiVal = data.summary.compromisePercentage;

  if (expectedRatio > 0) {
    const diffToRatio = Math.abs(aiVal - expectedRatio);
    const diffToPercentage = Math.abs((aiVal / 100) - expectedRatio);

    // Se dividir por 100 aproxima o valor do ratio esperado muito mais do que o valor original, corrigimos.
    if (diffToPercentage < diffToRatio && aiVal > 1) {
      data.summary.compromisePercentage = aiVal / 100;
    }
  } else if (aiVal > 1 && expenses <= income) {
      // Fallback básico para segurança
      data.summary.compromisePercentage = aiVal / 100;
  }

  return {
    ...data,
    analysisDate: new Date().toLocaleDateString('pt-BR')
  };
}

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { 
  Calculator, 
  UserCircle,
  Plus,
  AlertTriangle,
  Copy,
  Trash2,
  Cloud,
  CloudOff,
  RefreshCw,
  CheckCircle2
} from 'lucide-react';
import { FinanceItem, HealthStatus, FinanceAnalysis, Ledger } from './types';
import ExpenseTable from './components/ExpenseTable';
import { analyzeFinanceData } from './services/geminiService';
import { saveUserData, loadUserData } from './firebase';

const App: React.FC = () => {
  const [tabs, setTabs] = useState<Ledger[]>([]);
  const [activeTabId, setActiveTabId] = useState<string>('');
  const [syncStatus, setSyncStatus] = useState<'synced' | 'syncing' | 'error' | 'local'>('syncing');
  const [loading, setLoading] = useState(true);
  const [analysisLoading, setAnalysisLoading] = useState(false);
  const [analysis, setAnalysis] = useState<FinanceAnalysis | null>(null);

  // Estados do Formulário Manual
  const [mDesc, setMDesc] = useState('');
  const [mVal, setMVal] = useState('');
  const [mCat, setMCat] = useState<'house' | 'fixed' | 'work' | 'thirdParty'>('house');
  const [mInstPaid, setMInstPaid] = useState('');
  const [mInstTotal, setMInstTotal] = useState('');

  // 1. Carregamento Inicial
  useEffect(() => {
    const init = async () => {
      setSyncStatus('syncing');
      try {
        const cloudData = await loadUserData();
        if (cloudData && cloudData.length > 0) {
          setTabs(cloudData);
          setActiveTabId(cloudData[0].id);
          setSyncStatus('synced');
        } else {
          const savedLocal = localStorage.getItem('mf_tabs_v6');
          if (savedLocal) {
            const parsed = JSON.parse(savedLocal);
            setTabs(parsed);
            setActiveTabId(parsed[0]?.id || '');
          } else {
            const defaultTab: Ledger = {
              id: 'tab-' + Date.now(),
              name: 'Planilha Principal',
              month: new Date().getMonth() + 1,
              year: new Date().getFullYear(),
              items: []
            };
            setTabs([defaultTab]);
            setActiveTabId(defaultTab.id);
          }
          setSyncStatus('local');
        }
      } catch (e) {
        setSyncStatus('error');
      } finally {
        setLoading(false);
      }
    };
    init();
  }, []);

  // 2. Auto-Save Debounced
  useEffect(() => {
    if (loading || tabs.length === 0) return;
    localStorage.setItem('mf_tabs_v6', JSON.stringify(tabs));
    setSyncStatus('syncing');
    const timeout = setTimeout(async () => {
      try {
        await saveUserData(tabs);
        setSyncStatus('synced');
      } catch (e) {
        setSyncStatus('error');
      }
    }, 1500);
    return () => clearTimeout(timeout);
  }, [tabs, loading]);

  const activeTab = useMemo(() => {
    return tabs.find(t => t.id === activeTabId) || tabs[0];
  }, [tabs, activeTabId]);

  const updateItem = (id: string, updates: Partial<FinanceItem>) => {
    setTabs(prev => prev.map(tab => 
      tab.id === activeTabId 
        ? { ...tab, items: tab.items.map(i => i.id === id ? { ...i, ...updates } : i) }
        : tab
    ));
  };

  const removeItem = (id: string) => {
    setTabs(prev => prev.map(tab => 
      tab.id === activeTabId 
        ? { ...tab, items: tab.items.filter(i => i.id !== id) }
        : tab
    ));
  };

  const handleManualValueChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const digits = e.target.value.replace(/\D/g, '');
    if (!digits) { setMVal(''); return; }
    const amount = parseInt(digits) / 100;
    setMVal(new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(amount));
  };

  const addManualItem = () => {
    const numericValue = parseFloat(mVal.replace(/[^\d,]/g, '').replace(',', '.')) || 0;
    if (!mDesc || numericValue < 0) return;
    const newItem: FinanceItem = {
      id: 'item-' + Math.random().toString(36).substr(2, 9),
      description: mDesc,
      value: numericValue,
      category: mCat,
      paidInstallments: mInstPaid ? parseInt(mInstPaid) : undefined,
      totalInstallments: mInstTotal ? parseInt(mInstTotal) : undefined,
      status: 'pending'
    };
    setTabs(prev => prev.map(tab => tab.id === activeTabId ? { ...tab, items: [...tab.items, newItem] } : tab));
    setMDesc(''); setMVal(''); setMInstPaid(''); setMInstTotal('');
  };

  const addNewTab = () => {
    const newTab: Ledger = {
      id: 'tab-' + Date.now(),
      name: 'Nova Planilha',
      month: new Date().getMonth() + 1,
      year: new Date().getFullYear(),
      items: []
    };
    setTabs(prev => [...prev, newTab]);
    setActiveTabId(newTab.id);
  };

  const updateTabName = (id: string, newName: string) => {
    setTabs(prev => prev.map(t => t.id === id ? { ...t, name: newName } : t));
  };

  const duplicateActiveTab = () => {
    const newTab: Ledger = {
      ...activeTab,
      id: 'tab-' + Date.now(),
      name: `${activeTab.name} (Cópia)`,
      items: activeTab.items.map(item => ({ ...item, id: 'item-' + Math.random().toString(36).substr(2, 9) }))
    };
    setTabs(prev => [...prev, newTab]);
    setActiveTabId(newTab.id);
  };

  const deleteTab = (idToDelete: string) => {
    if (tabs.length <= 1) return alert("Mantenha ao menos uma planilha.");
    if (window.confirm("Excluir esta planilha?")) {
      const index = tabs.findIndex(t => t.id === idToDelete);
      const newTabs = tabs.filter(t => t.id !== idToDelete);
      if (idToDelete === activeTabId) {
        setActiveTabId(newTabs[index === 0 ? 0 : index - 1].id);
      }
      setTabs(newTabs);
    }
  };

  const totals = useMemo(() => {
    const items = activeTab?.items || [];
    const workIncome = items.filter(i => i.category === 'work').reduce((a, b) => a + b.value, 0);
    const expenses = items.filter(i => i.category === 'house' || i.category === 'fixed');
    const totalExpenses = expenses.reduce((a, b) => a + b.value, 0);
    const paidExpenses = expenses.filter(i => i.status === 'paid').reduce((a, b) => a + b.value, 0);
    const pendingExpenses = expenses.filter(i => i.status === 'pending').reduce((a, b) => a + b.value, 0);
    return { workIncome, totalExpenses, paidExpenses, pendingExpenses };
  }, [activeTab]);

  const runAnalysis = async () => {
    if (!activeTab || activeTab.items.length === 0) return;
    setAnalysisLoading(true);
    try {
      const result = await analyzeFinanceData(activeTab.items);
      setAnalysis(result);
    } catch (err) {
      alert('Erro na análise.');
    } finally {
      setAnalysisLoading(false);
    }
  };

  const fmt = (v: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v);

  if (loading) return (
    <div className="h-screen w-full flex flex-col items-center justify-center bg-slate-900 text-white">
      <RefreshCw className="animate-spin mb-4 text-blue-500" size={32} />
      <p className="text-[10px] font-black uppercase tracking-[0.3em]">Master Finance Cloud Sync...</p>
    </div>
  );

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col font-sans text-slate-900">
      <header className="bg-white border-b border-slate-200 h-16 flex items-center justify-between px-8 sticky top-0 z-50">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 bg-slate-900 rounded-lg flex items-center justify-center font-black text-white text-[10px]">MF</div>
          <h1 className="text-xs font-black uppercase tracking-[0.2em] text-slate-800">Master Finance</h1>
        </div>
        <div className="flex items-center gap-6">
          <div className="flex items-center gap-2">
            {syncStatus === 'synced' && <div className="flex items-center gap-1.5 text-emerald-600"><CheckCircle2 size={14} /><span className="text-[9px] font-black uppercase tracking-widest hidden sm:block">Nuvem Sincronizada</span></div>}
            {syncStatus === 'syncing' && <div className="flex items-center gap-1.5 text-amber-500"><RefreshCw size={14} className="animate-spin" /><span className="text-[9px] font-black uppercase tracking-widest hidden sm:block">Sincronizando...</span></div>}
            {syncStatus === 'error' && <div className="flex items-center gap-1.5 text-rose-600"><CloudOff size={14} /><span className="text-[9px] font-black uppercase tracking-widest hidden sm:block">Erro de Conexão</span></div>}
          </div>
          <UserCircle size={24} className="text-slate-300" />
        </div>
      </header>

      <main className="flex-1 max-w-7xl mx-auto w-full p-6 space-y-6">
        {/* Tab Bar */}
        <div className="flex items-center border-b border-slate-200 overflow-x-auto no-scrollbar bg-white rounded-t-xl px-2">
          {tabs.map((tab) => (
            <div 
              key={tab.id}
              onClick={() => setActiveTabId(tab.id)}
              className={`flex items-center gap-3 px-6 py-4 border-b-2 transition-all cursor-pointer whitespace-nowrap group ${
                activeTabId === tab.id ? 'border-slate-900 bg-slate-50/50 text-slate-900' : 'border-transparent text-slate-400 hover:text-slate-600 hover:bg-slate-50/30'
              }`}
            >
              {activeTabId === tab.id ? (
                <input type="text" value={tab.name} onChange={(e) => updateTabName(tab.id, e.target.value)} onClick={(e) => e.stopPropagation()} className="text-[10px] font-black uppercase tracking-widest bg-transparent outline-none border-none p-0 focus:ring-0 w-32 md:w-auto" autoFocus />
              ) : (
                <span className="text-[10px] font-black uppercase tracking-widest">{tab.name}</span>
              )}
              {activeTabId === tab.id && (
                <div className="flex items-center gap-3 ml-2 border-l border-slate-200 pl-3">
                  <button onClick={(e) => { e.stopPropagation(); duplicateActiveTab(); }} className="p-1 hover:text-emerald-600 transition-colors"><Copy size={12} /></button>
                  <button onClick={(e) => { e.stopPropagation(); deleteTab(tab.id); }} className="p-1 hover:text-rose-600 transition-colors"><Trash2 size={13} /></button>
                </div>
              )}
            </div>
          ))}
          <button onClick={addNewTab} className="px-6 py-4 text-slate-400 hover:text-blue-600 transition-all flex items-center gap-2 border-b-2 border-transparent"><Plus size={14} /><span className="text-[10px] font-black uppercase tracking-widest">Nova</span></button>
        </div>

        {/* Input Form */}
        <section className="bg-white border border-slate-200 rounded-xl p-6 shadow-sm">
          <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-12 gap-4 items-end">
            <div className="md:col-span-2">
              <label className="text-[9px] font-black text-slate-400 uppercase mb-2 block tracking-widest">Categoria</label>
              <select value={mCat} onChange={e => setMCat(e.target.value as any)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-xs font-bold outline-none focus:border-slate-900 transition-colors">
                <option value="house">🏠 Casa</option>
                <option value="fixed">📅 Fixa</option>
                <option value="work">📥 Trabalho</option>
                <option value="thirdParty">💳 Terceiros</option>
              </select>
            </div>
            <div className="md:col-span-4">
              <label className="text-[9px] font-black text-slate-400 uppercase mb-2 block tracking-widest">Descrição</label>
              <input type="text" placeholder="Ex: Aluguel" value={mDesc} onChange={e => setMDesc(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-xs font-bold outline-none focus:border-slate-900 transition-colors" />
            </div>
            <div className="md:col-span-2">
              <label className="text-[9px] font-black text-slate-400 uppercase mb-2 block tracking-widest">Valor</label>
              <input type="text" placeholder="R$ 0,00" value={mVal} onChange={handleManualValueChange} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-xs font-mono font-bold outline-none focus:border-slate-900 transition-colors" />
            </div>
            <div className="md:col-span-2">
              <label className="text-[9px] font-black text-slate-400 uppercase mb-2 block tracking-widest">Parcelas</label>
              <div className="flex items-center bg-slate-50 border border-slate-200 rounded-lg px-2 py-2 text-xs focus-within:border-slate-900 transition-colors">
                <input type="number" placeholder="0" value={mInstPaid} onChange={e => setMInstPaid(e.target.value)} className="w-full text-center bg-transparent outline-none font-bold" />
                <span className="px-1 text-slate-300 font-black">/</span>
                <input type="number" placeholder="0" value={mInstTotal} onChange={e => setMInstTotal(e.target.value)} className="w-full text-center bg-transparent outline-none font-bold" />
              </div>
            </div>
            <div className="md:col-span-2">
              <button onClick={addManualItem} className="w-full bg-slate-900 text-white font-black py-2.5 rounded-lg text-[10px] uppercase tracking-widest active:scale-95 transition-all hover:bg-slate-800">Lançar</button>
            </div>
          </div>
        </section>

        {/* Content Area */}
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
          <div className="lg:col-span-8 space-y-4">
            <ExpenseTable title="🏠 Contas da Casa" icon="" type="expense" showStatus={true} items={activeTab.items.filter(i => i.category === 'house')} onRemove={removeItem} onUpdate={updateItem} />
            <ExpenseTable title="📅 Contas Mensais" icon="" type="expense" showStatus={true} items={activeTab.items.filter(i => i.category === 'fixed')} onRemove={removeItem} onUpdate={updateItem} />
            <ExpenseTable title="📥 Entradas" icon="" type="income" items={activeTab.items.filter(i => i.category === 'work')} onRemove={removeItem} onUpdate={updateItem} />
            <ExpenseTable title="💳 Terceiros" icon="" type="neutral" items={activeTab.items.filter(i => i.category === 'thirdParty')} onRemove={removeItem} onUpdate={updateItem} />

            <div className="bg-white border border-slate-200 rounded-xl overflow-hidden shadow-sm">
              <div className="grid grid-cols-1 sm:grid-cols-4 divide-y sm:divide-y-0 sm:divide-x divide-slate-100">
