export const getUserId = () => {
  let uid = localStorage.getItem('mf_user_id_v2');
  if (!uid) {
    uid = 'u_' + Math.random().toString(36).substring(2, 15);
    localStorage.setItem('mf_user_id_v2', uid);
  }
  return uid;
};

export const saveUserData = async (tabs: any[]) => {
  const uid = getUserId();
  try {
    const userDoc = doc(db, "users", uid);
    await setDoc(userDoc, {
      tabs,
      updatedAt: new Date().toISOString()
    }, { merge: true });
    return true;
  } catch (e: any) {
    // Se estiver offline, o Firestore já gerencia o cache local para escrita, 
    // mas lançamos o erro para o App.tsx atualizar o ícone de status.
    console.warn("Firebase save warning (likely offline):", e.message);
    throw e;
  }
};

export const loadUserData = async () => {
  const uid = getUserId();
  try {
    const userDoc = doc(db, "users", uid);
    // getDoc tentará o servidor. Se falhar por estar offline, capturamos no catch.
    const docSnap = await getDoc(userDoc);
    if (docSnap.exists()) {
      return docSnap.data().tabs;
    }
    return null;
  } catch (e: any) {
    // Erros de "offline" ou "unavailable" são ignorados aqui para permitir o fallback do App.tsx
    console.warn("Firestore indisponível momentaneamente. O app usará dados locais.");
    return null;
  }
};

