import React, { useState } from 'react';
import { auth, signInWithEmailAndPassword, createUserWithEmailAndPassword } from '../firebase';
import { LogIn, UserPlus, ShieldCheck, AlertCircle } from 'lucide-react';

const AuthForm: React.FC = () => {
  const [isLogin, setIsLogin] = useState(true);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    try {
      if (isLogin) {
        await signInWithEmailAndPassword(auth, email, password);
      } else {
        await createUserWithEmailAndPassword(auth, email, password);
      }
    } catch (err: any) {
      console.error(err);
      setError(err.message.includes('auth/invalid-credential') 
        ? 'E-mail ou senha incorretos.' 
        : 'Ocorreu um erro. Tente novamente.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50 p-6">
      <div className="w-full max-w-md bg-white border border-slate-200 rounded-2xl shadow-xl overflow-hidden">
        <div className="bg-slate-900 p-8 text-center">
          <div className="w-12 h-12 bg-white rounded-xl mx-auto flex items-center justify-center font-black text-slate-900 text-lg mb-4 shadow-lg">MF</div>
          <h2 className="text-white text-xs font-black uppercase tracking-[0.3em]">Master Finance</h2>
          <p className="text-slate-400 text-[10px] mt-2 font-bold uppercase tracking-widest">
            {isLogin ? 'Bem-vindo de volta' : 'Crie sua conta profissional'}
          </p>
        </div>

        <form onSubmit={handleSubmit} className="p-8 space-y-5">
          {error && (
            <div className="bg-rose-50 border border-rose-100 p-3 rounded-lg flex items-center gap-2 text-rose-600 text-[10px] font-bold uppercase">
              <AlertCircle size={14} /> {error}
            </div>
          )}

          <div>
            <label className="text-[9px] font-black text-slate-400 uppercase mb-2 block tracking-widest">E-mail</label>
            <input 
              type="email" 
              required
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="w-full bg-slate-50 border border-slate-200 rounded-lg px-4 py-3 text-xs font-bold outline-none focus:border-slate-900 transition-colors"
              placeholder="seu@email.com"
            />
          </div>

          <div>
            <label className="text-[9px] font-black text-slate-400 uppercase mb-2 block tracking-widest">Senha</label>
            <input 
              type="password" 
              required
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full bg-slate-50 border border-slate-200 rounded-lg px-4 py-3 text-xs font-bold outline-none focus:border-slate-900 transition-colors"
              placeholder="••••••••"
            />
          </div>

          <button 
            type="submit" 
            disabled={loading}
            className="w-full bg-slate-900 text-white font-black py-4 rounded-xl text-[10px] uppercase tracking-widest hover:bg-slate-800 active:scale-[0.98] transition-all flex items-center justify-center gap-2 disabled:bg-slate-200"
          >
            {loading ? 'Processando...' : (
              <>
                {isLogin ? <LogIn size={14} /> : <UserPlus size={14} />}
                {isLogin ? 'Entrar no Sistema' : 'Finalizar Cadastro'}
              </>
            )}
          </button>

          <div className="pt-4 text-center">
            <button 
              type="button"
              onClick={() => setIsLogin(!isLogin)}
              className="text-[9px] font-black text-slate-400 uppercase tracking-widest hover:text-slate-900 transition-colors"
            >
              {isLogin ? 'Não tem conta? Registre-se' : 'Já tem conta? Faça Login'}
            </button>
          </div>
        </form>

        <div className="bg-slate-50 p-4 flex items-center justify-center gap-2 border-t border-slate-100">
           <ShieldCheck size={12} className="text-emerald-500" />
           <span className="text-[8px] font-black text-slate-400 uppercase tracking-widest">Conexão Segura e Criptografada</span>
        </div>
      </div>
    </div>
  );
};

export default AuthForm;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Calculator, 
  UserCircle,
  Plus,
  AlertTriangle,
  Copy,
  Trash2,
  RefreshCw,
  CheckCircle2,
  CloudOff,
  LogOut
} from 'lucide-react';
import { FinanceItem, HealthStatus, FinanceAnalysis, Ledger } from './types';
import ExpenseTable from './components/ExpenseTable';
import AuthForm from './components/AuthForm';
import { analyzeFinanceData } from './services/geminiService';
import { saveUserData, loadUserData, auth, onAuthStateChanged, signOut } from './firebase';

const App: React.FC = () => {
  const [user, setUser] = useState<any>(null);
  const [tabs, setTabs] = useState<Ledger[]>([]);
  const [activeTabId, setActiveTabId] = useState<string>('');
  const [syncStatus, setSyncStatus] = useState<'synced' | 'syncing' | 'error' | 'local'>('syncing');
  const [loading, setLoading] = useState(true);
  const [analysisLoading, setAnalysisLoading] = useState(false);
  const [analysis, setAnalysis] = useState<FinanceAnalysis | null>(null);

  const [mDesc, setMDesc] = useState('');
  const [mVal, setMVal] = useState('');
  const [mCat, setMCat] = useState<'house' | 'fixed' | 'work' | 'thirdParty'>('house');
  const [mInstPaid, setMInstPaid] = useState('');
  const [mInstTotal, setMInstTotal] = useState('');

  // Gerenciamento de Autenticação
  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      setUser(currentUser);
      if (!currentUser) {
        setTabs([]);
        setLoading(false);
      } else {
        initData();
      }
    });
    return () => unsubscribe();
  }, []);

  const initData = async () => {
    setLoading(true);
    try {
      const cloudData = await loadUserData();
      if (cloudData && Array.isArray(cloudData) && cloudData.length > 0) {
        setTabs(cloudData);
        setActiveTabId(cloudData[0].id);
        setSyncStatus('synced');
      } else {
        const defaultTab: Ledger = {
          id: 'tab-' + Date.now(),
          name: 'Planilha Principal',
          month: new Date().getMonth() + 1,
          year: new Date().getFullYear(),
          items: []
        };
        setTabs([defaultTab]);
        setActiveTabId(defaultTab.id);
        setSyncStatus('local');
      }
    } catch (e) {
      setSyncStatus('error');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (loading || tabs.length === 0 || !user) return;

    setSyncStatus('syncing');
    const timeout = setTimeout(async () => {
      try {
        await saveUserData(tabs);
        setSyncStatus('synced');
      } catch (e) {
        setSyncStatus('error');
      }
    }, 2000);

    return () => clearTimeout(timeout);
  }, [tabs, loading, user]);

  const activeTab = useMemo(() => {
    return tabs.find(t => t.id === activeTabId) || tabs[0];
  }, [tabs, activeTabId]);

  const updateItem = (id: string, updates: Partial<FinanceItem>) => {
    setTabs(prev => prev.map(tab => 
      tab.id === activeTabId 
        ? { ...tab, items: tab.items.map(i => i.id === id ? { ...i, ...updates } : i) }
        : tab
    ));
  };

  const removeItem = (id: string) => {
    setTabs(prev => prev.map(tab => 
      tab.id === activeTabId 
        ? { ...tab, items: tab.items.filter(i => i.id !== id) }
        : tab
    ));
  };

  const handleManualValueChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const digits = e.target.value.replace(/\D/g, '');
    if (!digits) { setMVal(''); return; }
    const amount = parseInt(digits) / 100;
    setMVal(new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(amount));
  };

  const addManualItem = () => {
    const numericValue = parseFloat(mVal.replace(/[^\d,]/g, '').replace(',', '.')) || 0;
    if (!mDesc || numericValue < 0) return;
    const newItem: FinanceItem = {
      id: 'item-' + Math.random().toString(36).substr(2, 9),
      description: mDesc,
      value: numericValue,
      category: mCat,
      paidInstallments: mInstPaid ? parseInt(mInstPaid) : undefined,
      totalInstallments: mInstTotal ? parseInt(mInstTotal) : undefined,
      status: 'pending'
    };
    setTabs(prev => prev.map(tab => tab.id === activeTabId ? { ...tab, items: [...tab.items, newItem] } : tab));
    setMDesc(''); setMVal(''); setMInstPaid(''); setMInstTotal('');
  };

  const addNewTab = () => {
    const newTab: Ledger = {
      id: 'tab-' + Date.now(),
      name: 'Nova Planilha',
      month: new Date().getMonth() + 1,
      year: new Date().getFullYear(),
      items: []
    };
    setTabs(prev => [...prev, newTab]);
    setActiveTabId(newTab.id);
  };

  const duplicateActiveTab = () => {
    if (!activeTab) return;
    const newTab: Ledger = {
      ...activeTab,
      id: 'tab-' + Date.now() + '-' + Math.random().toString(36).substr(2, 5),
      name: `${activeTab.name} (Cópia)`,
      items: activeTab.items.map(item => ({ ...item, id: 'item-' + Math.random().toString(36).substr(2, 9) }))
    };
    setTabs(prev => [...prev, newTab]);
    setActiveTabId(newTab.id);
  };

  const deleteTab = (idToDelete: string) => {
    if (tabs.length <= 1) return;
    if (window.confirm("Deseja realmente apagar esta planilha?")) {
      const indexToDelete = tabs.findIndex(t => t.id === idToDelete);
      const newTabs = tabs.filter(t => t.id !== idToDelete);
      if (idToDelete === activeTabId) {
        const nextIndex = indexToDelete === 0 ? 0 : indexToDelete - 1;
        setActiveTabId(newTabs[nextIndex].id);
      }
      setTabs(newTabs);
    }
  };

  const totals = useMemo(() => {
    const items = activeTab?.items || [];
    const workIncome = items.filter(i => i.category === 'work').reduce((a, b) => a + b.value, 0);
    const expenses = items.filter(i => i.category === 'house' || i.category === 'fixed');
    const totalExpenses = expenses.reduce((a, b) => a + b.value, 0);
    const paidExpenses = expenses.filter(i => i.status === 'paid').reduce((a, b) => a + b.value, 0);
    const pendingExpenses = expenses.filter(i => i.status === 'pending').reduce((a, b) => a + b.value, 0);
    return { workIncome, totalExpenses, paidExpenses, pendingExpenses };
  }, [activeTab]);

  const runAnalysis = async () => {
    if (!activeTab || activeTab.items.length === 0) return;
    setAnalysisLoading(true);
    try {
      const result = await analyzeFinanceData(activeTab.items);
      setAnalysis(result);
    } catch (err) {
      alert('Erro na análise.');
    } finally {
      setAnalysisLoading(false);
    }
  };

  const fmt = (v: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v);

  if (!user) return <AuthForm />;

  if (loading) return (
    <div className="h-screen w-full flex flex-col items-center justify-center bg-slate-900 text-white font-black text-[10px] tracking-[0.4em] uppercase">
