      <RefreshCw className="animate-spin mb-4 text-blue-500" size={32} />
      Carregando seu espaço...
    </div>
  );

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col font-sans text-slate-900">
      <header className="bg-white border-b border-slate-200 h-16 flex items-center justify-between px-8 sticky top-0 z-50">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 bg-slate-900 rounded-lg flex items-center justify-center font-black text-white text-[10px]">MF</div>
          <div>
            <h1 className="text-xs font-black uppercase tracking-[0.2em] text-slate-800">Master Finance</h1>
            <div className="flex items-center gap-1">
              <ShieldCheck size={10} className="text-emerald-500" />
              <span className="text-[8px] font-bold text-slate-400 uppercase tracking-widest">Espaço Privado</span>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-6">
          <div className="flex items-center gap-2 pr-4 border-r border-slate-100">
            {syncStatus === 'synced' && <div className="flex items-center gap-1.5 text-emerald-600"><CheckCircle2 size={14} /><span className="text-[9px] font-black uppercase tracking-widest hidden sm:block">Sincronizado</span></div>}
            {syncStatus === 'syncing' && <div className="flex items-center gap-1.5 text-amber-500"><RefreshCw size={14} className="animate-spin" /><span className="text-[9px] font-black uppercase tracking-widest hidden sm:block">Salvando...</span></div>}
          </div>

          <div className="flex items-center gap-3">
             <div className="hidden sm:flex flex-col items-end">
                <p className="text-[8px] font-black text-slate-400 uppercase tracking-tighter">Conectado como</p>
                <p className="text-[10px] font-bold text-slate-700 max-w-[150px] truncate">{user.email}</p>
             </div>
             <div className="w-8 h-8 rounded-full bg-slate-100 flex items-center justify-center text-slate-400 border border-slate-200">
               <User size={16} />
             </div>
             <button 
               onClick={() => signOut(auth)} 
               className="p-2 text-slate-300 hover:text-rose-500 transition-colors rounded-lg hover:bg-rose-50"
               title="Sair do sistema"
             >
               <LogOut size={18} />
             </button>
          </div>
        </div>
      </header>

      <main className="flex-1 max-w-7xl mx-auto w-full p-6 space-y-6">
        {/* Barra de Abas do Usuário */}
        <div className="flex items-center border-b border-slate-200 overflow-x-auto no-scrollbar bg-white rounded-t-xl px-2">
          {tabs.map((tab) => (
            <div 
              key={tab.id}
              onClick={() => setActiveTabId(tab.id)}
