              </div>
            )}
          </div>

          <nav className="space-y-2">
            <button 
              className={`w-full flex items-center gap-3 p-3 rounded-xl transition-all group ${!isSidebarOpen ? 'justify-center' : 'px-4'} bg-slate-50 dark:bg-slate-800/50 text-slate-900 dark:text-white`}
