                    <label className="text-[8px] font-black text-slate-400 uppercase tracking-widest">Nova Senha</label>
                    <div className="relative">
                      <Key size={12} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                      <input 
