        </header>

        <main className="p-10 pt-4 space-y-8 max-w-6xl w-full mx-auto">

          <div className="flex items-center border-b border-slate-200 dark:border-slate-800 overflow-x-auto no-scrollbar gap-2">
            {tabs.map((tab) => (
              <div 
