              items.map((item) => (
                <tr key={item.id} className={`hover:bg-blue-50/30 dark:hover:bg-blue-500/5 transition-colors group ${item.status === 'paid' ? 'bg-slate-50/30 dark:bg-slate-800/30 opacity-60' : ''}`}>
