const generateSystemInstruction = (maxCompromise: number) => `
Você é o "Master Finance", assistente de gestão de fluxo de caixa.
Sua função é analisar dados financeiros e gerar um Resumo Executivo e Status de Saúde.

LOGICA DE CÁLCULO RIGOROSA:
1. Gasto Total = Soma de todos os itens de saída (expenses).
2. Entradas (Trabalho) = Itens de entrada (income). Representa o salário líquido.
3. Entradas (Terceiros) = Itens neutros (neutral). Tratadas como compensação. NÃO somar como renda disponível.
4. Percentual de Comprometimento = Gasto Total / Entradas (Trabalho). 
   IMPORTANTE: Retorne este valor SEMPRE como um decimal (ex: 0.7014 para 70.14%).
5. LIMITE DE SEGURANÇA: O usuário definiu que o limite ideal de gastos é ${(maxCompromise * 100).toFixed(0)}% da renda.
6. ALERTA DE RISCO: Se o comprometimento for maior que ${(maxCompromise * 100).toFixed(0)}%, o campo 'alertMessage' DEVE conter o aviso de risco. Se for menor, o campo deve ser null.

STATUS:
- Saudável: Comprometimento <= ${(maxCompromise * 0.7).toFixed(2)}
- Atenção: Comprometimento > ${(maxCompromise * 0.7).toFixed(2)} e <= ${maxCompromise.toFixed(2)}
- Crítico: Comprometimento > ${maxCompromise.toFixed(2)}

TOM DE VOZ: Profissional, direto, objetivo e levemente analítico.
RETORNE APENAS JSON.
`;

export async function analyzeFinanceData(items: FinanceItem[], categories: Category[], maxCompromise: number): Promise<FinanceAnalysis> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const incomeCats = categories.filter(c => c.type === 'income').map(c => c.id);
  const expenseCats = categories.filter(c => c.type === 'expense').map(c => c.id);

  const income = items.filter(i => incomeCats.includes(i.category)).reduce((a, b) => a + b.value, 0);
  const expenses = items.filter(i => expenseCats.includes(i.category)).reduce((a, b) => a + b.value, 0);
  const expectedRatio = income > 0 ? expenses / income : (expenses > 0 ? 1 : 0);

  const prompt = `Analise estes dados: ${JSON.stringify(items)}. O Gasto Total é ${expenses} e a Renda é ${income}. Calcule o comprometimento exato baseado no limite de ${maxCompromise}.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: prompt,
    config: {
      systemInstruction: generateSystemInstruction(maxCompromise),
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          summary: {
            type: Type.OBJECT,
            properties: {
              totalWorkIncome: { type: Type.NUMBER },
              totalExpenses: { type: Type.NUMBER },
              remainingBalance: { type: Type.NUMBER },
              compromisePercentage: { type: Type.NUMBER, description: "Ratio decimal (ex: 0.75 for 75%)" },
              status: { type: Type.STRING },
              alertMessage: { type: Type.STRING, nullable: true }
            },
            required: ["totalWorkIncome", "totalExpenses", "remainingBalance", "compromisePercentage", "status"],
          }
        },
        required: ["summary"]
      }
    }
  });

  const data = JSON.parse(response.text.trim());

  // Sanitização rigorosa para evitar a string "null"
  if (data.summary.alertMessage === "null" || data.summary.alertMessage === "") {
    data.summary.alertMessage = null;
  }

  const aiVal = data.summary.compromisePercentage;

  if (expectedRatio > 0) {
    const diffToRatio = Math.abs(aiVal - expectedRatio);
    const diffToPercentage = Math.abs((aiVal / 100) - expectedRatio);
    if (diffToPercentage < diffToRatio && aiVal > 1) {
      data.summary.compromisePercentage = aiVal / 100;
    }
  } else if (aiVal > 1 && expenses <= income) {
      data.summary.compromisePercentage = aiVal / 100;
  }

  return {
    ...data,
    analysisDate: new Date().toLocaleDateString('pt-BR')
  };
}

export async function parseNaturalLanguage(text: string, categories: Category[]): Promise<Partial<FinanceItem>[]> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const categoryInstructions = categories.map(c => `${c.id} (${c.name})`).join(", ");

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Extraia os dados deste texto: "${text}". Categorias permitidas: ${categoryInstructions}`,
    config: {
      systemInstruction: "Extraia itens financeiros e categorize-os corretamente baseado nas categorias fornecidas.",
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            description: { type: Type.STRING },
            value: { type: Type.NUMBER },
            category: { type: Type.STRING },
            paidInstallments: { type: Type.NUMBER },
            totalInstallments: { type: Type.NUMBER },
          },
          required: ["description", "value", "category"]
        }
      }
    }
  });
  return JSON.parse(response.text.trim());
}

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Calculator, Plus, AlertTriangle, Trash2, RefreshCw, CheckCircle2, 
  LogOut, User, ShieldCheck, Sun, Moon, LayoutDashboard, Settings, 
  HelpCircle, ChevronRight, ChevronLeft, Lock, Key, Copy, History, 
  Menu, X, Edit2, Percent, List, Save
} from 'lucide-react';
import { FinanceItem, HealthStatus, FinanceAnalysis, Ledger, Category, FinanceSettings } from './types';
import ExpenseTable from './components/ExpenseTable';
import AuthForm from './components/AuthForm';
import { analyzeFinanceData } from './services/geminiService';
import { saveUserData, loadUserData, auth, onAuthStateChanged, signOut, updatePassword } from './firebase';

const DEFAULT_CATEGORIES: Category[] = [
  { id: 'house', name: 'Casa', icon: '🏠', type: 'expense' },
  { id: 'fixed', name: 'Mensal Fixa', icon: '📅', type: 'expense' },
  { id: 'work', name: 'Trabalho', icon: '📥', type: 'income' },
  { id: 'thirdParty', name: 'Terceiros', icon: '💳', type: 'neutral' }
];

const App: React.FC = () => {
  const [user, setUser] = useState<any>(null);
  const [tabs, setTabs] = useState<Ledger[]>([]);
  const [settings, setSettings] = useState<FinanceSettings>({
    maxCompromisePercentage: 0.8,
    categories: DEFAULT_CATEGORIES
  });

  const [activeTabId, setActiveTabId] = useState<string>('');
  const [syncStatus, setSyncStatus] = useState<'synced' | 'syncing' | 'error' | 'local'>('syncing');
  const [loading, setLoading] = useState(true);
  const [analysisLoading, setAnalysisLoading] = useState(false);
  const [analysis, setAnalysis] = useState<FinanceAnalysis | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(window.innerWidth >= 1024);
  const [theme, setTheme] = useState<'light' | 'dark'>(() => (localStorage.getItem('theme') as 'light' | 'dark') || 'dark');
  const [showSettings, setShowSettings] = useState(false);

  // States para Auth/Password
  const [showPasswordForm, setShowPasswordForm] = useState(false);
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [pwdLoading, setPwdLoading] = useState(false);
  const [pwdMsg, setPwdMsg] = useState({ type: '', text: '' });

  // States para Novo Item Manual
  const [mDesc, setMDesc] = useState('');
  const [mVal, setMVal] = useState('');
  const [mCat, setMCat] = useState<string>('house');
  const [mInstPaid, setMInstPaid] = useState('');
  const [mInstTotal, setMInstTotal] = useState('');

  // States para Gestão de Categorias
  const [newCatName, setNewCatName] = useState('');
  const [newCatIcon, setNewCatIcon] = useState('🏷️');
  const [newCatType, setNewCatType] = useState<'income' | 'expense' | 'neutral'>('expense');

  useEffect(() => {
    theme === 'dark' ? document.documentElement.classList.add('dark') : document.documentElement.classList.remove('dark');
    localStorage.setItem('theme', theme);
  }, [theme]);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      if (!currentUser) {
        setUser(null); setTabs([]); setActiveTabId(''); setAnalysis(null); setLoading(false);
      } else {
        setUser(currentUser); initData();
      }
    });
    return () => unsubscribe();
  }, []);

  const initData = async () => {
    setLoading(true);
    try {
      const data = await loadUserData();
      if (data) {
        if (data.tabs && data.tabs.length > 0) {
          setTabs(data.tabs);
          setActiveTabId(data.tabs[0].id);
        }
        if (data.settings) {
          setSettings(data.settings);
        }
        setSyncStatus('synced');
      } else {
        const defaultTab: Ledger = { id: 'tab-' + Date.now(), name: 'Minha Planilha', month: new Date().getMonth() + 1, year: new Date().getFullYear(), items: [] };
        setTabs([defaultTab]); setActiveTabId(defaultTab.id); setSyncStatus('local');
      }
    } catch (e) { setSyncStatus('error'); } finally { setLoading(false); }
  };

  useEffect(() => {
    if (loading || tabs.length === 0 || !user) return;
    setSyncStatus('syncing');
    const timeout = setTimeout(async () => {
      try {
        await saveUserData(tabs, settings);
        setSyncStatus('synced');
      } catch (e) { setSyncStatus('error'); }
    }, 2000);
    return () => clearTimeout(timeout);
  }, [tabs, settings, loading, user]);

  const activeTab = useMemo(() => tabs.find(t => t.id === activeTabId) || tabs[0], [tabs, activeTabId]);

  const updateItem = (id: string, updates: Partial<FinanceItem>) => {
    setTabs(prev => prev.map(tab => tab.id === activeTabId ? { ...tab, items: tab.items.map(i => i.id === id ? { ...i, ...updates } : i) } : tab));
  };

  const removeItem = (id: string) => {
    setTabs(prev => prev.map(tab => tab.id === activeTabId ? { ...tab, items: tab.items.filter(i => i.id !== id) } : tab));
  };

  const handleManualValueChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const digits = e.target.value.replace(/\D/g, '');
    if (!digits) { setMVal(''); return; }
    const amount = parseInt(digits) / 100;
    setMVal(new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(amount));
  };

  const addManualItem = () => {
    const numericValue = parseFloat(mVal.replace(/[^\d,]/g, '').replace(',', '.')) || 0;
    if (!mDesc || numericValue < 0) return;
    const newItem: FinanceItem = {
      id: 'item-' + Math.random().toString(36).substr(2, 9),
      description: mDesc, value: numericValue, category: mCat,
      paidInstallments: mInstPaid ? parseInt(mInstPaid) : undefined,
      totalInstallments: mInstTotal ? parseInt(mInstTotal) : undefined,
      status: 'pending'
    };
    setTabs(prev => prev.map(tab => tab.id === activeTabId ? { ...tab, items: [...tab.items, newItem] } : tab));
    setMDesc(''); setMVal(''); setMInstPaid(''); setMInstTotal('');
  };

  const addNewTab = () => {
    const newTab: Ledger = { id: 'tab-' + Date.now(), name: 'Nova Planilha', month: new Date().getMonth() + 1, year: new Date().getFullYear(), items: [] };
    setTabs(prev => [...prev, newTab]); setActiveTabId(newTab.id);
  };

  const renameTab = (id: string, currentName: string) => {
    const newName = prompt("Renomear planilha para:", currentName);
    if (newName?.trim()) setTabs(prev => prev.map(t => t.id === id ? { ...t, name: newName.trim() } : t));
  };

  const duplicateTab = (idToDuplicate: string) => {
    const tabToCopy = tabs.find(t => t.id === idToDuplicate);
    if (!tabToCopy) return;
    const newTab: Ledger = { ...tabToCopy, id: 'tab-' + Date.now(), name: `${tabToCopy.name} (Cópia)`, items: tabToCopy.items.map(i => ({ ...i, id: 'item-' + Math.random().toString(36).substr(2, 9) })) };
    setTabs(prev => [...prev, newTab]); setActiveTabId(newTab.id);
  };

  const deleteTab = (idToDelete: string) => {
    if (tabs.length <= 1) return alert("Não é possível excluir a única planilha.");
    if (window.confirm("Deseja realmente excluir permanentemente esta planilha?")) {
      const newTabs = tabs.filter(t => t.id !== idToDelete);
      if (idToDelete === activeTabId) setActiveTabId(newTabs[0].id);
      setTabs(newTabs);
    }
  };

  const totals = useMemo(() => {
    const items = activeTab?.items || [];
    const incomeCats = settings.categories.filter(c => c.type === 'income').map(c => c.id);
    const expenseCats = settings.categories.filter(c => c.type === 'expense').map(c => c.id);
    const neutralCats = settings.categories.filter(c => c.type === 'neutral').map(c => c.id);

    const workIncome = items.filter(i => incomeCats.includes(i.category)).reduce((a, b) => a + b.value, 0);
    const neutralIncome = items.filter(i => neutralCats.includes(i.category)).reduce((a, b) => a + b.value, 0);
    const totalEntrance = workIncome + neutralIncome;

    const totalExpenses = items.filter(i => expenseCats.includes(i.category)).reduce((a, b) => a + b.value, 0);
    const paidExpenses = items.filter(i => expenseCats.includes(i.category) && i.status === 'paid').reduce((a, b) => a + b.value, 0);
    const pendingExpenses = items.filter(i => expenseCats.includes(i.category) && i.status === 'pending').reduce((a, b) => a + b.value, 0);

    return { workIncome, neutralIncome, totalEntrance, totalExpenses, paidExpenses, pendingExpenses };
  }, [activeTab, settings]);

  const runAnalysis = async () => {
    if (!activeTab || activeTab.items.length === 0) return;
    setAnalysisLoading(true);
    try {
      const result = await analyzeFinanceData(activeTab.items, settings.categories, settings.maxCompromisePercentage);
      setAnalysis(result);
    } catch (err) { 
      console.error(err);
      alert('Erro na análise do sistema Master.'); 
    } finally { setAnalysisLoading(false); }
  };

  const handleUpdatePassword = async () => {
    setPwdMsg({ type: '', text: '' });
    if (newPassword !== confirmPassword) return setPwdMsg({ type: 'error', text: 'Senhas não coincidem.' });
    setPwdLoading(true);
    try {
      if (auth.currentUser) await updatePassword(auth.currentUser, newPassword);
      setPwdMsg({ type: 'success', text: 'Senha atualizada!' });
      setNewPassword(''); setConfirmPassword('');
      setTimeout(() => setShowPasswordForm(false), 2000);
    } catch (err: any) { setPwdMsg({ type: 'error', text: 'Erro ao atualizar.' }); } finally { setPwdLoading(false); }
  };

  const addCategory = () => {
    if (!newCatName.trim()) return;
    const id = 'cat-' + Date.now(); // ID único persistente
    setSettings(prev => ({ ...prev, categories: [...prev.categories, { id, name: newCatName.trim(), icon: newCatIcon, type: newCatType }] }));
    setNewCatName('');
  };

  const editCategory = (id: string, currentName: string) => {
    const newName = prompt("Renomear fluxo para:", currentName);
    if (newName?.trim()) {
      setSettings(prev => ({
        ...prev,
        categories: prev.categories.map(c => c.id === id ? { ...c, name: newName.trim() } : c)
      }));
    }
  };

  const removeCategory = (id: string) => {
    if (settings.categories.length <= 1) return alert("Mínimo de uma categoria necessária.");
    if (window.confirm("Deseja remover este fluxo? Itens vinculados continuarão existindo mas sem categoria definida.")) {
      setSettings(prev => ({ ...prev, categories: prev.categories.filter(c => c.id !== id) }));
    }
  };

  const fmt = (v: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v);

  if (!user) return <AuthForm theme={theme} />;
  if (loading) return (
    <div className="h-screen w-full flex flex-col items-center justify-center bg-slate-900 text-white font-black text-[10px] tracking-[0.4em] uppercase">
      <RefreshCw className="animate-spin mb-4 text-blue-500" size={32} /> Iniciando Master Engine...
    </div>
  );

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-950 flex font-sans text-slate-900 dark:text-slate-100 transition-colors duration-300">
      <aside className={`bg-white dark:bg-slate-900 border-r border-slate-200 dark:border-slate-800 flex flex-col fixed h-full z-50 transition-all duration-300 ${isSidebarOpen ? 'w-[280px]' : 'w-0 lg:w-[80px] overflow-hidden'}`}>
        <div className="p-6">
          <div className="flex items-center gap-3 mb-10 transition-all">
            <div className="w-10 h-10 bg-slate-900 dark:bg-blue-600 rounded-xl flex items-center justify-center font-black text-white text-sm shadow-lg">MF</div>
            {isSidebarOpen && <div className="animate-in fade-in duration-300"><h1 className="text-xs font-black uppercase tracking-[0.2em]">Master Finance</h1><span className="text-[8px] font-bold text-slate-400 uppercase tracking-widest">Enterprise Edition</span></div>}
          </div>
          <nav className="space-y-2">
            <button onClick={() => setShowSettings(false)} className={`w-full flex items-center gap-3 p-3 rounded-xl transition-all ${!showSettings ? 'bg-slate-50 dark:bg-slate-800/50 text-blue-500' : 'text-slate-400'}`}>
              <LayoutDashboard size={20} />{isSidebarOpen && <span className="text-[10px] font-black uppercase tracking-widest">Dashboard</span>}
            </button>
            <button onClick={() => setShowSettings(true)} className={`w-full flex items-center gap-3 p-3 rounded-xl transition-all ${showSettings ? 'bg-slate-50 dark:bg-slate-800/50 text-blue-500' : 'text-slate-400'}`}>
              <Settings size={20} />{isSidebarOpen && <span className="text-[10px] font-black uppercase tracking-widest">Ajustes</span>}
            </button>
          </nav>
        </div>
        <div className="mt-auto p-4 space-y-4">
           <button onClick={() => signOut(auth)} className="w-full flex items-center gap-2 py-3.5 bg-rose-50 dark:bg-rose-500/10 text-rose-600 rounded-xl text-[10px] font-black uppercase tracking-widest justify-center transition-colors hover:bg-rose-100 dark:hover:bg-rose-500/20"><LogOut size={16} /> {isSidebarOpen && "Sair"}</button>
        </div>
      </aside>

      <div className={`flex-1 flex flex-col transition-all duration-300 ${isSidebarOpen ? 'lg:ml-[280px]' : 'lg:ml-[80px]'} ml-0`}>
        <header className="h-20 flex items-center justify-between px-10 sticky top-0 z-40 bg-slate-50/80 dark:bg-slate-950/80 backdrop-blur-md border-b border-slate-100 dark:border-slate-800">
           <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="p-2 text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg">{isSidebarOpen ? <X size={20} /> : <Menu size={20} />}</button>
           <div className="flex items-center gap-4">
             <div className="flex items-center gap-2 bg-emerald-50 dark:bg-emerald-500/10 px-3 py-1.5 rounded-full border border-emerald-100 dark:border-emerald-500/20 text-[9px] font-black text-emerald-600 uppercase tracking-widest"><ShieldCheck size={12} /> Sessão Segura</div>
             <button onClick={() => setTheme(theme === 'light' ? 'dark' : 'light')} className="p-2 text-slate-400 hover:text-blue-500 transition-colors">{theme === 'light' ? <Sun size={20} /> : <Moon size={20} />}</button>
           </div>
        </header>

        <main className="p-10 pt-4 space-y-8 max-w-6xl w-full mx-auto">
          {showSettings ? (
            <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 space-y-10">
              <div className="flex items-center justify-between">
                <div><h1 className="text-2xl font-black uppercase tracking-tighter">Configurações Gerais</h1><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Parametrização do sistema Master</p></div>
                <button onClick={() => setShowSettings(false)} className="bg-slate-900 dark:bg-blue-600 text-white px-6 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest shadow-lg shadow-blue-500/20 active:scale-95 transition-all">Salvar e Voltar</button>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {/* Limite de Gasto */}
                <div className="bg-white dark:bg-slate-900 p-8 rounded-2xl border border-slate-200 dark:border-slate-800 space-y-6 shadow-sm">
                  <div className="flex items-center gap-3 text-blue-500"><Percent size={20} /><h3 className="text-xs font-black uppercase tracking-widest">Limite de Comprometimento</h3></div>
                  <div className="space-y-4">
                    <p className="text-[10px] font-bold text-slate-400 uppercase leading-relaxed">Defina a porcentagem (%) máxima do seu salário que pode ser usada para despesas. O diagnóstico usará este valor como régua.</p>
                    <div className="flex items-center gap-4">
                      <input type="range" min="0.1" max="1.0" step="0.05" value={settings.maxCompromisePercentage} onChange={e => setSettings(prev => ({ ...prev, maxCompromisePercentage: parseFloat(e.target.value) }))} className="flex-1 h-2 bg-slate-100 dark:bg-slate-800 rounded-lg appearance-none cursor-pointer accent-blue-500" />
                      <span className="text-lg font-mono font-black text-blue-500">{(settings.maxCompromisePercentage * 100).toFixed(0)}%</span>
                    </div>
                  </div>
                </div>

                {/* Gestão de Senha */}
                <div className="bg-white dark:bg-slate-900 p-8 rounded-2xl border border-slate-200 dark:border-slate-800 space-y-6 shadow-sm">
                  <div className="flex items-center gap-3 text-amber-500"><Lock size={20} /><h3 className="text-xs font-black uppercase tracking-widest">Segurança da Conta</h3></div>
                  <div className="space-y-4">
                    <input type="password" placeholder="Nova Senha" value={newPassword} onChange={e => setNewPassword(e.target.value)} className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl px-4 py-3 text-xs font-bold outline-none" />
                    <input type="password" placeholder="Confirme a Senha" value={confirmPassword} onChange={e => setConfirmPassword(e.target.value)} className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl px-4 py-3 text-xs font-bold outline-none" />
                    <button onClick={handleUpdatePassword} disabled={pwdLoading} className="w-full bg-slate-900 dark:bg-slate-800 text-white py-3 rounded-xl text-[9px] font-black uppercase tracking-widest transition-colors hover:bg-slate-800 active:scale-95">{pwdLoading ? "Salvando..." : "Atualizar Credenciais"}</button>
                    {pwdMsg.text && <p className={`text-[8px] font-black uppercase text-center ${pwdMsg.type === 'error' ? 'text-rose-500' : 'text-emerald-500'}`}>{pwdMsg.text}</p>}
                  </div>
                </div>
              </div>

              {/* Gestão de Categorias */}
              <div className="bg-white dark:bg-slate-900 p-8 rounded-2xl border border-slate-200 dark:border-slate-800 space-y-8 shadow-sm">
                <div className="flex items-center gap-3 text-emerald-500"><List size={20} /><h3 className="text-xs font-black uppercase tracking-widest">Gerenciador de Fluxos (Categorias)</h3></div>

                <div className="grid grid-cols-1 md:grid-cols-4 gap-4 items-end">
                  <div><label className="text-[8px] font-black text-slate-400 uppercase mb-2 block">Ícone</label><input type="text" value={newCatIcon} onChange={e => setNewCatIcon(e.target.value)} className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 p-3 rounded-xl text-center" /></div>
                  <div className="md:col-span-2"><label className="text-[8px] font-black text-slate-400 uppercase mb-2 block">Nome do Fluxo</label><input type="text" placeholder="Ex: Investimentos" value={newCatName} onChange={e => setNewCatName(e.target.value)} className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 p-3 rounded-xl text-xs font-bold" /></div>
                  <div><label className="text-[8px] font-black text-slate-400 uppercase mb-2 block">Tipo</label><select value={newCatType} onChange={e => setNewCatType(e.target.value as any)} className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 p-3 rounded-xl text-xs font-bold"><option value="expense">Saída</option><option value="income">Entrada</option><option value="neutral">Neutro</option></select></div>
                  <button onClick={addCategory} className="w-full md:col-span-4 bg-emerald-500 text-white py-3 rounded-xl text-[10px] font-black uppercase tracking-widest flex items-center justify-center gap-2 active:scale-95 transition-all"><Plus size={16} /> Adicionar Novo Fluxo</button>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                  {settings.categories.map(cat => (
                    <div key={cat.id} className="p-4 bg-slate-50 dark:bg-slate-800/50 rounded-xl border border-slate-200 dark:border-slate-700 flex items-center justify-between group">
                      <div className="flex items-center gap-3">
                        <span className="text-xl">{cat.icon}</span>
                        <div><p className="text-[10px] font-black uppercase tracking-tight">{cat.name}</p><p className={`text-[8px] font-black uppercase ${cat.type === 'income' ? 'text-emerald-500' : cat.type === 'expense' ? 'text-rose-500' : 'text-blue-500'}`}>{cat.type}</p></div>
                      </div>
                      <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                        <button onClick={() => editCategory(cat.id, cat.name)} className="text-slate-400 hover:text-blue-500 transition-colors p-1" title="Editar nome"><Edit2 size={14} /></button>
                        <button onClick={() => removeCategory(cat.id)} className="text-slate-400 hover:text-rose-500 transition-colors p-1" title="Excluir fluxo"><Trash2 size={14} /></button>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          ) : (
            <>
              <div className="flex items-center border-b border-slate-200 dark:border-slate-800 overflow-x-auto gap-2 no-scrollbar">
                {tabs.map((tab) => (
                  <div key={tab.id} onClick={() => setActiveTabId(tab.id)} className={`flex items-center gap-2 px-5 py-4 border-b-2 transition-all cursor-pointer whitespace-nowrap group ${activeTabId === tab.id ? 'border-slate-900 dark:border-blue-500 text-slate-900 dark:text-white' : 'border-transparent text-slate-400'}`}>
                    <span className="text-[10px] font-black uppercase tracking-widest">{tab.name}</span>
                    <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity"><button onClick={(e) => { e.stopPropagation(); renameTab(tab.id, tab.name); }} className="p-1 hover:text-blue-500"><Edit2 size={11} /></button><button onClick={(e) => { e.stopPropagation(); duplicateTab(tab.id); }} className="p-1 hover:text-blue-500"><Copy size={11} /></button>{tabs.length > 1 && <button onClick={(e) => { e.stopPropagation(); deleteTab(tab.id); }} className="p-1 hover:text-rose-600"><Trash2 size={11} /></button>}</div>
                  </div>
                ))}
                <button onClick={addNewTab} className="px-6 py-4 text-slate-400 hover:text-blue-600 transition-all flex items-center gap-2 border-b-2 border-transparent"><Plus size={14} /><span className="text-[10px] font-black uppercase tracking-widest">Nova Planilha</span></button>
              </div>

              <section className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl p-8 shadow-sm">
                <div className="grid grid-cols-1 md:grid-cols-12 gap-6 items-end">
                  <div className="md:col-span-2"><label className="text-[9px] font-black text-slate-400 uppercase mb-2 block tracking-widest">Fluxo</label><select value={mCat} onChange={e => setMCat(e.target.value)} className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl px-4 py-3.5 text-xs font-bold outline-none focus:ring-2 focus:ring-blue-500/20">{settings.categories.map(c => <option key={c.id} value={c.id}>{c.icon} {c.name}</option>)}</select></div>
                  <div className="md:col-span-4"><label className="text-[9px] font-black text-slate-400 uppercase mb-2 block tracking-widest">Identificação</label><input type="text" placeholder="Ex: Aluguel" value={mDesc} onChange={e => setMDesc(e.target.value)} className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl px-4 py-3.5 text-xs font-bold outline-none focus:ring-2 focus:ring-blue-500/20" /></div>
                  <div className="md:col-span-2"><label className="text-[9px] font-black text-slate-400 uppercase mb-2 block tracking-widest">Montante</label><input type="text" placeholder="R$ 0,00" value={mVal} onChange={handleManualValueChange} className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl px-4 py-3.5 text-xs font-mono font-bold outline-none focus:ring-2 focus:ring-blue-500/20" /></div>
                  <div className="md:col-span-2"><label className="text-[9px] font-black text-slate-400 uppercase mb-2 block tracking-widest">Parcelas</label><div className="flex items-center bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl px-3 py-3 text-xs focus-within:ring-2 focus-within:ring-blue-500/20"><input type="number" placeholder="0" value={mInstPaid} onChange={e => setMInstPaid(e.target.value)} className="w-full text-right bg-transparent outline-none font-bold" /><span className="px-3 font-black text-slate-300">/</span><input type="number" placeholder="0" value={mInstTotal} onChange={e => setMInstTotal(e.target.value)} className="w-full text-left bg-transparent outline-none font-bold" /></div></div>
                  <div className="md:col-span-2"><button onClick={addManualItem} className="w-full bg-slate-900 dark:bg-blue-600 text-white font-black py-4 rounded-xl text-[10px] uppercase tracking-widest hover:bg-slate-800 transition-all shadow-lg active:scale-95">Registrar</button></div>
                </div>
              </section>

              <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
                <div className="lg:col-span-8 space-y-8">
                  {settings.categories.map(cat => {
                    const catItems = activeTab?.items.filter(i => i.category === cat.id) || [];
                    return <ExpenseTable key={cat.id} title={cat.name} icon={cat.icon} type={cat.type === 'income' ? 'income' : cat.type === 'expense' ? 'expense' : 'neutral'} showStatus={cat.type === 'expense'} items={catItems} onRemove={removeItem} onUpdate={updateItem} />;
                  })}

                  <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl overflow-hidden shadow-sm grid grid-cols-2 md:grid-cols-4 divide-y md:divide-y-0 md:divide-x divide-slate-100 dark:divide-slate-800">
                    <div className="p-6 text-center"><p className="text-[8px] font-black text-slate-400 uppercase mb-2 tracking-widest">TOTAL SAÍDA</p><p className="text-sm font-mono font-black text-rose-600 dark:text-rose-400">{fmt(totals.totalExpenses)}</p></div>
                    <div className="p-6 text-center"><p className="text-[8px] font-black text-slate-400 uppercase mb-2 tracking-widest">TOTAL DE ENTRADA</p><p className="text-sm font-mono font-black text-emerald-600 dark:text-emerald-400">{fmt(totals.totalEntrance)}</p></div>
                    <div className="p-6 text-center"><p className="text-[8px] font-black text-slate-400 uppercase mb-2 tracking-widest">PAGAS</p><p className="text-sm font-mono font-black text-blue-600 dark:text-blue-400">{fmt(totals.paidExpenses)}</p></div>
                    <div className="p-6 text-center bg-slate-50/50 dark:bg-slate-800/20"><p className="text-[8px] font-black text-slate-400 uppercase mb-2 tracking-widest">EM ABERTO</p><p className="text-sm font-mono font-black text-amber-600 dark:text-amber-400">{fmt(totals.pendingExpenses)}</p></div>
                  </div>
                </div>

                <div className="lg:col-span-4 space-y-6">
                  <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl p-8 shadow-sm lg:sticky lg:top-24">
                    <button onClick={runAnalysis} disabled={analysisLoading || !activeTab || activeTab.items.length === 0} className="w-full bg-slate-900 dark:bg-blue-600 text-white font-black py-4 rounded-xl text-[10px] uppercase tracking-widest hover:bg-slate-800 transition-all flex items-center justify-center gap-4 active:scale-95 disabled:opacity-50 shadow-xl shadow-blue-500/10">
                      {analysisLoading ? <RefreshCw className="animate-spin" size={16} /> : <><Calculator size={18}/> Gerar Diagnóstico</>}
                    </button>
                    {analysis && (
                      <div className="mt-8 pt-8 border-t border-slate-100 dark:border-slate-800 animate-in fade-in slide-in-from-bottom-4 duration-500">
                        <h3 className={`text-2xl font-black uppercase tracking-tighter mb-6 ${analysis.summary.status === HealthStatus.HEALTHY ? 'text-emerald-600' : analysis.summary.status === HealthStatus.ATTENTION ? 'text-amber-600' : 'text-rose-700'}`}>{analysis.summary.status}</h3>
                        <div className="space-y-5">
                          <div className="flex justify-between items-center text-[10px] font-black uppercase text-slate-400"><span>Comprometimento</span><span className="text-slate-900 dark:text-white font-mono">{(analysis.summary.compromisePercentage * 100).toFixed(1)}%</span></div>
                          <div className="w-full bg-slate-100 dark:bg-slate-800 h-2 rounded-full overflow-hidden"><div className={`h-full transition-all duration-1000 ${analysis.summary.compromisePercentage > settings.maxCompromisePercentage ? 'bg-rose-500' : 'bg-emerald-500'}`} style={{ width: `${Math.min(analysis.summary.compromisePercentage * 100, 100)}%` }} /></div>
                        </div>
                        {analysis.summary.alertMessage && analysis.summary.alertMessage !== 'null' && (
                          <div className="mt-6 p-5 bg-rose-50 dark:bg-rose-500/10 text-rose-700 dark:text-rose-400 text-[10px] font-bold uppercase rounded-xl border border-rose-100 dark:border-rose-500/20 flex gap-3 animate-in fade-in duration-300">
                            <AlertTriangle size={16} className="shrink-0 mt-0.5" />
                            {analysis.summary.alertMessage.replace(/\*\*/g, '')}
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                </div>
              </div>
            </>
          )}
        </main>
        <footer className="mt-auto h-16 flex items-center justify-center text-[9px] font-black text-slate-300 dark:text-slate-700 uppercase tracking-[0.5em] border-t border-slate-100 dark:border-slate-900">Master Finance Engine • 2026 • AI Powered</footer>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
// Fixed: Member is now correctly exported from types.ts
import { Member, Ledger, FinanceItem, FinanceAnalysis, HealthStatus, Category } from '../types';
import { Plus, Copy, Trash2, Calculator, History, CheckCircle, Clock, Tag, DollarSign, Type as TypeIcon, Sparkles, AlertTriangle } from 'lucide-react';
import ExpenseTable from './ExpenseTable';
import { analyzeFinanceData, parseNaturalLanguage } from '../services/geminiService';

interface MemberViewProps {
  member: Member;
  onUpdateLedgers: (ledgers: Ledger[]) => void;
  filter: { month: number; year: number };
  onRemove: () => void;
  // Added missing props required for Gemini service calls and dynamic UI
  categories: Category[];
  maxCompromise: number;
}

const MemberView: React.FC<MemberViewProps> = ({ member, onUpdateLedgers, filter, onRemove, categories, maxCompromise }) => {
  // Garantir que a planilha ativa corresponda ao filtro global se possível, ou seja a primeira
  const filteredLedgers = useMemo(() => {
    return member.ledgers.filter(l => l.month === filter.month && l.year === filter.year);
  }, [member.ledgers, filter]);

  const [activeLedgerId, setActiveLedgerId] = useState<string>('');

  useEffect(() => {
    if (filteredLedgers.length > 0) {
      setActiveLedgerId(filteredLedgers[0].id);
    } else if (member.ledgers.length > 0) {
      setActiveLedgerId(member.ledgers[0].id);
    }
  }, [member.id, filter.month, filter.year]);

  const [analysis, setAnalysis] = useState<FinanceAnalysis | null>(null);
  const [loading, setLoading] = useState(false);
  const [parsing, setParsing] = useState(false);
  const [nlpText, setNlpText] = useState('');

  // Form States - Updated to support dynamic categories
  const [mDesc, setMDesc] = useState('');
  const [mVal, setMVal] = useState('');
  const [mCat, setMCat] = useState<string>(categories[0]?.id || 'house');
  const [mInstPaid, setMInstPaid] = useState('');
  const [mInstTotal, setMInstTotal] = useState('');

  const activeLedger = useMemo(() => {
    return member.ledgers.find(l => l.id === activeLedgerId) || member.ledgers[0];
  }, [member, activeLedgerId]);

  const items = activeLedger?.items || [];

  const updateItem = (id: string, updates: Partial<FinanceItem>) => {
    const newLedgers = member.ledgers.map(l => 
      l.id === activeLedgerId 
        ? { ...l, items: l.items.map(i => i.id === id ? { ...i, ...updates } : i) } 
        : l
    );
    onUpdateLedgers(newLedgers);
  };

  const removeItem = (id: string) => {
    const newLedgers = member.ledgers.map(l => 
      l.id === activeLedgerId 
        ? { ...l, items: l.items.filter(i => i.id !== id) } 
        : l
    );
    onUpdateLedgers(newLedgers);
  };

  const handleManualValueChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const digits = e.target.value.replace(/\D/g, '');
    if (!digits) { setMVal(''); return; }
    const amount = parseInt(digits) / 100;
    setMVal(new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(amount));
  };

  const addManualItem = () => {
    const numericValue = parseFloat(mVal.replace(/[^\d,]/g, '').replace(',', '.')) || 0;
    if (!mDesc || numericValue < 0) return;
    const newItem: FinanceItem = {
      id: Math.random().toString(36).substr(2, 9),
      description: mDesc,
      value: numericValue,
      category: mCat,
      paidInstallments: mInstPaid ? parseInt(mInstPaid) : undefined,
      totalInstallments: mInstTotal ? parseInt(mInstTotal) : undefined,
      status: 'pending'
    };
    const newLedgers = member.ledgers.map(l => l.id === activeLedgerId ? { ...l, items: [...l.items, newItem] } : l);
    onUpdateLedgers(newLedgers);
    setMDesc(''); setMVal(''); setMInstPaid(''); setMInstTotal('');
  };

  const addLedger = () => {
    const name = prompt("Nome para a nova planilha deste período:");
    if (!name) return;
    const newLedger: Ledger = { id: 'led-' + Date.now(), name, month: filter.month, year: filter.year, items: [] };
    onUpdateLedgers([...member.ledgers, newLedger]);
    setActiveLedgerId(newLedger.id);
  };

  const runAnalysis = async () => {
    if (items.length === 0) return;
    setLoading(true);
    try {
      // Fixed: Added categories and maxCompromise arguments as required by the service
      const result = await analyzeFinanceData(items, categories, maxCompromise);
      setAnalysis(result);
    } catch (err) {
      alert('Erro na análise Master Finance. Verifique sua conexão.');
    } finally {
      setLoading(false);
    }
  };

  const handleNLP = async () => {
    if (!nlpText.trim()) return;
    setParsing(true);
    try {
      // Fixed: Added categories argument as required by the service
      const parsedItems = await parseNaturalLanguage(nlpText, categories);
      const newItems: FinanceItem[] = parsedItems.map(item => ({
        id: Math.random().toString(36).substr(2, 9),
        description: item.description || 'Novo Item',
        value: item.value || 0,
        category: item.category || categories[0]?.id || 'house',
        paidInstallments: item.paidInstallments,
        totalInstallments: item.totalInstallments,
        status: 'pending' as const
      }));

      const newLedgers = member.ledgers.map(l => 
        l.id === activeLedgerId ? { ...l, items: [...l.items, ...newItems] } : l
      );
      onUpdateLedgers(newLedgers);
      setNlpText('');
    } catch (err) {
      alert('Erro ao processar texto com IA.');
    } finally {
      setParsing(false);
    }
  };

  const summaryData = useMemo(() => {
    const expenseCats = categories.filter(c => c.type === 'expense').map(c => c.id);
    const expenses = items.filter(i => expenseCats.includes(i.category));
    const totalPaid = expenses.filter(i => i.status === 'paid').reduce((a, b) => a + b.value, 0);
    const totalPending = expenses.filter(i => i.status === 'pending').reduce((a, b) => a + b.value, 0);
    return { totalPaid, totalPending, paidItems: expenses.filter(i => i.status === 'paid') };
  }, [items, categories]);

  const fmt = (v: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v);

  return (
    <div className="max-w-6xl mx-auto space-y-8 animate-in fade-in slide-in-from-right-4 duration-500 pb-20">
      <div className="flex items-center justify-between border-b border-slate-200 pb-6">
        <div className="flex items-center gap-5">
          <div className="w-14 h-14 bg-slate-900 rounded-2xl flex items-center justify-center font-black text-white text-xl shadow-xl shadow-slate-900/10">
            {member.name.charAt(0).toUpperCase()}
          </div>
          <div>
            <h1 className="text-2xl font-black uppercase tracking-tighter text-slate-800">{member.name}</h1>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mt-1">Gestão de Fluxo de Caixa Individual</p>
          </div>
        </div>
        <button 
          onClick={onRemove} 
          className="text-rose-500 hover:bg-rose-50 px-4 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all border border-transparent hover:border-rose-100"
        >
          Excluir Membro
        </button>
      </div>

      {/* Spreadsheet Tabs */}
      <div className="flex items-center gap-3 overflow-x-auto no-scrollbar pb-2">
        {member.ledgers.map(l => (
          <button
            key={l.id}
            onClick={() => { setActiveLedgerId(l.id); setAnalysis(null); }}
            className={`px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest border transition-all whitespace-nowrap ${activeLedgerId === l.id ? 'bg-slate-900 text-white border-slate-900 shadow-lg shadow-slate-900/20' : 'bg-white text-slate-400 border-slate-200 hover:border-slate-300 hover:text-slate-600'}`}
          >
            {l.name} <span className="ml-2 opacity-40 font-mono">[{l.month}/{l.year}]</span>
          </button>
        ))}
        <button 
          onClick={addLedger} 
          className="flex items-center gap-2 px-4 py-2.5 bg-white border border-slate-200 rounded-xl text-[10px] font-black uppercase tracking-widest text-blue-600 hover:bg-blue-50 hover:border-blue-200 transition-all shadow-sm active:scale-95"
        >
          <Plus size={14} /> Nova Planilha
        </button>
      </div>

      <section className="bg-white border border-slate-200 shadow-sm rounded-2xl overflow-hidden p-6 md:p-8">
        <div className="flex items-center gap-3 mb-8 border-b border-slate-100 pb-4">
          <Plus size={18} className="text-blue-600" />
          <h2 className="text-[11px] font-black text-slate-700 uppercase tracking-[0.2em]">Lançamento Manual Rápido</h2>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-12 gap-5 items-end">
          <div className="md:col-span-2">
            <label className="flex items-center gap-2 text-[10px] font-black text-slate-400 uppercase mb-2 tracking-wide"><Tag size={12} /> Categoria</label>
            <select value={mCat} onChange={e => setMCat(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-xs font-bold focus:ring-4 focus:ring-blue-500/5 focus:border-blue-500 outline-none transition-all cursor-pointer">
              {categories.map(c => (
                <option key={c.id} value={c.id}>{c.icon} {c.name}</option>
              ))}
            </select>
          </div>
          <div className="md:col-span-4">
            <label className="flex items-center gap-2 text-[10px] font-black text-slate-400 uppercase mb-2 tracking-wide"><TypeIcon size={12} /> Descrição</label>
            <input type="text" placeholder="Ex: Mercado mensal" value={mDesc} onChange={e => setMDesc(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-xs focus:ring-4 focus:ring-blue-500/5 focus:border-blue-500 outline-none transition-all" />
          </div>
          <div className="md:col-span-2">
            <label className="flex items-center gap-2 text-[10px] font-black text-slate-400 uppercase mb-2 tracking-wide"><DollarSign size={12} /> Valor</label>
            <input type="text" placeholder="R$ 0,00" value={mVal} onChange={handleManualValueChange} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-xs font-mono font-bold focus:ring-4 focus:ring-blue-500/5 focus:border-blue-500 outline-none transition-all" />
          </div>
          <div className="md:col-span-2">
            <label className="flex items-center gap-2 text-[10px] font-black text-slate-400 uppercase mb-2 tracking-wide"><History size={12} /> Parcelas</label>
            <div className="flex items-center bg-slate-50 border border-slate-200 rounded-xl px-3 py-3 text-xs transition-all focus-within:ring-4 focus-within:ring-blue-500/5 focus-within:border-blue-500">
              <input type="number" placeholder="0" value={mInstPaid} onChange={e => setMInstPaid(e.target.value)} className="w-full text-right bg-transparent outline-none font-bold [appearance:textfield]" />
              <span className="px-3 font-black text-slate-300">/</span>
              <input type="number" placeholder="0" value={mInstTotal} onChange={e => setMInstTotal(e.target.value)} className="w-full text-left bg-transparent outline-none font-bold [appearance:textfield]" />
            </div>
          </div>
          <div className="md:col-span-2">
            <button onClick={addManualItem} className="w-full bg-blue-600 hover:bg-blue-700 text-white font-black py-3.5 rounded-xl text-[10px] uppercase tracking-[0.2em] transition-all shadow-lg shadow-blue-600/20 active:scale-95">Lançar</button>
          </div>
        </div>
      </section>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
        <div className="lg:col-span-8 space-y-8">
          {categories.map(cat => (
            <ExpenseTable 
              key={cat.id} 
              title={cat.name} 
              icon={cat.icon} 
              type={cat.type} 
              showStatus={cat.type === 'expense'} 
              items={items.filter(i => i.category === cat.id)} 
              onRemove={removeItem} 
              onUpdate={updateItem} 
            />
          ))}

          <div className="bg-white border border-slate-200 rounded-2xl overflow-hidden shadow-sm">
            <div className="bg-slate-900 text-white px-8 py-5 flex items-center justify-between">
              <div className="flex items-center gap-4"><CheckCircle size={22} className="text-emerald-400" /><h3 className="text-xs font-black uppercase tracking-[0.2em]">Fluxo de Caixa Real</h3></div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 divide-x divide-slate-100">
               <div className="p-8">
                  <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-6 flex items-center gap-2"><CheckCircle size={14} className="text-emerald-500" /> Itens Liquidados</h4>
                  <div className="space-y-3 max-h-56 overflow-y-auto no-scrollbar mb-6 pr-2">
                     {summaryData.paidItems.length > 0 ? summaryData.paidItems.map(i => (
                       <div key={i.id} className="flex justify-between items-center text-xs py-2 border-b border-slate-50 hover:bg-slate-50 px-2 rounded-lg transition-colors">
                         <span className="font-bold text-slate-600">{i.description}</span>
                         <span className="font-mono font-black text-emerald-600">{fmt(i.value)}</span>
                       </div>
                     )) : (
                       <div className="text-center py-4 text-slate-300 text-[10px] font-bold uppercase tracking-widest italic">Nenhum item pago</div>
                     )}
                  </div>
                  <div className="flex justify-between items-center pt-5 border-t border-slate-200">
                     <span className="text-[11px] font-black uppercase text-slate-900 tracking-wider">Total Pago</span>
                     <span className="text-xl font-mono font-black text-emerald-600">{fmt(summaryData.totalPaid)}</span>
                  </div>
               </div>
               <div className="p-8 bg-slate-50/30">
                  <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-6 flex items-center gap-2"><Clock size={14} className="text-amber-500" /> A Pagar (Pendente)</h4>
                  <div className="p-8 bg-white rounded-2xl border border-slate-200 shadow-sm text-center transform hover:scale-[1.02] transition-transform">
                    <p className="text-[10px] font-black text-slate-400 uppercase mb-2 tracking-widest">Saldo Devedor</p>
                    <p className="text-4xl font-mono font-black text-rose-500 tracking-tighter">{fmt(summaryData.totalPending)}</p>
                  </div>
                  <p className="text-[9px] text-center mt-6 font-bold text-slate-400 uppercase leading-relaxed px-4">Este valor representa tudo o que foi lançado mas ainda não foi marcado como "Pago".</p>
               </div>
            </div>
          </div>
        </div>

        <div className="lg:col-span-4 space-y-6 sticky top-24">
           <button onClick={runAnalysis} disabled={loading || items.length === 0} className="w-full bg-slate-900 text-white font-black py-5 rounded-2xl uppercase text-[11px] tracking-[0.2em] shadow-xl hover:bg-slate-800 transition-all flex items-center justify-center gap-4 disabled:bg-slate-200 active:scale-95 group">
             {loading ? <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : <Calculator size={20} className="group-hover:scale-110 transition-transform" />}
             Gerar Análise Master
           </button>

           {analysis && (
             <div className="bg-white border-2 border-slate-900 p-8 rounded-3xl shadow-2xl animate-in slide-in-from-bottom-4 duration-500 relative overflow-hidden">
                <div className="absolute top-0 right-0 w-24 h-24 bg-slate-900/5 rounded-bl-full -mr-12 -mt-12"></div>
                <span className="text-[10px] font-black uppercase text-slate-400 mb-3 block tracking-widest">Diagnóstico Master Finance</span>
                <h3 className={`text-3xl font-black uppercase tracking-tighter mb-6 ${analysis.summary.status === HealthStatus.HEALTHY ? 'text-emerald-700' : analysis.summary.status === HealthStatus.ATTENTION ? 'text-amber-700' : 'text-rose-700'}`}>{analysis.summary.status}</h3>
                <div className="space-y-5">
                  <div className="flex justify-between text-[11px] font-black uppercase tracking-tight">
                    <span className="text-slate-400">Renda Mensal (Líquida)</span>
                    <span className="text-emerald-600">{fmt(analysis.summary.totalWorkIncome)}</span>
                  </div>
                  <div className="flex justify-between text-[11px] font-black uppercase tracking-tight">
                    <span className="text-slate-400">Gastos Essenciais</span>
                    <span className="text-rose-600">{fmt(analysis.summary.totalExpenses)}</span>
                  </div>
                  <div className="pt-4 border-t border-slate-100 flex justify-between text-sm font-black uppercase">
                    <span className="text-slate-900">Saldo Disponível</span>
                    <span className={analysis.summary.remainingBalance >= 0 ? 'text-blue-600 font-mono' : 'text-rose-600 font-mono'}>{fmt(analysis.summary.remainingBalance)}</span>
                  </div>
                </div>
                {analysis.summary.alertMessage && analysis.summary.alertMessage !== 'null' && (
                  <div className="mt-8 p-4 bg-rose-50 border border-rose-100 rounded-xl text-rose-700 text-[11px] font-bold flex gap-3 items-start leading-relaxed animate-in fade-in duration-300">
                    <AlertTriangle size={16} className="shrink-0 mt-0.5" /> 
                    {analysis.summary.alertMessage.replace(/\*\*/g, '')}
                  </div>
                )}
             </div>
